  `ProductState` int(11) NOT NULL COMMENT '状态',
  `BookingDesc` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预订须知',
  `ProductDesc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '产品说明',
  `CreatedBy` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
