  `ModifiedBy` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `ModifiedTime` datetime(6) NOT NULL,
  `OwnerCode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `Themes` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主题',
  `ImgUrl` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图片',
  `PlanQuota` int(11) NULL DEFAULT NULL COMMENT '计划库存',
  `HoldQuota` int(11) NULL DEFAULT NULL,
  `PriceMode` int(11) NULL DEFAULT NULL COMMENT '报价方式',
  `UsedQuota` int(11) NULL DEFAULT NULL COMMENT '已用库存',
  `StartTime` datetime NULL DEFAULT NULL COMMENT '使用时限-开始',
  `EndTime` datetime NULL DEFAULT NULL COMMENT '使用时限-结束',
  `LimitQuota` int(11) NULL DEFAULT NULL COMMENT '订单限额',
  `BeginBuyTime` datetime NULL DEFAULT NULL COMMENT '下单时限-开始',
  `LastDate` datetime NULL DEFAULT NULL COMMENT '下单时限-结束',
  `PreDays` int(11) NULL DEFAULT NULL,
  `PreTime` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `IsImport` bit(1) NOT NULL,
  `ImportState` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`Id`) USING BTREE,
  UNIQUE INDEX `ProductId`(`ProductId` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

