DROP TABLE IF EXISTS `tptourbalance`;
CREATE TABLE `tptourbalance`  (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `MasterOrderCode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '总单号',
  `Type` int(11) NOT NULL DEFAULT 1 COMMENT '关联产品类型',
  `IsPackage` int(11) NOT NULL DEFAULT 1,
  `ProductType` int(11) NOT NULL DEFAULT 1 COMMENT '产品类型',
  `TeamId` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品组',
  `BranchCode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `SalesTeamId` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售组',
  `SalerCode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售编码',
  `Saler` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售姓名',
  `TourNo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '团号',
  `TourId` int(11) NULL DEFAULT NULL COMMENT '关联TpTourPlan',
  `ProductName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品名称',
  `AuditState` int(11) NOT NULL DEFAULT 0 COMMENT '团单状态',
  `OrderState` int(11) NOT NULL DEFAULT 0 COMMENT '订单状态',
  `OutDate` datetime NULL DEFAULT NULL COMMENT '入园日期-门票',
  `TravelDays` int(11) NOT NULL DEFAULT 0 COMMENT '出行天数-旅游',
  `AgentCode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分销商编码',
  `AgentName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分销商名称',
  `TouristName` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游客姓名',
  `TouristPhone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '游客电话',
  `ContactName` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人姓名',
  `ContactPhone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人电话',
  `ContactEmail` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人电子邮箱',
  `PostCode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮编',
  `DeliveryAddress` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配送地址',
  `YingShou` decimal(18, 2) NOT NULL COMMENT '应收',
  `YiShou` decimal(18, 2) NOT NULL COMMENT '已收',
  `Num` int(11) NOT NULL COMMENT '人数',
  `AuditPax` int(11) NOT NULL COMMENT '成人数',
  `OldPax` int(11) NOT NULL COMMENT '老人数',
  `ChildPax` int(11) NOT NULL COMMENT '儿童人数',
  `TotalCost` decimal(18, 2) NOT NULL COMMENT '总成本',
  `SupplierCode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商-门票',
  `MaoLi` decimal(18, 2) NOT NULL COMMENT '毛利',
  `GuideName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '导游',
  `GuidePhone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '导游手机号-门票',
  `Remarks` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CreatedBy` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `CreatedTime` datetime(6) NOT NULL,
  `ModifiedBy` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `ModifiedTime` datetime(6) NOT NULL,
  `OPAuditBy` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `OPAuditTime` datetime(6) NULL DEFAULT NULL,
  `CWAuditBy` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `CWAuditTime` datetime(6) NULL DEFAULT NULL,
  `OwnerCode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商户编号',
  `IsCopy` bit(1) NOT NULL DEFAULT b'0',
  `IsCancel` int(11) NOT NULL DEFAULT 0,
  `OrderSource` int(11) NOT NULL COMMENT '订单来源',
  `IsneedInvoice` int(11) NOT NULL COMMENT '是否需要发票',
  `ContractType` int(11) NOT NULL COMMENT '签约方式',
  `PaymentStatus` int(11) NOT NULL COMMENT '收款状态',
  `LaterPayDate` datetime NULL DEFAULT NULL COMMENT '最晚支付时间',
  PRIMARY KEY (`Id`) USING BTREE,
  INDEX `MasterOrderCode`(`MasterOrderCode` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 69 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

