INSERT INTO `tpline` VALUES (56, 'L0000056', '2008000003', '南京新加坡5晚6天【测试】', NULL, 6, 5, 10, '3201', '/1/121/', '/1/126/440/', '蜜月游', 1, 4, 3, 'CA', '丰富行程：\r\n★新加坡（鱼尾狮，滨海湾花园，乌节路，政府大厦，维多利亚剧院，伊丽莎白公园，莱佛士铜像，滨海艺术中心）\r\n★马来西亚（三保井-荷兰红屋-圣保罗教堂-波德申-太子城-云顶高原-独立广场-苏丹皇宫）\r\n\r\n住宿全新升级：\r\n★新加坡网评4钻酒店  京华、国际、凯丽或同级\r\n★马来西亚全程国际4星酒店 \r\n★升级1晚波德申海边5钻酒店\r\n\r\n地道美食：\r\n★海南鸡饭，面包鸡，马来手抓饭，各类地道马来小吃让您流连忘返~\r\n\r\n精选航空：南京直飞，梦幻客机   \r\n★新加坡航空旗下酷航787-9，375座超大【梦幻客机】\r\n★南京直飞，不转机，不经停', NULL, '费用包含', '费用不包含', '预订须知', NULL, NULL, NULL, 3, 1, '1611000001', '上海新康辉', NULL, '1811000106', '2019-04-04 12:27:44.597000', '1811000106', '2019-04-04 12:27:44.597000', '1812000007', 'Files/pic/34/20/636517266077155031.jpg', NULL, NULL, '<p>bftgft<img src=\"http://yuanfile.sh-cct.cn/Files/line/L0000056/blog-2.jpg\" class=\"fluid image ui\" style=\"\"></p>', b'1', b'0', 0, b'0');
