INSERT INTO `visa_country_consulardistrict` VALUES (7, 'V130114000105', 'V130114000104', '/27/', '2', '护照签发地为上海、江苏、浙江、安徽、江西以及湖北。如护照签发地不在上述地区，申请者需在上述地区以外工作、生活或学习并提供已有六个月记录的有效暂住证或居住证原件。', '1610000002', '2013-01-14 11:24:47.260000', NULL, NULL, 1);
