INSERT INTO `visa_country_consulardistrict` VALUES (9, 'V130114000133', 'V130114000090', '/31/', '2', '如是北京、广东、福建、广西、天津、河北、海南、云南、重庆、四川、陕西、香港、澳门签发的护照或国外换发的中国护照，另须提供从签发期起至今已有半年以上有效期的江、浙、沪的暂住证或居住证原件及复印件；或提供江、浙、沪身份证原件及复印件。如：暂住证或居住证办理延期，请提供上海市人力资源和社会保障局出具的办理延期证明复印件。', '1610000002', '2013-01-14 16:35:26.750000', NULL, NULL, 0);
