INSERT INTO `visa_country_consulardistrict` VALUES (26, 'V130115000196', 'V130115000194', '/8/', '2', '上海、浙江、江苏、安徽、江西签发的护照并在以上五地工作生活或学习。其他地区签发的护照申请人如在以上五地工作生活或学习，需提供已有六个月记录的有效暂住证或居住证复印件。 备注：符合以上受理范围申请人的父母、子女、亲兄弟姐妹、配偶居住在受理范围外的家属也可与该申请人一起申请签证，同时提供与同行家属的户口簿复印件或亲属关系公证书原件。', '1610000002', '2013-01-15 11:54:46.517000', NULL, NULL, 1);
INSERT INTO `visa_country_consulardistrict` VALUES (27, 'V130115000197', 'V130115000194', '/8/', '1', '护照签发地为北京市，天津市，陕西省，山西省，甘肃省，河南省，河北省，湖北省，湖南省，青海省，新疆维吾尔自治区，宁夏回族自治区，西藏自治区，内蒙古自治区。如护照签发地不在上述地区内，其他地区申请者需在上述地区内工作、生活或学习并提供已有六个月记录的有效暂住证或居住证原件。 ', '1610000002', '2013-01-15 11:54:58.110000', NULL, NULL, 1);
