INSERT INTO `visa_countryinfo` VALUES (24, 'V130115000194', '/8/', 'Files/pic/8/1/4.jpg', '日本签证分八个领区：北京领区、上海领区、广州领区、沈阳领区、重庆领区、大连领区、青岛领区、香港领区。日本签证申请有领区限制，要注意所属领区。 建议按照居住证所在地或护照签发地就近办理。', '1610000002', '2013-01-15 12:05:39.123000', NULL, NULL, '1611000001');
