INSERT INTO `visa_data` VALUES (42, 'V120905000163', 'V120904000001', '在职证明', '用有公司抬头纸打印包含申请人的姓名,工作职位,公司名称,公司地址,公司电话,公司E-mail、联系方式、出行事由（目的）、出行时间、滞留时间(需公司法人代表签字及盖有公章,如法人代表申请由人事代表签字)以上内容均需要用英文填写<br style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\" />注：出行人不能为自己签名，同行人不可以互相签名。', 0, 1, 'V10001', '1610000002', '2012-09-05 15:35:13.807000', NULL, NULL, 1, 1, 1, 3);
