INSERT INTO `visa_data` VALUES (81, 'V120905000272', 'V120905000268', '户口簿', '<div class=\"align_l\">提供户口簿整本原件，如是集体户口，请提供集体户口首页和本人页的原件或户籍证明原件。</div>', 1, 1, 'V10007', '1610000002', '2012-09-05 16:37:35.987000', NULL, NULL, 0, 1, 1, 4);
