INSERT INTO `visa_data` VALUES (83, 'V120905000274', 'V120905000268', '在职证明', '<div class=\"align_l\">提供打印在有准确单位地址、电话的抬头信纸上的中文在职证明，加盖公司公章或人事章并有负责人签名和职务（如申请人本人是负责人，请公司其他高管签名，不可以自己签名）。在职证明内容包括：申请人在公司的职务、月薪，在现在工作单位工作时间、此行目的、行程日期、准假天数、说明谁承担费用并保证其遵守当地法律以及按时返回中国，公司保证申请人回国后保留其职务（具体内容和格式详见样本） 附： <a href=\"http://res.maidou.cn:98/upload/Visa/personal/singapore03.doc\">在职证明模板.doc</a> <a href=\"http://res.maidou.cn:98/upload/Visa/personal/singapore04.doc\">在职证明样本.doc</a> </div>', 0, 1, 'V10007', '1610000002', '2012-09-05 16:37:36.020000', NULL, NULL, 0, 1, 0, 6);
INSERT INTO `visa_data` VALUES (84, 'V120905000275', 'V120905000268', '备注', '<div class=\"align_l\">请务必确保在职证明中的联系方式是真实有效的，并在白纸上备注方便审核的时间段，以备领馆进行电话审核。 除了在职证明需要原件以外，其他材料都可以只提供扫描件。</div>', 1, 1, 'V10007', '1610000002', '2012-09-05 16:37:36.037000', NULL, NULL, 0, 1, 0, 7);
