INSERT INTO `visa_data` VALUES (95, 'V120905000288', 'V120905000283', '在校证明', '<div class=\"align_l\">提供打印在学校抬头纸上的中文在校证明，注明入学时间、请假时间、所在院校、地址、联系电话。加盖学校公章或学籍章或教务章，有学校负责人亲笔签名（学校负责人包括校长，教务主任，学籍管理处老师等，具体内容和格式详见样本）。如是应届毕业生（除大学生之外），可凭毕业证书或录取通知书的复印件代替。如在放假期间，提供学生证复印件。附： <a href=\"http://res.maidou.cn:98/upload/Visa/personal/singapore01.doc\">在校证明模板.doc</a> <a href=\"http://res.maidou.cn:98/upload/Visa/personal/singapore01.doc\">在校证明样本.doc</a> </div>', 1, 1, 'V10007', '1610000002', '2012-09-05 16:37:36.623000', NULL, NULL, 0, 1, 0, 5);
