INSERT INTO `visa_data` VALUES (237, 'V120907000625', 'V120907000562', '在校证明', '<p>请提供学校出具的中文在校证明，需用抬头纸打印并加盖公章和学校领导签名。内容必须写明是旅游目的。提供体现与有经济能力者关系的证明，学生证复印件或中文在校证明及父母的资金、资产证明（如有请提供）；若父母双方均不出行，还需提供父母双方的委托书；未成年人不能单独出行。</p>', 1, 0, 'V10012', '1610000002', '2012-09-07 20:53:28.623000', NULL, NULL, 0, 1, 0, 11);
