INSERT INTO `visa_data` VALUES (248, 'V120907000640', 'V120907000563', '同行关系证明', '提供体现与有经济能力者关系的证明、出生证复印件及父母的资金、资产证明（如有请提供）；若父母双方均不出行，还需提供父母双方的委托书；', 1, 0, 'V10012', '1610000002', '2012-09-07 20:55:55.643000', NULL, NULL, 1, 1, 0, 11);
INSERT INTO `visa_data` VALUES (250, 'V120907000647', 'V120907000564', '护照', '<div class=\"align_l\">1、护照在归国后至少还有半年以上有效期，护照末页需本人中文签名（不要用铅笔签名）；护照至少留有连续2页的空白签证页，不含备注页。<br />2、如有旧护照，则一并提供原件；如旧护照遗失，提供遗失证明；（注明护照号，是否有签证记录和拒签记录）。<br />3、不接受半年内被日本领馆拒签过和有过日本非法滞留过的护照。</div><div class=\"align_l\">4、不接收半年内有日本拒签章（含日本商务拒签）的护照。</div>', 1, 0, 'V10012', '1610000002', '2012-09-07 20:57:27.123000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (251, 'V120907000648', 'V120907000564', '照片', '<div class=\"align_l\">半年内拍摄的2寸（4.5cmx4.5cm）白底彩照2张（照片背面签字）。</div>', 1, 0, 'V10012', '1610000002', '2012-09-07 20:57:27.157000', NULL, NULL, 1, 2, 0, 2);
INSERT INTO `visa_data` VALUES (252, 'V120907000649', 'V120907000564', '身份证', '&nbsp;身份证正反面复印件。', 1, 0, 'V10012', '1610000002', '2012-09-07 20:57:27.170000', NULL, NULL, 0, 1, 0, 3);
INSERT INTO `visa_data` VALUES (253, 'V120907000650', 'V120907000564', '户口簿', '1、整本复印件（须复印到第一页空白页）；<br />2、如同行人在同一本户口簿上，只需提供一套复印件；<br />3、如是集体户口，可以提供集体户口本人信息页复印件或常驻人口信息登记表复印件或户籍证明原件。', 1, 0, 'V10012', '1610000002', '2012-09-07 20:57:27.187000', NULL, NULL, 0, 1, 0, 4);
INSERT INTO `visa_data` VALUES (254, 'V120907000651', 'V120907000564', '结婚证', '<div class=\"align_l\">已婚人员提供结婚证复印件。</div>', 1, 0, 'V10012', '1610000002', '2012-09-07 20:57:27.203000', NULL, NULL, 0, 1, 0, 5);
INSERT INTO `visa_data` VALUES (255, 'V120907000652', 'V120907000564', '营业执照', '<div class=\"align_l\">提供在有效期内的营业执照副本的复印件，并加盖公章（非企业单位可用组织机构代码证代替）。营业执照或组织机构代码证上必须有近一年内的年检章。</div>', 1, 0, 'V10012', '1610000002', '2012-09-07 20:57:27.220000', NULL, NULL, 0, 1, 0, 6);
INSERT INTO `visa_data` VALUES (256, 'V120907000653', 'V120907000564', '资产证明（4选1）', '<div class=\"align_l\">(以下财产证明，请尽可能多提供，有助于出签)<br />1、房产证复印件<br />2、购车证或车辆行驶证复印件<br />3、银行出具的近六个月的有进出账记录的银行卡对账单或存折复印件，对账单上须能显示持卡人姓名及卡号（切勿在最后突然存入大额款项，存款余额在5万元以上，须有银行盖章）。<br />4、股票交割单原件需加盖柜台章或其他资金证明（余额在5万以上）。</div>', 1, 0, 'V10012', '1610000002', '2012-09-07 20:57:27.237000', NULL, NULL, 0, 1, 0, 7);
INSERT INTO `visa_data` VALUES (257, 'V120907000654', 'V120907000564', '行程安排', '<div class=\"align_l\">（客人自己提供）<br />1、中文的行程单。<br />2、往返机票预订单（必须与您的中文行程单保持一致）。</div>', 1, 0, 'V10012', '1610000002', '2012-09-07 20:57:27.253000', NULL, NULL, 0, 1, 0, 8);
INSERT INTO `visa_data` VALUES (258, 'V120907000655', 'V120907000564', '签证申请表', '请用黑色水笔填写真实完整的签证申请表一份。确保联系电话真实有效、保持畅通便于领馆联系。', 1, 0, 'V10012', '1610000002', '2012-09-07 20:57:27.270000', NULL, NULL, 1, 1, 1, 9);
INSERT INTO `visa_data` VALUES (259, 'V120907000658', 'V120907000564', '担保金', '<div class=\"align_l\">担保金5万/人，我司将根据您的材料情况，酌情增加担保金的额度。回国后凭护照给予返还。如发生滞留不归或违反当地相关法律的情况，担保金将不予退还。</div>', 1, 0, 'V10012', '1610000002', '2012-09-07 20:57:27.317000', NULL, NULL, 1, 1, 1, 10);
INSERT INTO `visa_data` VALUES (260, 'V120907000660', 'V120907000564', '资金证明', '①首先提供父母、子女、亲兄弟姐妹、配偶名下的上述任一经济能力证明；并同时提交两人的关系证明（可体现关系的户口本整本复印件、结婚证复印件或者亲属关系公证书复印件）<br />②无法提供①中的材料请提供本人名下至少40万的存款证明原件（需冻结至归国后3个月）与市值至少200万元的房产证复印件（请客人在复印件上标注出房产的市值）。 <br />以上情况领馆可能会要求您增补材料，请积极配合，备注中的申请人不能携带父母、子女、亲兄弟姐妹、配偶申请签证。', 1, 0, 'V10012', '1610000002', '2012-09-07 21:00:00.213000', NULL, NULL, 0, 1, 0, 11);
INSERT INTO `visa_data` VALUES (261, 'V120910000671', 'V120910000665', '护照', '<div class=\"align_l\">护照在归国后至少还有半年以上有效期，护照末页需本人中文签名（不要用铅笔签名）；护照至少留有连续2页的空白签证页，不含备注页。 </div>', 1, 1, 'V10013', '1610000002', '2012-09-10 09:50:02.153000', NULL, NULL, 1, 1, 0, 1);
