INSERT INTO `visa_data` VALUES (307, 'V120912000770', 'V120912000724', '★护照', '1、护照在归国后至少还有半年以上有效期，护照末页需本人中文签名（不要用铅笔签名）；护照至少留有连续正反2页的空白签证页，不含备注页。<br />2、如有旧护照，则一并提供原件；如旧护照遗失，提供遗失证明；（注明护照号，是否有签证记录和拒签记录）。', 1, 0, 'V10015', '1610000002', '2012-09-12 17:37:05.677000', NULL, NULL, 1, 1, 1, 1);
