INSERT INTO `visa_data` VALUES (309, 'V120912000772', 'V120912000724', '★身份证', '身份证正反面的复印件。', 1, 0, 'V10015', '1610000002', '2012-09-12 17:37:05.750000', NULL, NULL, 1, 1, 0, 3);
INSERT INTO `visa_data` VALUES (310, 'V120912000773', 'V120912000724', '★户口簿', '提供户口簿整本复印件（从第一页印到第一张空白页），如是集体户口，请提供集体户口首页和本人页的复印件或户籍证明原件。', 0, 0, 'V10015', '1610000002', '2012-09-12 17:37:05.777000', NULL, NULL, 1, 1, 0, 4);
INSERT INTO `visa_data` VALUES (311, 'V120912000775', 'V120912000724', '★在校证明', '提供打印在学校抬头纸上的英文在校证明，注明入学时间、请假时间、所在院校、地址、联系电话。加盖学校公章或学籍章或教务章，有学校负责人亲笔签名（学校负责人包括校长，教务主任，学籍管理处老师等，具体内容和格式详见样本）。如是应届毕业生（除大学生之外），可凭毕业证书或录取通知书的复印件代替。', 1, 1, 'V10015', '1610000002', '2012-09-12 17:38:33.940000', NULL, NULL, 1, 1, 0, 5);
INSERT INTO `visa_data` VALUES (312, 'V120912000779', 'V120912000724', '★资金证明', '（可提供父母名下的资产，请提供户口本复印件、出生证复印件或亲属关系公证书）<br />1、银行存款证明：银行出具的本人名下至少10万元的存款证明原件，需冻结4个月。<br />2、银行对账单：提供银行出具的本人名下近六个月的有进出账记录的工资卡对账单，银行卡对账单或存折复印件，对账单上须能显示持卡人姓名及卡号（切勿在最后突然存入大额款项，存款余额越多越好，须有银行盖章）。<br />', 1, 0, 'V10015', '1610000002', '2012-09-12 17:38:57.650000', NULL, NULL, 1, 1, 0, 6);
INSERT INTO `visa_data` VALUES (313, 'V120912000784', 'V120912000724', '★资产证明', '以下财产证明，请尽可能多提供，有助于出签：（可提供父母名下的资产，请提供户口本复印件、出生证复印件或亲属关系公证书）<br />1、房产证复印件；<br />2、购车证或车辆行驶证复印件；<br />3、股票交割单或其他资金证明复印件。', 0, 1, 'V10015', '1610000002', '2012-09-12 17:39:58.760000', NULL, NULL, 1, 1, 0, 7);
INSERT INTO `visa_data` VALUES (314, 'V120912000786', 'V120912000724', '★亲属关系证明', '如是18周岁以下未成年人，请根据出行情况提供以下材料： <br />1、若与父母同行，须提供体现关系的户口本复印件（如果户口本无法体现一家三口关系，可以用出生证复印件或亲属关系公证书代替）。<br />2、若只与父母一方出行，须提供体现关系的户口本复印件、父母不同行一方的身份证复印件及不同行一方的同意书（如果户口本无法体现一家三口关系，可以用出生证复印件或亲属关系公证书代替）。<br />3、若父母双方均不出行，须提供供体现关系的户口本复印件、父母双方的身份证复印件及父母双方的委托书（如果户口本无法体现一家三口关系，可以用出生证复印件或亲属关系公证书代替）。<br />4、亲属关系公证书申请人必须为儿童本人，具体格式内容请参照样本。<br />5、如父母离异提供离婚证复印件。', 1, 1, 'V10015', '1610000002', '2012-09-12 17:40:35.427000', NULL, NULL, 1, 1, 0, 8);
INSERT INTO `visa_data` VALUES (315, 'V120912000792', 'V120912000724', '★行程单', '1、英文的行程单<br />2、往返机票预订单（必须与您的英文行程单保持一致）<br />3、酒店确认单（必须与您的英文行程单保持一致）', 0, 0, 'V10015', '1610000002', '2012-09-12 17:42:29.740000', NULL, NULL, 1, 1, 0, 9);
INSERT INTO `visa_data` VALUES (316, 'V120912000794', 'V120912000724', '★个人资料表', '填写真实完整的个人资料表一份并本人亲笔签字。确保联系电话真实有效、保持畅通便于领馆联系。', 1, 0, 'V10015', '1610000002', '2012-09-12 17:42:29.787000', NULL, NULL, 1, 1, 0, 10);
INSERT INTO `visa_data` VALUES (317, 'V120912000797', 'V120912000725', '★护照', '1、护照在归国后至少还有半年以上有效期，护照末页需本人中文签名（不要用铅笔签名）；护照至少留有连续正反2页的空白签证页，不含备注页。<br />2、如有旧护照，则一并提供原件；如旧护照遗失，提供遗失证明；（注明护照号，是否有签证记录和拒签记录）。', 1, 0, 'V10015', '1610000002', '2012-09-12 17:43:30.263000', NULL, NULL, 1, 1, 1, 1);
