INSERT INTO `visa_data` VALUES (321, 'V120912000803', 'V120912000725', '★资金证明', '（可提供父母名下的资产，请提供户口本复印件、出生证复印件或亲属关系公证书）<br />1、银行存款证明：银行出具的本人名下至少10万元的存款证明原件，需冻结4个月。<br />2、银行对账单：提供银行出具的本人名下近六个月的有进出账记录的工资卡对账单，银行卡对账单或存折复印件，对账单上须能显示持卡人姓名及卡号（切勿在最后突然存入大额款项，存款余额越多越好，须有银行盖章）。', 1, 1, 'V10015', '1610000002', '2012-09-12 17:44:31.010000', NULL, NULL, 1, 1, 0, 5);
INSERT INTO `visa_data` VALUES (322, 'V120912000805', 'V120912000725', '★资产证明', '以下财产证明，请尽可能多提供，有助于出签：（可提供父母名下的资产，请提供户口本复印件、出生证复印件或亲属关系公证书）<br />1、房产证复印件；<br />2、购车证或车辆行驶证复印件；<br />3、股票交割单或其他资金证明复印件。', 0, 1, 'V10015', '1610000002', '2012-09-12 17:44:49.713000', NULL, NULL, 1, 1, 0, 6);
