INSERT INTO `visa_data` VALUES (325, 'V120912000811', 'V120912000725', '★亲属关系证明', '如是18周岁以下未成年人，请根据出行情况提供以下材料： <br />1、若与父母同行，须提供体现关系的户口本复印件（如果户口本无法体现一家三口关系，可以用出生证复印件或亲属关系公证书代替）。<br />2、若只与父母一方出行，须提供体现关系的户口本复印件、父母不同行一方的身份证复印件及不同行一方的同意书（如果户口本无法体现一家三口关系，可以用出生证复印件或亲属关系公证书代替）。<br />3、若父母双方均不出行，须提供供体现关系的户口本复印件、父母双方的身份证复印件及父母双方的委托书（如果户口本无法体现一家三口关系，可以用出生证复印件或亲属关系公证书代替）。<br />4、亲属关系公证书申请人必须为儿童本人，具体格式内容请参照样本。<br />5、如父母离异提供离婚证复印件。', 1, 0, 'V10015', '1610000002', '2012-09-12 17:45:20.877000', NULL, NULL, 1, 1, 0, 7);
