INSERT INTO `visa_data` VALUES (494, 'V120928001216', 'V120928001212', '户口簿', '<p>1、提供户口簿整本复印件（从第一页印到第一张空白页），如是集体户口，请提供集体户口首页和本人页的复印件或户籍证明原件。</p><p>2、若夫妻不在同一户口本上，请提供配偶的完整户口本复印件（包括首页，备注页，不能有缺页）</p><p>3、若非上海领区申请人，请提供在上海领区范围内城市，半年以上，有效期为六个月以上的暂住证或者居住证原件和复印件<br /><br /></p>', 0, 0, 'V10020', '1610000002', '2012-09-28 14:40:15.853000', NULL, NULL, 0, 1, 0, 0);
