INSERT INTO `visa_data` VALUES (595, 'V120928001403', 'V120928001395', '个人资料表', '①要求按照提供的申请表如实填写,并且右下角必须本人签字。（与护照签字一致）<br />②每个栏目都要填,表上每一栏资料都会用到。（注意：职务、手机、单位电话、地址必须<br />  填写，并如有虚假内容所有后果一律自己负责）<br />③特别注意【在南非是否有亲属生活或工作？】一栏，必须填写。<br /><br />', 0, 1, 'V20021', '1610000002', '2012-09-28 16:03:31.550000', NULL, NULL, 1, 1, 0, 2);
