INSERT INTO `visa_data` VALUES (616, 'V120928001454', 'V120928001396', '退休人员', '1、退休证原件，若无退休证，可提供公司英文的退休证明或由街道出具退休证明，也需由负责人签字。<br />2、70岁以上老年人领馆要求提供健康证明，保证客人不会在境外发生健康问题。<br />', 1, 1, 'V20021', '1610000002', '2012-09-28 16:18:23.343000', NULL, NULL, 1, 1, 1, 4);
