INSERT INTO `visa_data` VALUES (693, 'V120928001591', 'V120928001398', '学龄前儿童', 'A：随父母旅游，需提供亲属关系公证书原件。<br />B：随父母一方去旅游，必须提供亲属关系公证书及另一方的委托授权书；若离异，则须原配父母提供。<br />C：单独旅游领馆不受理，必须有大人的陪同，非父母的陪同，需提供亲属关系公证书原件及双方委托授权同意书公证书原件。<br />（公证书需中英文对照翻译，且公证件一律不退还）。<br /><p><br /></p>', 1, 1, 'V20021', '1610000002', '2012-09-28 16:36:18.987000', NULL, NULL, 1, 1, 0, 4);
