INSERT INTO `visa_data` VALUES (767, 'V120928001768', 'V120928001751', '护照', '<p>1、有效期半年以上的护照，空白签证页2张以上（护照末页必须有客人本人签名）。<br />2、如有旧护照，则一并提供原件；如旧护照遗失，提供遗失证明；（注明护照号，是否有签证记录和拒签记录）。<br /><br /></p>', 1, 1, 'V10026', '1610000002', '2012-09-28 17:27:28.507000', NULL, NULL, 1, 1, 1, 1);
