INSERT INTO `visa_data` VALUES (817, 'V120928001869', 'V120928001751', '在职证明', '<p>提供英文在职证明。在职证明中必须包含公司抬头，加盖公司公章或人事章，有公司负责人亲笔签名。空格处内容不可手写。公司负责人可以是法人代表、总经理、部门主管或人事主管。注：出行人不能为自己签名（除非是法人代表，可以为自己的在职证明签名）同行人不可以互相签名。（在职证明内须注明月薪、职务；不可写EMPLOYEE或STAFF）<span style=\"font-size:10pt;font-family:宋体;\">抬头纸上必须有</span><strong><span style=\"font-size:10.0pt;font-family:宋体;color:red;\">公司地址</span></strong><span style=\"font-size:10pt;font-family:宋体;\">和</span><strong><span style=\"font-size:10.0pt;font-family:宋体;color:red;\">公司电话.</span></strong></p>', 1, 1, 'V10026', '1610000002', '2012-09-28 17:40:56.790000', NULL, NULL, 1, 1, 0, 3);
