INSERT INTO `visa_data` VALUES (840, 'V120929001975', 'V120928001740', '退休人员', '1、需提供退休证原件。60岁以上的老人还需要提供健康证明原件。（几乎不予退还）50岁以上的视其签证照片而定，若照片苍老也需提供健康证原件。需向领事馆提供每人至少3个月有效的不少于30000元的银行存款证明。年老者有被领馆拒签的可能性。<br />2、若无退休证，可由户籍所在居委或村委开具详细书面退休证明【英文版】原件。', 1, 1, 'V20025', '1610000002', '2012-09-29 09:16:26.827000', NULL, NULL, 1, 1, 1, 5);
