INSERT INTO `visa_data` VALUES (845, 'V120929001982', 'V120928001741', '在校学生', '<p>小于18周岁的未成年人：<br />A：随父母旅游，需提供亲属关系公证书原件;<br />B：随父母一方去旅游，必须提供亲属关系公证书及另一方的委托授权书；若离异，须原配父母提供<br />C：单独旅游领馆不受理，必须有大人的陪同，非父母的陪同，需提供亲属关系公证书原件及父母双方委托授权同意书公证书原件。<br />以上三种情况皆需须提供学籍证明（英文版）或学生证原件<br />（公证书需中英文对照翻译，且公证件一律不退还）。<br />已满18周岁的学生：<br />提供学籍证明或学生证原件及能证明其亲属关系的户口本复印件。如若单独出行则另须提供本人的银行存款证明 有效期3个月以上 金额5万以上 若提供父母存款证明 另须附加出生证原件。（领馆不受理集体户口。）<br /></p>', 0, 1, 'V20025', '1610000002', '2012-09-29 09:20:28.923000', NULL, NULL, 1, 1, 1, 3);
