INSERT INTO `visa_data` VALUES (926, 'V120929002152', 'V120929002138', '户口簿', '户口本整本复印件（须复印到第一页空白页）<br />如果是集体户口，请提供户主页和本人页，或户籍证明原件', 1, 1, 'V20029', '1610000002', '2012-09-29 11:36:12.940000', NULL, NULL, 0, 1, 0, 5);
INSERT INTO `visa_data` VALUES (927, 'V120929002154', 'V120929002138', '个人资料表', '填写真实完整并本人亲笔签字，并请将本人的父母、兄弟姐妹、子女的详细资料认真如实填写。特别注意是否有亲戚在国外,是否有过拒签。', 1, 1, 'V20029', '1610000002', '2012-09-29 11:37:27.077000', NULL, NULL, 1, 1, 0, 6);
