INSERT INTO `visa_data` VALUES (929, 'V120929002159', 'V120929002138', '在职证明', '①提供中文在职证明一份，必须包含公司抬头，加盖公司公章或人事章，有公司负责人亲笔签名。公司负责人可以是法人代表、总经理、部门主管或人事主管。<br />②本人单位营业执照（或组织机构代码证）复印件并加盖公章。<br />（如是澳新连线，请提供两份在职证明、两份营业执照）', 1, 1, 'V20029', '1610000002', '2012-09-29 11:40:14.850000', NULL, NULL, 1, 1, 0, 8);
INSERT INTO `visa_data` VALUES (930, 'V120929002162', 'V120929002138', '资产证明（必须提供） ', '<p>①银行开具的本人名下的已有3个月存入期的至少5万元的定期存款证明原件（此原件不退）。</p><p>注：存款证明必须注明已冻结，冻结至旅行回来1个月后。</p><p>②能证明是本人所有的存折或一卡通账户的近半年对帐单（上面需有清晰的户主姓名和卡号，以及银行的盖章），资金的进出金额、进出频率以及余额要尽可能丰富。</p>', 0, 1, 'V20029', '1610000002', '2012-09-29 11:41:34.723000', NULL, NULL, 1, 1, 0, 9);
INSERT INTO `visa_data` VALUES (931, 'V120929002165', 'V120929002138', '资产证明（选择提供）', '为了提高您的出签率，以下材料请尽可能多提供：（可以是配偶名下的资产证明，同时提供结婚证复印件）<br />A.提供半年有效期存单5万元以上复印件（定期或活期都可）<br />B.房产证复印件<br />C.车产证复印件或行驶证复印件<br />D.股票交割单原件需加盖柜台章或其他资金证明，且余额在5万以上', 1, 1, 'V20029', '1610000002', '2012-09-29 11:44:46.193000', NULL, NULL, 1, 1, 0, 10);
INSERT INTO `visa_data` VALUES (932, 'V120929002167', 'V120929002138', '团队旅游保证金 ', '担保金5万/人，我司将根据您的材料情况，酌情增加担保金的额度。随团回国后凭护照给予返还。如发生滞留不归或违反当地相关法律的情况，担保金将不予退还。（建议使用渣打银行“创享旅游服务”，旅游保证金交纳不烦恼）', 1, 1, 'V20029', '1610000002', '2012-09-29 11:45:10.033000', NULL, NULL, 1, 1, 1, 11);
INSERT INTO `visa_data` VALUES (933, 'V120929002169', 'V120929002138', '特别提醒', '①如有拒签记录，请如实提供亲笔签名的拒签说明书。<br />②如在澳大利亚和新西兰有亲戚，请提供其在当地的电话，地址；护照复印件和签证页复印件。<br />③我公司保留索要补充资料的权利', 1, 1, 'V20029', '1610000002', '2012-09-29 11:45:32.813000', NULL, NULL, 1, 1, 0, 12);
