INSERT INTO `visa_data` VALUES (953, 'V120929002205', 'V120929002064', '在校学生', '小于18周岁的未成年人：<br />A：随父母旅游，需提供亲属关系公证书原件;<br />B：随父母一方去旅游，必须提供亲属关系公证书及另一方的委托授权书；若离异，须原配父母提供<br />C：单独旅游领馆不受理，必须有大人的陪同，非父母的陪同，需提供亲属关系公证书原件及父母双方授权委托书公证书原件。<br />以上三种情况皆需须提供学籍证明（中英文皆可）和 学生证原件<br />（公证书需中英文对照翻译，且公证件一律不退还）。<br />已满18周岁的学生：<br />提供学籍证明（中英文皆可，需校方负责人签字盖章）和 学生证原件及能证明其亲属关系的户口本复印件。如若单独出行则另须提供本人的银行存款证明 有效期3个月以上 金额5万以上 若提供父母存款证明 另须附加出生证。（领馆不受理集体户口。）', 0, 1, 'V20028', '1610000002', '2012-09-29 13:26:36.270000', NULL, NULL, 1, 1, 1, 3);
INSERT INTO `visa_data` VALUES (954, 'V120929002207', 'V120929002065', '护照', '有效期半年以上的护照，空白签证页2张以上（护照上有换发或补发字样，必须提供旧护照，无旧护照必须提供护照的遗失证明原件 （签发日期为2008年之前的可以不许旧护照，2008年及以后签发的必须提供）', 1, 0, 'V20028', '1610000002', '2012-09-29 13:26:53.953000', NULL, NULL, 1, 1, 1, 1);
