INSERT INTO `visa_data` VALUES (957, 'V120929002212', 'V120929002065', '学龄前儿童', 'A：随父母旅游，需提供亲属关系公证书原件。<br />B：随父母一方去旅游，必须提供亲属关系公证书及另一方的委托授权书；若离异，则须原配父母提供。<br />C：单独旅游领馆不受理，必须有大人的陪同，非父母的陪同，需提供亲属关系公证书原件及双方委托授权同意书公证书原件。<br />（公证书需中英文对照翻译，且公证件一律不退还）。', 1, 1, 'V20028', '1610000002', '2012-09-29 13:27:28.027000', NULL, NULL, 1, 1, 0, 3);
INSERT INTO `visa_data` VALUES (958, 'V120929002214', 'V120929002066', '护照', '有效期半年以上的护照，空白签证页2张以上（护照上有换发或补发字样，必须提供旧护照，无旧护照必须提供护照的遗失证明原件 （签发日期为2008年之前的可以不许旧护照，2008年及以后签发的必须提供）', 1, 0, 'V20028', '1610000002', '2012-09-29 13:27:39.417000', NULL, NULL, 1, 1, 1, 1);
