INSERT INTO `visa_data` VALUES (961, 'V120929002219', 'V120929002066', '自由职业者', '提供配偶的英文在职证明、结婚证的复印件及有效期3个月以上、金额5万元以上的存款证明，无配偶者视情况而定。', 1, 1, 'V20028', '1610000002', '2012-09-29 13:28:27.510000', NULL, NULL, 1, 1, 1, 3);
INSERT INTO `visa_data` VALUES (963, 'V120929002226', 'V120929002140', '护照', '①归国后还有6个月以上有效期<br />②末页必须有持证人中文亲笔签名<br />③至少留有2页空白签证页（不是备注页）<br />④如有旧护照请一并提供。<br />⑤不接收半年内有澳大利亚拒签章的护照；不接收在澳大利亚非法滞留过的护照', 1, 0, 'V20029', '1610000002', '2012-09-29 13:47:49.670000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (964, 'V120929002227', 'V120929002140', '照片', '半年内拍摄的2寸(3.5cmx4.5cm)白底彩照3张(照片背面签字) （如是澳新连线是4张）', 1, 0, 'V20029', '1610000002', '2012-09-29 13:47:49.723000', NULL, NULL, 1, 3, 0, 2);
