INSERT INTO `visa_data` VALUES (979, 'V120929002251', 'V120929002141', '存款证明 ', '银行开具的已有3个月存入期的至少5万元的定期存款证明原件（此原件不退）。存款证明必须注明已冻结，冻结至旅行归来1个月后。<br />可以提供父母名下的资产，如房产，车产等。', 1, 1, 'V20029', '1610000002', '2012-09-29 14:32:06.443000', NULL, NULL, 1, 1, 0, 6);
