INSERT INTO `visa_data` VALUES (981, 'V120929002255', 'V120929002142', '护照', '①归国后还有6个月以上有效期<br />②末页必须有持证人中文亲笔签名<br />③至少留有2页空白签证页（不是备注页）<br />④如有旧护照请一并提供。<br />⑤不接收半年内有澳大利亚拒签章的护照；不接收在澳大利亚非法滞留过的护照', 1, 0, 'V20029', '1610000002', '2012-09-29 14:34:42.180000', NULL, NULL, 1, 1, 1, 1);
