INSERT INTO `visa_data` VALUES (986, 'V120929002261', 'V120929002142', '结婚证/离婚证', '凡有婚姻状况，均需要提供结婚证或者离婚证复印件。', 1, 0, 'V20029', '1610000002', '2012-09-29 14:34:42.343000', NULL, NULL, 0, 1, 0, 6);
INSERT INTO `visa_data` VALUES (987, 'V120929002262', 'V120929002142', '资产证明（必须提供） ', '<p>①银行开具的本人名下的已有3个月存入期的至少5万元的定期存款证明原件（此原件不退）。</p><p>注：存款证明必须注明已冻结，冻结至旅行回来1个月后。</p><p>②能证明是本人所有的存折或一卡通账户的近半年对帐单（上面需有清晰的户主姓名和卡号，以及银行的盖章），资金的进出金额、进出频率以及余额要尽可能丰富。</p>', 1, 0, 'V20029', '1610000002', '2012-09-29 14:34:42.380000', NULL, NULL, 1, 1, 0, 7);
INSERT INTO `visa_data` VALUES (988, 'V120929002263', 'V120929002142', '资产证明（选择提供）', '为了提高您的出签率，以下材料请尽可能多提供：（可以是配偶名下的资产证明，同时提供结婚证复印件）<br />A.提供半年有效期存单5万元以上复印件（定期或活期都可）<br />B.房产证复印件<br />C.车产证复印件或行驶证复印件<br />D.股票交割单原件需加盖柜台章或其他资金证明，且余额在5万以上', 1, 0, 'V20029', '1610000002', '2012-09-29 14:34:42.403000', NULL, NULL, 1, 1, 0, 8);
INSERT INTO `visa_data` VALUES (989, 'V120929002264', 'V120929002142', '团队旅游保证金 ', '担保金5万/人，我司将根据您的材料情况，酌情增加担保金的额度。随团回国后凭护照给予返还。如发生滞留不归或违反当地相关法律的情况，担保金将不予退还。（建议使用渣打银行“创享旅游服务”，旅游保证金交纳不烦恼）', 1, 0, 'V20029', '1610000002', '2012-09-29 14:34:42.427000', NULL, NULL, 1, 1, 1, 10);
INSERT INTO `visa_data` VALUES (990, 'V120929002265', 'V120929002142', '特别提醒', '①如有拒签记录，请如实提供亲笔签名的拒签说明书。<br />②如在澳大利亚和新西兰有亲戚，请提供其在当地的电话，地址；护照复印件和签证页复印件。<br />③我公司保留索要补充资料的权利', 1, 0, 'V20029', '1610000002', '2012-09-29 14:34:42.450000', NULL, NULL, 1, 1, 0, 11);
INSERT INTO `visa_data` VALUES (991, 'V120929002267', 'V120929002142', '工作情况（选择提供） ', '如是个体户请提供本人营业执照复印件；<br />如果有失业证或社区失业证明，请提供复印件；<br />如果有无业证，请提供复印件。', 1, 1, 'V20029', '1610000002', '2012-09-29 14:35:02.683000', NULL, NULL, 0, 1, 0, 9);
INSERT INTO `visa_data` VALUES (992, 'V120929002278', 'V120929002272', '护照', '①归国后还有6个月以上有效期<br />②末页必须有持证人中文亲笔签名<br />③至少留有2页空白签证页（不是备注页）<br />④如有旧护照请一并提供。<br />⑤不接收半年内有澳大利亚拒签章的护照；不接收在澳大利亚非法滞留过的护照', 0, 1, 'V20030', '1610000002', '2012-09-29 14:39:17.600000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (993, 'V120929002280', 'V120929002272', '照片', '半年内拍摄的2寸(3.5cmx4.5cm)白底彩照3张(照片背面签字) （如是澳新连线是4张）', 1, 1, 'V20030', '1610000002', '2012-09-29 14:39:48.400000', NULL, NULL, 1, 3, 0, 2);
INSERT INTO `visa_data` VALUES (994, 'V120929002282', 'V120929002272', '名片 ', '2张（如有请提供）', 1, 1, 'V20030', '1610000002', '2012-09-29 14:40:10.707000', NULL, NULL, 1, 2, 0, 3);
INSERT INTO `visa_data` VALUES (995, 'V120929002284', 'V120929002272', '身份证', '本人身份证正反面复印件。', 1, 1, 'V20030', '1610000002', '2012-09-29 14:40:32.117000', NULL, NULL, 0, 1, 0, 4);
INSERT INTO `visa_data` VALUES (996, 'V120929002286', 'V120929002272', '户口簿', '户口整本复印件（须复印到第一页空白页）<br />如是集体户口，需提供户主页和本人页复印件', 1, 1, 'V20030', '1610000002', '2012-09-29 14:41:35.247000', NULL, NULL, 0, 1, 0, 5);
INSERT INTO `visa_data` VALUES (997, 'V120929002288', 'V120929002272', '个人资料表', '填写真实完整并本人亲笔签字，并请将本人的父母、兄弟姐妹、子女的详细资料认真如实填写。特别注意是否有亲戚在国外,是否有过拒签。', 1, 1, 'V20030', '1610000002', '2012-09-29 14:42:49.033000', NULL, NULL, 1, 1, 0, 6);
INSERT INTO `visa_data` VALUES (998, 'V120929002291', 'V120929002272', '结婚证/离婚证', '凡有婚姻状况，均需要提供结婚证或者离婚证复印件。', 1, 1, 'V20030', '1610000002', '2012-09-29 14:43:20.960000', NULL, NULL, 0, 1, 0, 7);
INSERT INTO `visa_data` VALUES (999, 'V120929002293', 'V120929002272', '在职证明/准假信', '①提供中英文在职证明不接受空白信纸，必须包含准假信息，公司抬头，加盖公司公章或人事章，有公司负责人亲笔签名。公司负责人可以是法人代表、总经理、部门主管或人事主管。<br />②本人单位营业执照（或组织机构代码证）复印件并加盖公章。<br />（如是澳新连线，请提供两份在职证明、两份营业执照）', 1, 1, 'V20030', '1610000002', '2012-09-29 14:44:24.797000', NULL, NULL, 1, 1, 0, 8);
INSERT INTO `visa_data` VALUES (1001, 'V120929002298', 'V120929002272', '资产证明（必须提供） ', '<p>① 银行开具的本人名下的已有3个月存入期的至少5万元的定期存款证明原件（此原件不退）。</p><p>注：存款证明必须注明已冻结，冻结至旅行回来1个月后。</p>②能证明是本人所有的存折或一卡通账户的近半年对帐单（上面需有清晰的户主姓名和卡号，以及银行的盖章），资金的进出金额、进出频率以及余额要尽可能丰富。', 1, 1, 'V20030', '1610000002', '2012-09-29 14:48:39.443000', NULL, NULL, 1, 1, 0, 10);
INSERT INTO `visa_data` VALUES (1002, 'V120929002300', 'V120929002272', '资产证明（选择提供） ', '为了提高您的出签率，以下材料请尽可能多提供： （可以是配偶名下的资产证明，同时提供结婚证复印件）<br />A.提供半年有效期存单5万元以上复印件（定期或活期都可）<br />B.房产证复印件<br />C.车产证复印件或行驶证复印件<br />D.股票交割单原件需加盖柜台章或其他资金证明，且余额在5万以上', 1, 1, 'V20030', '1610000002', '2012-09-29 14:49:19.583000', NULL, NULL, 0, 1, 0, 11);
INSERT INTO `visa_data` VALUES (1003, 'V120929002302', 'V120929002272', '团队旅游保证金 ', '担保金5万/人，我司将根据您的材料情况，酌情增加担保金的额度。随团回国后凭护照给予返还。如发生滞留不归或违反当地相关法律的情况，担保金将不予退还。（建议使用渣打银行“创享旅游服务”，旅游保证金交纳不烦恼）', 1, 1, 'V20030', '1610000002', '2012-09-29 14:49:40.867000', NULL, NULL, 1, 1, 1, 12);
INSERT INTO `visa_data` VALUES (1004, 'V120929002304', 'V120929002272', '特别提醒', '①如有拒签记录，请如实提供亲笔签名的拒签说明书。并提供本人名下近6个月银行对账单。<br />②如在澳大利亚和新西兰有亲戚，请提供其在当地的电话，地址；护照复印件和签证页复印件。<br />③我公司保留索要补充资料的权利', 1, 1, 'V20030', '1610000002', '2012-09-29 14:49:59.340000', NULL, NULL, 1, 1, 1, 13);
