INSERT INTO `visa_data` VALUES (1021, 'V120929002326', 'V120929002274', '团队旅游保证金 ', '担保金5万/人，我司将根据您的材料情况，酌情增加担保金的额度。随团回国后凭护照给予返还。如发生滞留不归或违反当地相关法律的情况，担保金将不予退还。（建议使用渣打银行“创享旅游服务”，旅游保证金交纳不烦恼）', 1, 0, 'V20030', '1610000002', '2012-09-29 15:38:48.523000', NULL, NULL, 1, 1, 1, 9);
INSERT INTO `visa_data` VALUES (1022, 'V120929002328', 'V120929002274', '相关证明 ', '18岁以下学生请根据出行情况提供以下材料： <br />（1）若与父母同行，须提供出生证原件；<br />（2）若只与父母一方出行，须提供出生证原件、不同行方的中文同意信和父母双方的身份证复印件；<br />（3）若与亲戚朋友出行，须提供出生证原件、父母双方的中文同意信和身份证复印件；<br />注：1、出生证上所显示的信息要打印版本，如子女的姓名是手工填写的，需在手工填写姓名的地方加盖医院公章；如出生证上的所有信息均为手工填写的，必须保持笔迹一致，否则也要在姓名的地方加盖医院公章（医院公章应与出生证右下方公章一致）。<br />2、如无法提供符合要求的出生证，可以用中英文亲属关系公证书代替，但不可以用独生子女证代替<br />3、中英文亲属关系公证书申请人必须为儿童本人<br />4、同意信具体格式内容请参照样本（此表格由十八岁以下申请人的不随行父母填写）', 1, 1, 'V20030', '1610000002', '2012-09-29 15:41:03.977000', NULL, NULL, 1, 1, 0, 6);
INSERT INTO `visa_data` VALUES (1023, 'V120929002330', 'V120929002274', '存款证明 ', '银行开具的已有3个月存入期的至少5万元的定期存款证明原件（此原件不退）。存款证明必须注明已冻结，冻结至旅行归来1个月后。', 1, 1, 'V20030', '1610000002', '2012-09-29 15:43:30.020000', NULL, NULL, 1, 1, 0, 8);
INSERT INTO `visa_data` VALUES (1024, 'V120929002333', 'V120929002274', '特别提醒', '①如有拒签记录，请如实提供亲笔签名的拒签说明书。<br />②如在澳大利亚和新西兰有亲戚，请提供其在当地的电话，地址；护照复印件和签证页复印件。<br />③我公司保留索要补充资料的权利<br />④公证书办理须知：<br />1、上海市户口的申请人在市区级公证处均可以办理公证书。部分公证处联系方式以供参考：静安区公证处 (电话：62671801、32170441)、杨浦区公证处（电话：65899528）、浦东新区公证处（电话：58396060、58395050）。 <br />2、请在去公证处前先准备齐全资料，可以缩短公证书的办理时间。<br />办理亲属关系公证书所需材料：<br />-父母和子女的身份证及户口本原件<br />-结婚证书原件<br />-子女出生证或独生子女证原件', 1, 1, 'V20030', '1610000002', '2012-09-29 15:51:02.703000', NULL, NULL, 1, 1, 0, 10);
INSERT INTO `visa_data` VALUES (1025, 'V120929002341', 'V120929002274', '在校证明 ', '提供学校出具的中文在校证明原件，需用抬头纸打印并加盖公章和学校领导签名<br />（如是澳新连线，请提供两份在校证明）<br />如是假期不方便提供在校证明，可用学生证复印件替代', 1, 1, 'V20030', '1610000002', '2012-09-29 17:15:58.963000', NULL, NULL, 1, 1, 0, 7);
INSERT INTO `visa_data` VALUES (1026, 'V120929002344', 'V120929002275', '护照', '①归国后还有6个月以上有效期<br />②末页必须有持证人中文亲笔签名<br />③至少留有2页空白签证页（不是备注页）<br />④如有旧护照请一并提供。<br />⑤不接收半年内有澳大利亚拒签章的护照；不接收在澳大利亚非法滞留过的护照', 1, 0, 'V20030', '1610000002', '2012-09-29 17:18:10.080000', NULL, NULL, 1, 1, 1, 1);
