INSERT INTO `visa_data` VALUES (1030, 'V120929002349', 'V120929002275', '团队旅游保证金 ', '担保金5万/人，我司将根据您的材料情况，酌情增加担保金的额度。随团回国后凭护照给予返还。如发生滞留不归或违反当地相关法律的情况，担保金将不予退还。（建议使用渣打银行“创享旅游服务”，旅游保证金交纳不烦恼）', 1, 0, 'V20030', '1610000002', '2012-09-29 17:18:10.293000', NULL, NULL, 1, 1, 1, 8);
INSERT INTO `visa_data` VALUES (1031, 'V120929002350', 'V120929002275', '特别提醒', '①如有拒签记录，请如实提供亲笔签名的拒签说明书。并提供本人名下近6个月银行对账单。<br />②如在澳大利亚和新西兰有亲戚，请提供其在当地的电话，地址；护照复印件和签证页复印件。<br />③我公司保留索要补充资料的权利', 1, 0, 'V20030', '1610000002', '2012-09-29 17:18:10.320000', NULL, NULL, 1, 1, 1, 9);
INSERT INTO `visa_data` VALUES (1032, 'V120929002351', 'V120929002275', '相关证明 ', '18岁以下学生请根据出行情况提供以下材料： <br />（1）若与父母同行，须提供出生证原件；<br />（2）若只与父母一方出行，须提供出生证原件、不同行方的中文同意信和父母双方的身份证复印件；<br />（3）若与亲戚朋友出行，须提供出生证原件、父母双方的中文同意信和身份证复印件；<br />注：1、出生证上所显示的信息要打印版本，如子女的姓名是手工填写的，需在手工填写姓名的地方加盖医院公章；如出生证上的所有信息均为手工填写的，必须保持笔迹一致，否则也要在姓名的地方加盖医院公章（医院公章应与出生证右下方公章一致）。<br />2、如无法提供符合要求的出生证，可以用中英文亲属关系公证书代替，但不可以用独生子女证代替<br />3、中英文亲属关系公证书申请人必须为儿童本人<br />4、同意信具体格式内容请参照样本（此表格由十八岁以下申请人的不随行父母填写）', 1, 0, 'V20030', '1610000002', '2012-09-29 17:18:10.363000', NULL, NULL, 1, 1, 0, 5);
INSERT INTO `visa_data` VALUES (1033, 'V120929002352', 'V120929002275', '存款证明 ', '<div class=\"align_l\">银行开具的已有3个月存入期的至少5万元的定期存款证明原件（此原件不退）。存款证明必须注明已冻结，冻结至旅行归来1个月后。<br />可以提供父母名下的资产，如房产，车产等。</div>', 0, 0, 'V20030', '1610000002', '2012-09-29 17:18:10.410000', NULL, NULL, 1, 1, 0, 6);
INSERT INTO `visa_data` VALUES (1035, 'V120929002356', 'V120929002275', '公证书办理须知： ', '1、上海市户口的申请人在市区级公证处均可以办理公证书。部分公证处联系方式以供参考：静安区公证处 (电话：62671801、32170441)、杨浦区公证处（电话：65899528）、浦东新区公证处（电话：58396060、58395050）。 <br />2、请在去公证处前先准备齐全资料，可以缩短公证书的办理时间。<br />办理亲属关系公证书所需材料：<br />-父母和子女的身份证及户口本原件<br />-结婚证书原件<br />-子女出生证或独生子女证原件', 1, 1, 'V20030', '1610000002', '2012-09-29 17:19:43.160000', NULL, NULL, 1, 1, 0, 7);
INSERT INTO `visa_data` VALUES (1036, 'V120929002359', 'V120929002276', '护照', '①归国后还有6个月以上有效期<br />②末页必须有持证人中文亲笔签名<br />③至少留有2页空白签证页（不是备注页）<br />④如有旧护照请一并提供。<br />⑤不接收半年内有澳大利亚拒签章的护照；不接收在澳大利亚非法滞留过的护照', 1, 0, 'V20030', '1610000002', '2012-09-29 17:22:19.517000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (1037, 'V120929002360', 'V120929002276', '照片', '半年内拍摄的2寸(3.5cmx4.5cm)白底彩照3张(照片背面签字) （如是澳新连线是4张）', 1, 0, 'V20030', '1610000002', '2012-09-29 17:22:19.637000', NULL, NULL, 1, 3, 0, 2);
INSERT INTO `visa_data` VALUES (1038, 'V120929002361', 'V120929002276', '身份证', '本人身份证正反面复印件。', 1, 0, 'V20030', '1610000002', '2012-09-29 17:22:19.727000', NULL, NULL, 0, 1, 0, 3);
INSERT INTO `visa_data` VALUES (1039, 'V120929002362', 'V120929002276', '户口簿', '户口整本复印件（须复印到第一页空白页）<br />如是集体户口，需提供户主页和本人页复印件', 1, 0, 'V20030', '1610000002', '2012-09-29 17:22:19.753000', NULL, NULL, 0, 1, 0, 4);
INSERT INTO `visa_data` VALUES (1040, 'V120929002363', 'V120929002276', '个人资料表', '填写真实完整并本人亲笔签字，并请将本人的父母、兄弟姐妹、子女的详细资料认真如实填写。特别注意是否有亲戚在国外,是否有过拒签。', 1, 0, 'V20030', '1610000002', '2012-09-29 17:22:19.790000', NULL, NULL, 1, 1, 0, 5);
INSERT INTO `visa_data` VALUES (1041, 'V120929002365', 'V120929002276', '结婚证/离婚证', '凡有婚姻状况，均需要提供结婚证或者离婚证复印件。', 1, 0, 'V20030', '1610000002', '2012-09-29 17:22:19.843000', NULL, NULL, 0, 1, 0, 6);
INSERT INTO `visa_data` VALUES (1042, 'V120929002366', 'V120929002276', '资产证明（必须提供） ', '<p>① 银行开具的本人名下的已有3个月存入期的至少5万元的定期存款证明原件（此原件不退）。</p><p>注：存款证明必须注明已冻结，冻结至旅行回来1个月后。</p>②能证明是本人所有的存折或一卡通账户的近半年对帐单（上面需有清晰的户主姓名和卡号，以及银行的盖章），资金的进出金额、进出频率以及余额要尽可能丰富。', 1, 0, 'V20030', '1610000002', '2012-09-29 17:22:19.870000', NULL, NULL, 1, 1, 0, 7);
INSERT INTO `visa_data` VALUES (1043, 'V120929002367', 'V120929002276', '资产证明（选择提供） ', '为了提高您的出签率，以下材料请尽可能多提供： （可以是配偶名下的资产证明，同时提供结婚证复印件）<br />A.提供半年有效期存单5万元以上复印件（定期或活期都可）<br />B.房产证复印件<br />C.车产证复印件或行驶证复印件<br />D.股票交割单原件需加盖柜台章或其他资金证明，且余额在5万以上', 1, 0, 'V20030', '1610000002', '2012-09-29 17:22:19.900000', NULL, NULL, 0, 1, 0, 9);
INSERT INTO `visa_data` VALUES (1044, 'V120929002368', 'V120929002276', '团队旅游保证金 ', '担保金5万/人，我司将根据您的材料情况，酌情增加担保金的额度。随团回国后凭护照给予返还。如发生滞留不归或违反当地相关法律的情况，担保金将不予退还。（建议使用渣打银行“创享旅游服务”，旅游保证金交纳不烦恼）', 1, 0, 'V20030', '1610000002', '2012-09-29 17:22:19.927000', NULL, NULL, 1, 1, 1, 10);
INSERT INTO `visa_data` VALUES (1045, 'V120929002369', 'V120929002276', '特别提醒', '①如有拒签记录，请如实提供亲笔签名的拒签说明书。并提供本人名下近6个月银行对账单。<br />②如在澳大利亚和新西兰有亲戚，请提供其在当地的电话，地址；护照复印件和签证页复印件。<br />③我公司保留索要补充资料的权利', 1, 0, 'V20030', '1610000002', '2012-09-29 17:22:20.070000', NULL, NULL, 1, 1, 1, 11);
INSERT INTO `visa_data` VALUES (1046, 'V120929002371', 'V120929002276', '工作情况（选择提供） ', '如是个体户请提供本人营业执照复印件；<br />如果有失业证或社区失业证明，请提供复印件；<br />如果有无业证，请提供复印件。', 1, 1, 'V20030', '1610000002', '2012-09-29 17:23:02.190000', NULL, NULL, 0, 1, 0, 8);
