INSERT INTO `visa_data` VALUES (1074, 'V121008000069', 'V121008000032', '在校学生', '小于18周岁的未成年人：<br />A：随父母旅游，需提供亲属关系公证书原件；<br />B：随父母一方去旅游，必须提供亲属关系公证书及另一方的委托授权书；<br />C：单独旅游领馆不受理，必须有大人的陪同，非父母的陪同，需提供亲属关系公证书原件及委托书公证书原件。<br />（公证书需中英文对照翻译，且公证件一律不退还）。<br />已满18周岁的学生：<br />A：随父母旅游，提供学籍卡或学生证原件、学校准假证明以及能证明其亲属关系的户口本复印件；<br />B：单独旅游：提供学籍卡或学生证原件、学校准假证本人的有效期3个月以上，金额5万以上的银行存款证明。若提供父母存款证明，另须附加出生证。<br />（注：学校的准假证明，必须写明在肯尼亚的停留天数以及会按时返回中国的字样）<br /><br />', 1, 1, 'V20032', '1610000002', '2012-10-08 14:26:01.220000', NULL, NULL, 1, 1, 1, 4);
INSERT INTO `visa_data` VALUES (1075, 'V121008000071', 'V121008000033', '护照', '有效期半年以上的护照，空白签证页2张以上（护照上有换发或补发字样，必须提供旧护照，无旧护照必须提供护照的遗失证明原件）', 1, 0, 'V20032', '1610000002', '2012-10-08 14:26:16.007000', NULL, NULL, 1, 2, 1, 1);
