INSERT INTO `visa_data` VALUES (1114, 'V121008000206', 'V121008000194', '在职证明', '<p>提供英文在职证明。在职证明中必须包含公司抬头，加盖公司公章或人事章，有公司负责人亲笔签名。空格处内容不可手写。公司负责人可以是法人代表、总经理、部门主管或人事主管。注：出行人不能为自己签名（除非是法人代表，可以为自己的在职证明签名）同行人不可以互相签名。（在职证明内须注明月薪、职务）<br /></p>', 1, 1, 'V10036', '1610000002', '2012-10-08 17:40:58.910000', NULL, NULL, 1, 1, 0, 4);
