INSERT INTO `visa_data` VALUES (1167, 'V121009000346', 'V121009000345', '护照', 'A  1本原件有效期至少半年以上，护照后需有个人本人签名<br />B  有旧护照，则必须提供原件，老护照后也必须本人签名<br />C  若申请人旧护照遗失，则必须提供旧护照的遗失证明（即客人自己写一份遗失说明并签字或者公安机关开具的遗失证明）<br />D  若申请者在以往申请欧洲签证过程中，有被拒签的记录显示，请提供说明。（即客人自己写一份拒签理由并签字即可。）<br />E 有 2 张以上的空白可用页', 0, 1, 'V20037', '1610000002', '2012-10-09 10:57:18.150000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1168, 'V121009000349', 'V121009000345', '照片', '4张最近半年内白底彩色照片，照片大小为（3.5*4.5）厘米：<br />A  从头发最高处至下颚占全部相片高度的70%-80%<br />B  4张并在背后附签名<br />C  务必请配合清晰的露出五官。 ', 1, 1, 'V20037', '1610000002', '2012-10-09 10:57:18.340000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1169, 'V121009000350', 'V121009000345', '个人资料表', '1份字迹清晰、内容真实无误、填写完整的个人资料表（尤其是父母姓名不管其在世或者离世）', 1, 1, 'V20037', '1610000002', '2012-10-09 10:57:18.430000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1170, 'V121009000352', 'V121009000345', '英文申请表', '1份需提供两处签名：A3<br />A  英文表格的37项本人签名；<br />B  英文表格最后一栏，右侧签名。', 0, 1, 'V20037', '1610000002', '2012-10-09 10:57:18.473000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1171, 'V121009000355', 'V121009000345', '户口薄', 'A  1份申请人全家的户口薄复印件（包括首页，备注页，不能有缺页）<br />B  若夫妻不在同一口薄上，请提供配偶的完整口薄复印件（包括首页，备注页，不能有缺页）<br />C  户口薄全本必须机打，不收手写<br />D  申请人的户口薄所有信息（包括婚姻状况、工作单位、职务、学历等）必须要与现在的实际情况相一致', 1, 1, 'V20037', '1610000002', '2012-10-09 10:57:18.517000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1172, 'V121009000356', 'V121009000345', '结婚证/离婚证', 'A  申请人为已婚身份，请提供1份结婚证复印件<br />B  申请人为离婚身份，请提供离婚证复印件 ', 1, 1, 'V20037', '1610000002', '2012-10-09 10:57:18.537000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1173, 'V121009000357', 'V121009000345', '在职证明', '2份申请人所在公司的正式公函原件：<br />A  要有供领馆查询的准确单位地址、单位电话；有单位名称抬头、公章、负责人签名（申请人若为公司法人代表或负责人，签字人不能为本人）。<br />B  内容包括：申请人在公司的职务、月薪，在现在工作单位工作时间、此行目的、行程日期、准假天数、说明谁承担费用并保证其遵守当地法律以及按时返回中国，公司保证申请人回国后保留其职务。<br />C  用英文打印，手写无效，请勿在上面标注“仅供签证使用”等字样。', 1, 1, 'V20037', '1610000002', '2012-10-09 10:57:18.553000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1174, 'V121009000358', 'V121009000345', '营业执照', 'A  1份申请人为企业性质的公司：提供有经营范围的营业执照<br />B  申请人为非企业性质的公司：提供组织机构代码证<br />C  营业执照和组织机构代码证均为清晰的复印件并加盖公司公章<br />D  营业执照或组织机构代码证上必须有近一年内的年检章', 1, 1, 'V20037', '1610000002', '2012-10-09 10:57:18.570000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1175, 'V121009000359', 'V121009000345', '资产证明', 'A  各类房产证明复印件、汽车行使证复印件等一切可以证明申请人经济情况的材料此类文件非常重要，（如果有的话，请尽可能多的提供这方面材料，有利于提高出签率）', 1, 1, 'V20037', '1610000002', '2012-10-09 10:57:18.590000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1176, 'V121009000360', 'V121009000345', '银行对账单', 'A  1份能证明是本人所有的存折或一卡通账户近半年对帐单，资金的进出金额、进出频率以及余额要尽可能丰富，余额不低于一万。<br />B  信用卡对账单只能作为补充材料，不能替代银行对账单。<br />C  若申请人为公司法人代表，请提供该公司近3月缴纳的税单，可以是国税也可以是地税，网上缴款凭证也可。 ', 1, 1, 'V20037', '1610000002', '2012-10-09 10:57:18.607000', NULL, NULL, 0, 1, 0, 0);
