INSERT INTO `visa_data` VALUES (1196, 'V121009000390', 'V121009000383', '英文申请表', '1份需提供两处签名：A3<br />A  英文表格的37项本人签名；<br />B  英文表格最后一栏，右侧签名。', 0, 0, 'V20037', '1610000002', '2012-10-09 10:57:19.160000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1197, 'V121009000393', 'V121009000383', '户口薄', 'A  1份申请人全家的户口薄复印件（包括首页，备注页，不能有缺页）<br />B  若夫妻不在同一口薄上，请提供配偶的完整口薄复印件（包括首页，备注页，不能有缺页）<br />C  户口薄全本必须机打，不收手写<br />D  申请人的户口薄所有信息（包括婚姻状况、工作单位、职务、学历等）必须要与现在的实际情况相一致', 1, 0, 'V20037', '1610000002', '2012-10-09 10:57:19.203000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1198, 'V121009000394', 'V121009000383', '资产证明', 'A  各类房产证明复印件、汽车行使证复印件等一切可以证明申请人经济情况的材料此类文件非常重要，（如果有的话，请尽可能多的提供这方面材料，有利于提高出签率）', 1, 0, 'V20037', '1610000002', '2012-10-09 10:57:19.220000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1199, 'V121009000395', 'V121009000383', '银行对账单', 'A  1份能证明是本人所有的存折或一卡通账户近半年对帐单，资金的进出金额、进出频率以及余额要尽可能丰富，余额不低于一万。<br />B  信用卡对账单只能作为补充材料，不能替代银行对账单。<br />C  若申请人为公司法人代表，请提供该公司近3月缴纳的税单，可以是国税也可以是地税，网上缴款凭证也可。 ', 1, 0, 'V20037', '1610000002', '2012-10-09 10:57:19.240000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1200, 'V121009000396', 'V121009000383', '身份证', '1份身份证必须在有效期内，新版身份证必须正反两面复印', 1, 0, 'V20037', '1610000002', '2012-10-09 10:57:19.257000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1201, 'V121009000397', 'V121009000383', '学校准假证明', '1份申请人所在学校证明原件：<br />A  有学校抬头信笺、学校负责人签字、学校盖章。<br />B  内容包含：申请人的姓名、性别、班级，出行时间、目的，费用承担方，并保证其按时回国等。<br />C  必须为A4或学校信纸打印英文，手写无效。<br />D  如学生处于升学期间、须提供毕业证书复印件以及录取通知书复印件。', 0, 1, 'V20037', '1610000002', '2012-10-09 10:57:19.273000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1202, 'V121009000399', 'V121009000383', '公证认证', 'A  1份与父母双方一同出行的，提供省、市或区县级公证处出具的出生公证书。<br />B  与父母一方出行的，在原有出生公证的基础上，另需提供一份不出行一方的委托公证书原件（内容主要是同意小孩随另一方出国旅游，18周岁以上可以不提供）<br />C  所有公证书必须是涉外公证书，即需附有英文翻译件的公证书<br />D  公证书需要经过外办认证。<br />注：18周岁以下及18周岁以上在校生，仅假期内可以申请签证。', 0, 1, 'V20037', '1610000002', '2012-10-09 10:57:19.307000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1203, 'V121009000401', 'V121009000383', '团队旅游保证金 ', '根据您的材料情况进行审核收取，一般为5万元/人起，我司有根据您的材料情况，酌情增加担保金的额度。您也可选择渣打银行或建设银行（办理三方协议。A流程：只限旅游保证金；或者B流程，旅游保证金加存款冻结证明）或详询客服。', 1, 0, 'V20037', '1610000002', '2012-10-09 10:57:19.337000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1204, 'V121009000402', 'V121009000383', '特殊提醒 ', 'A.领馆保留索要补充资料和要求申请者面试的权利。 B.消签要求：团队回国后护照原件需在48小时内至领馆销签，同时需附上往返登机牌（登机牌不退还）。领馆保留要求申请者面试消签的权利。', 1, 0, 'V20037', '1610000002', '2012-10-09 10:57:19.353000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1205, 'V121009000404', 'V121009000403', '护照', 'A  1本原件有效期至少半年以上，护照后需有个人本人签名<br />B  有旧护照，则必须提供原件，老护照后也必须本人签名<br />C  若申请人旧护照遗失，则必须提供旧护照的遗失证明（即客人自己写一份遗失说明并签字或者公安机关开具的遗失证明）<br />D  若申请者在以往申请欧洲签证过程中，有被拒签的记录显示，请提供说明。（即客人自己写一份拒签理由并签字即可。）<br />E 有 2 张以上的空白可用页', 1, 0, 'V20037', '1610000002', '2012-10-09 10:57:19.400000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1206, 'V121009000407', 'V121009000403', '照片', '4张最近半年内白底彩色照片，照片大小为（3.5*4.5）厘米：<br />A  从头发最高处至下颚占全部相片高度的70%-80%<br />B  4张并在背后附签名<br />C  务必请配合清晰的露出五官。 ', 1, 0, 'V20037', '1610000002', '2012-10-09 10:57:19.443000', NULL, NULL, 0, 1, 0, 0);
