INSERT INTO `visa_data` VALUES (1393, 'V121011000756', 'V121011000743', '身份证', '1份身份证必须在有效期内，新版身份证必须正反两面复印', 1, 0, 'V20040', '1610000002', '2012-10-11 14:27:11.000000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1396, 'V121011000759', 'V121011000743', '收入来源证明 ', '<p><span style=\"font-family:宋体;color:black;font-size:9.0pt;background:#FEFEFE;\"></span>请提供本人收人情况说明，资金来源。<br />A.无业未婚的;a.提供父母的在职证明，营业执照，6个月工资单<br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; b.父母的出资说明 和资产证明<br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;c.申请人本人名下的6个月对账单<br />B.无业离婚的，提供自己有效的经济来源及申请人本人名下的6个月对账单<br />C.无业已婚的：<br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; a..配偶工作单位出具的英文在职证明原件，需使用单位抬头纸打印加盖公章、签字并明确日期及如下信息：单位地址、电话、传真号码，单位签字人员的姓名和职务，申请人配偶的姓名、职务、收入和工作年限。<br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;b..配偶的6个月工资卡对账单盖银行章。<br />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;c.配偶出具的经济担保证明书（内容需包含：担保出行人在签证有效期内按时回国，且承担其出行的所有费用）。<span style=\"font-family:宋体;color:black;font-size:9.0pt;background:#FEFEFE;\"></span></p>', 1, 1, 'V20040', '1610000002', '2012-10-11 14:27:11.050000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1398, 'V121011000764', 'V121011000763', '护照', 'A  1本原件有效期至少半年以上，护照后需有个人本人签名<br />B  有旧护照，则必须提供原件，老护照后也必须本人签名<br />C  若申请人旧护照遗失，则必须提供旧护照的遗失证明（即客人自己写一份遗失说明并签字或者公安机关开具的遗失证明）<br />D  若申请者在以往申请欧洲签证过程中，有被拒签的记录显示，请提供说明。（即客人自己写一份拒签理由并签字即可。）<br />E 有 2 张以上的空白可用页', 0, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.560000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1399, 'V121011000767', 'V121011000763', '照片', '4张最近半年，大小为两寸白底彩照：<br />A  宽26-35毫米，长32-45毫米<br />B  在背后附签名<br />C  务必请配合清晰的露出五官。 ', 1, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.623000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1400, 'V121011000768', 'V121011000763', '个人资料表', '1份字迹清晰、内容真实无误、填写完整的个人资料表（尤其是父母姓名不管其在世或者离世）必需填写联系方式（手机，电子邮箱）', 1, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.647000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1401, 'V121011000770', 'V121011000763', '英文申请表', '1份需提供两处签名：<br />A  英文表格的37项本人签名；<br />B  英文表格最后一栏，右侧签名。', 0, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.680000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1402, 'V121011000774', 'V121011000763', '户口薄', 'A  1份申请人全家的户口薄原件及全套户口本复印件（包括首页，备注页，空白页不能有缺页）护照上没有任何大国的出境记录的话，建议更改服务处所。<br />B  若夫妻不在同一口薄上，请提供配偶所在户口本的完整户口本原件及全套复印件（包括首页，备注页，不能有缺页）<br />C  户口薄全本必须机打，不收手写', 1, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.753000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1403, 'V121011000775', 'V121011000763', '结婚证/离婚证', 'A  申请人为已婚身份，请提供1份结婚证复印件<br />B  申请人为离婚身份，请提供离婚证复印件 ', 1, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.790000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1404, 'V121011000776', 'V121011000763', '在职证明', '2份申请人所在公司的正式公函原件：<br />A  要有供领馆查询的准确单位地址、单位电话及传真号；有单位名称抬头、公章、负责人签名和职务（申请人若为公司法人代表或负责人，签字人不能为本人，可以是副经理，财务主管，办公室主任等公司高管）。<br />B  内容包括：申请人在公司的职务、月薪，在现在工作单位工作年限、此行目的、行程日期、准假天数、说明谁承担费用并保证其遵守当地法律以及按时返回中国，公司保证申请人回国后保留其职务。<br />C  用英文打印，手写无效，请勿在上面标注“仅供签证使用”等字样。<br />D．如申请人为公安部门警察类职员，出具的担保函必须由其所在单位的政治部盖章签字。', 1, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.807000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1405, 'V121011000777', 'V121011000763', '营业执照', '<p>A  1份申请人为企业性质的公司：提供有经营范围的营业执照<br />B  申请人为非企业性质的公司：提供组织机构代码证<br />■营业执照和组织机构代码证均为清晰的复印件并加盖公司公章。<br /><br /></p>', 1, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.820000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1406, 'V121011000778', 'V121011000763', '资产证明', 'A  1份最近六个月的银行活期存款对账单。注意：余额并不是审核材料的重点，主要看整体的出入帐目情况，且不接受定期存款，余额不少于1万 <br />B 股票，信用卡对账单，各类房产证明复印件、汽车行使证复印件等一切可以证明申请人经济情况的材料此类文件非常重要，（如果有的话，请尽可能多的提供这方面材料，有利于提高出签率）', 1, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.840000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1407, 'V121011000779', 'V121011000763', '税单', ' 1份若申请人为公司法人代表，请提供该公司近3月缴纳的税单，可以是国税也可以是地税，网上缴款凭证也可。', 1, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.857000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1408, 'V121011000780', 'V121011000763', '名片', '2张申请人本人的名片，内容真实无误', 1, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.873000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1409, 'V121011000781', 'V121011000763', '身份证', '1份身份证必须在有效期内，新版身份证必须正反两面复印', 1, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.890000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1410, 'V121011000782', 'V121011000763', '特殊提醒 ', 'A 领馆保留索要补充资料和要求申请者面试的权利。<br />B 销签要求：团队回国后护照原件需在48小时内至领馆销签同时需附上往返登机牌。领馆保留要求申请者面试消签的权利。<br />C 西班牙领事馆对空白护照或无大国出入境记录的申请者审核较严格。<br />D 西班牙国领事馆要求户口本原件交进领事馆，出签证时一同返还。', 1, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.907000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1411, 'V121011000783', 'V121011000763', '团队旅游保证金 ', '根据您的材料情况进行审核收取，一般为5万元/人起，我司有根据您的材料情况，酌情增加担保金的额度。您也可选择渣打银行或建设银行（办理三方协议。A流程：只限旅游保证金；或者B流程，旅游保证金加存款冻结证明）或详询客服。', 1, 1, 'V20041', '1610000002', '2012-10-11 14:27:20.923000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1412, 'V121011000785', 'V121011000784', '护照', 'A  1本原件有效期至少半年以上，护照后需有个人本人签名<br />B  有旧护照，则必须提供原件，老护照后也必须本人签名<br />C  若申请人旧护照遗失，则必须提供旧护照的遗失证明（即客人自己写一份遗失说明并签字或者公安机关开具的遗失证明）<br />D  若申请者在以往申请欧洲签证过程中，有被拒签的记录显示，请提供说明。（即客人自己写一份拒签理由并签字即可。）<br />E 有 2 张以上的空白可用页', 1, 0, 'V20041', '1610000002', '2012-10-11 14:27:20.960000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1413, 'V121011000788', 'V121011000784', '照片', '4张最近半年，大小为两寸白底彩照：<br />A  宽26-35毫米，长32-45毫米<br />B  在背后附签名<br />C  务必请配合清晰的露出五官。 ', 1, 0, 'V20041', '1610000002', '2012-10-11 14:27:21.003000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1414, 'V121011000789', 'V121011000784', '个人资料表', '1份字迹清晰、内容真实无误、填写完整的个人资料表（尤其是父母姓名不管其在世或者离世）必需填写联系方式（手机，电子邮箱）', 1, 0, 'V20041', '1610000002', '2012-10-11 14:27:21.020000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1415, 'V121011000791', 'V121011000784', '英文申请表', '1份需提供两处签名：<br />A  英文表格的37项本人签名；<br />B  英文表格最后一栏，右侧签名。', 0, 0, 'V20041', '1610000002', '2012-10-11 14:27:21.050000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1416, 'V121011000795', 'V121011000784', '户口薄', 'A  1份申请人全家的户口薄原件及全套户口本复印件（包括首页，备注页，空白页不能有缺页）护照上没有任何大国的出境记录的话，建议更改服务处所。<br />B  若夫妻不在同一口薄上，请提供配偶所在户口本的完整户口本原件及全套复印件（包括首页，备注页，不能有缺页）<br />C  户口薄全本必须机打，不收手写', 1, 0, 'V20041', '1610000002', '2012-10-11 14:27:21.103000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1417, 'V121011000796', 'V121011000784', '结婚证/离婚证', 'A  申请人为已婚身份，请提供1份结婚证复印件<br />B  申请人为离婚身份，请提供离婚证复印件 ', 1, 0, 'V20041', '1610000002', '2012-10-11 14:27:21.120000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1418, 'V121011000797', 'V121011000784', '资产证明', 'A  1份最近六个月的银行活期存款对账单。注意：余额并不是审核材料的重点，主要看整体的出入帐目情况，且不接受定期存款，余额不少于1万 <br />B 股票，信用卡对账单，各类房产证明复印件、汽车行使证复印件等一切可以证明申请人经济情况的材料此类文件非常重要，（如果有的话，请尽可能多的提供这方面材料，有利于提高出签率）', 1, 0, 'V20041', '1610000002', '2012-10-11 14:27:21.137000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1419, 'V121011000798', 'V121011000784', '身份证', '1份身份证必须在有效期内，新版身份证必须正反两面复印', 1, 0, 'V20041', '1610000002', '2012-10-11 14:27:21.153000', NULL, NULL, 0, 1, 0, 0);
