INSERT INTO `visa_data` VALUES (1421, 'V121011000800', 'V121011000784', '团队旅游保证金 ', '根据您的材料情况进行审核收取，一般为5万元/人起，我司有根据您的材料情况，酌情增加担保金的额度。您也可选择渣打银行或建设银行（办理三方协议。A流程：只限旅游保证金；或者B流程，旅游保证金加存款冻结证明）或详询客服。', 1, 0, 'V20041', '1610000002', '2012-10-11 14:27:21.190000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1422, 'V121011000801', 'V121011000784', '退休证', 'A 70周岁以上必须提供健康证明原件且内容必须包含有，医师手写证明该申请人适宜长途旅行等字样！<br />B  退休人员需要提供1份退休证复印件！<br />C  退休人员需提供本人养老金对账单，往来账不大的请额外提供其他的固定收入。', 1, 1, 'V20041', '1610000002', '2012-10-11 14:27:21.207000', NULL, NULL, 0, 1, 0, 0);
