INSERT INTO `visa_data` VALUES (1473, 'V121011000887', 'V121011000880', '英文申请表', '1份需提供两处签名：<br />A  英文表格的37项本人签名；<br />B  英文表格最后一栏，右侧签名。', 0, 0, 'V20042', '1610000002', '2012-10-11 14:27:29.177000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1474, 'V121011000890', 'V121011000880', '户口薄', 'A  1份申请人全家的户口薄复印件（包括首页，备注页，不能有缺页）<br />B  若夫妻不在同一口薄上，请提供配偶的完整口薄复印件（包括首页，备注页，不能有缺页）<br />C  户口薄全本必须机打，不收手写（针对整本户口本都是手写版本，更改服务处所，婚姻状况等除外）<br />D  如果被抽到面试的客人请携带原件前往', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:29.220000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1475, 'V121011000891', 'V121011000880', '结婚证/离婚证', 'A  申请人为已婚身份，请提供结1份婚证复印件<br />B  申请人为离婚身份，请提供离婚证复印件 <br />C  如果被抽到面试的客人请携带原件前往', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:29.240000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1476, 'V121011000892', 'V121011000880', '资产证明', 'A 各类房产证明复印件、汽车行使证复印件等一切可以证明申请人经济情况的材料此类文件非常重要，（如果有的话，请尽可能多的提供这方面材料，有利于提高出签率）<br />B 最近六个月且余额必须高于团费，经银行盖章的工资流水账单。<br />C  最近六个月的个人完税证明原件。<br />D  若申请人为公司法人代表，请提供该公司近3月缴纳的税单，可以是国税也可以是地税，网上缴款凭证也可。 <br />E  如果被抽到面试的客人请携带原件前往', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:29.257000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1477, 'V121011000893', 'V121011000880', '职业资格证', 'A  医生、律师、教师、建筑师等工作性质的人员需要提供有效的职业资格证复印件<br />B  如果被抽到面试的客人请携带原件前往', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:29.273000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1478, 'V121011000894', 'V121011000880', '名片', '2张申请人本人的名片，内容真实无误', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:29.290000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1479, 'V121011000895', 'V121011000880', '身份证', 'A  1份身份证必须在有效期内，新版身份证必须正反两面复印<br />B  如果被抽到面试的客人请携带原件前往', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:29.310000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1480, 'V121011000896', 'V121011000880', '特殊提醒', '<p>A 领馆保留索要补充资料和要求申请者面试的权利</p><p>B 浙江省签发的护照，需要到浙江省外办认证所有材料后，才可以申请希腊签证</p><p>C 浙江省签发的护照，在职证明需由浙江省外办递交给领馆</p><p>D 销签要求：团队回国后护照原件需在48小时内至领馆销签，同时需附上往返登机牌（登机牌不退还）。领馆保留要求申请者面试消签的权利</p>', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:29.327000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1481, 'V121011000897', 'V121011000880', '团队旅游保证金', '根据您的材料情况进行审核收取，一般为5万元/人起，我司有根据您的材料情况，酌情增加担保金的额度。您也可选择渣打银行或建设银行（办理三方协议。A流程：只限旅游保证金；或者B流程，旅游保证金加存款冻结证明）或详询客服。', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:29.343000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1482, 'V121011000898', 'V121011000880', '退休证', 'A  建议70周岁以上申请人提供健康证明原件！ <br />B  退休人员需要提供1份退休证复印件！<br />C  如果被抽到面试的客人请携带原件前往！', 1, 1, 'V20042', '1610000002', '2012-10-11 14:27:29.360000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1483, 'V121011000900', 'V121011000899', '护照', 'A  1本原件有效期至少半年以上，护照后需有个人本人签名<br />B  有旧护照，则必须提供原件，老护照后也必须本人签名<br />C  若申请人旧护照遗失，则必须提供旧护照的遗失证明（即客人自己写一份遗失说明并签字或者公安机关开具的遗失证明）<br />D  若申请者在以往申请欧洲签证过程中，有被拒签的记录显示，请提供说明。（即客人自己写一份拒签理由并签字即可。）<br />E 有 2 张以上的空白可用页', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:29.400000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1484, 'V121011000903', 'V121011000899', '照片', '4张最近半年内白底彩色照片，照片大小为（3.5*4.5）厘米：<br />A  从头发最高处至下颚占全部相片高度的70%-80%<br />B  4张并在背后附签名<br />C  务必请配合清晰的露出五官。 ', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:29.447000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1485, 'V121011000904', 'V121011000899', '个人资料表', '1份字迹清晰、内容真实无误、填写完整的个人资料表（尤其是父母姓名不管其在世或者离世）', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:29.467000', NULL, NULL, 0, 1, 0, 0);
