INSERT INTO `visa_data` VALUES (1507, 'V121011000944', 'V121011000934', '户口薄', 'A  1份申请人全家的户口薄复印件（包括首页，备注页，不能有缺页）<br />B  若夫妻不在同一口薄上，请提供配偶的完整口薄复印件（包括首页，备注页，不能有缺页）<br />C  户口薄全本必须机打，不收手写（针对整本户口本都是手写版本，更改服务处所，婚姻状况等除外）<br />D  如果被抽到面试的客人请携带原件前往', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:30.113000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1508, 'V121011000945', 'V121011000934', '结婚证/离婚证', 'A  申请人为已婚身份，请提供结1份婚证复印件<br />B  申请人为离婚身份，请提供离婚证复印件 <br />C  如果被抽到面试的客人请携带原件前往', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:30.130000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1509, 'V121011000946', 'V121011000934', '资产证明', 'A 各类房产证明复印件、汽车行使证复印件等一切可以证明申请人经济情况的材料此类文件非常重要，（如果有的话，请尽可能多的提供这方面材料，有利于提高出签率）<br />B 最近六个月且余额必须高于团费，经银行盖章的工资流水账单。<br />C  最近六个月的个人完税证明原件。<br />D  若申请人为公司法人代表，请提供该公司近3月缴纳的税单，可以是国税也可以是地税，网上缴款凭证也可。 <br />E  如果被抽到面试的客人请携带原件前往', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:30.147000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1510, 'V121011000947', 'V121011000934', '职业资格证', 'A  医生、律师、教师、建筑师等工作性质的人员需要提供有效的职业资格证复印件<br />B  如果被抽到面试的客人请携带原件前往', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:30.163000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1511, 'V121011000948', 'V121011000934', '身份证', 'A  1份身份证必须在有效期内，新版身份证必须正反两面复印<br />B  如果被抽到面试的客人请携带原件前往', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:30.187000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1512, 'V121011000949', 'V121011000934', '特殊提醒', '<p>A 领馆保留索要补充资料和要求申请者面试的权利</p><p>B 浙江省签发的护照，需要到浙江省外办认证所有材料后，才可以申请希腊签证</p><p>C 浙江省签发的护照，在职证明需由浙江省外办递交给领馆</p><p>D 销签要求：团队回国后护照原件需在48小时内至领馆销签，同时需附上往返登机牌（登机牌不退还）。领馆保留要求申请者面试消签的权利</p>', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:30.213000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1513, 'V121011000950', 'V121011000934', '团队旅游保证金', '根据您的材料情况进行审核收取，一般为5万元/人起，我司有根据您的材料情况，酌情增加担保金的额度。您也可选择渣打银行或建设银行（办理三方协议。A流程：只限旅游保证金；或者B流程，旅游保证金加存款冻结证明）或详询客服。', 1, 0, 'V20042', '1610000002', '2012-10-11 14:27:30.230000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1514, 'V121011000951', 'V121011000934', '自由职业者', '需提供丰富、可信的良好收入来源及其相关资产。并要有一份描述性的说明,所提供的材料要能证明自己有这个能力及实力去欧洲旅游。', 1, 1, 'V20042', '1610000002', '2012-10-11 14:27:30.260000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1515, 'V121011000952', 'V121011000934', '未就业成人/已婚者', '配偶的在职证明和收入证明+婚姻关系公证书（由外交部认证）的回执条。', 1, 1, 'V20042', '1610000002', '2012-10-11 14:27:30.277000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1516, 'V121011000955', 'V121011000954', '护照', '<p><span style=\"font-size:9pt;font-family:Arial;\">A.&nbsp;1</span><span style=\"font-size:9pt;font-family:宋体;\">本原件有效期至少半年以上，护照后需有个人本人签名</span><span style=\"font-size:9pt;font-family:Arial;\"><br /><span style=\"background:#FEFEFE;\">B. &nbsp;</span></span><span style=\"font-size:9pt;font-family:宋体;\">有旧护照，则必须提供原件，老护照后也必须本人签名</span><span style=\"font-size:9pt;font-family:Arial;\"><br /><span style=\"background:#FEFEFE;\">C. &nbsp;</span></span><span style=\"font-size:9pt;font-family:宋体;\">若申请人旧护照遗失，则必须提供旧护照的遗失证明（即客人自己写一份遗失说明并签字或者公安机关开具的遗失证明）</span><span style=\"font-size:9pt;font-family:Arial;\"><br /><span style=\"background:#FEFEFE;\">D. </span></span><span style=\"font-size:9pt;font-family:宋体;\">有</span><span style=\"font-size:9pt;font-family:Arial;\"> 2 </span><span style=\"font-size:9pt;font-family:宋体;\">张以上的空白可用页</span><span style=\"font-size:9pt;font-family:Arial;\">2.</span><span style=\"font-size:9pt;font-family:宋体;\">个人资料表一份（必须如实详填写）</span><span style=\"font-size:9pt;font-family:Arial;\">,35*45mm</span><span style=\"font-size:9pt;font-family:宋体;\">白底正面彩照</span><span style=\"font-size:9pt;font-family:Arial;\">4</span><span style=\"font-size:9pt;font-family:宋体;\">张（背面写上自己的名字）</span></p><p><span style=\"font-size:9pt;font-family:Arial;\">&nbsp;</span></p>', 0, 1, 'V20043', '1610000002', '2012-10-11 14:27:36.740000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1517, 'V121011000958', 'V121011000954', '照片', '4张最近半年内白底彩色照片，照片大小为（3.5*4.5）厘米：<br />A  从头发最高处至下颚占全部相片高度的70%-80%<br />B  4张并在背后附签名<br />C  务必请配合清晰的露出五官', 1, 1, 'V20043', '1610000002', '2012-10-11 14:27:36.793000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1518, 'V121011000959', 'V121011000954', '个人资料表', '1份字迹清晰、内容真实无误、填写完整的个人资料表。特别注意申请人的手机联系方式一定要留准确。', 0, 1, 'V20043', '1610000002', '2012-10-11 14:27:36.810000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1520, 'V121011000964', 'V121011000954', '户口薄', '<p><span style=\"font-size:9pt;font-family:宋体;\">全家户口本整本复印件：</span></p><p><span style=\"font-size:9pt;font-family:Arial;\">a.</span><span style=\"font-size:9pt;font-family:宋体;\">户口本的服务处所</span><span style=\"font-size:9pt;font-family:Arial;\">/</span><span style=\"font-size:9pt;font-family:宋体;\">职务必须与所提供公司营业执照名称一致</span></p><p><span style=\"font-size:9pt;font-family:Arial;\">b.</span><span style=\"font-size:9pt;font-family:宋体;\">爱人、小孩户口不在同一本户口本上，必须提供爱人和小孩所在户口本的整本户口本复印件</span></p><p><span style=\"font-size:9pt;font-family:Arial;\">c.</span><span style=\"font-size:9pt;font-family:宋体;\">军人提供军官证复印件</span></p>', 0, 1, 'V20043', '1610000002', '2012-10-11 14:27:36.880000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1521, 'V121011000965', 'V121011000954', '结婚证/离婚证', 'A  申请人为已婚身份，请提供1份结婚证复印件<br />B  申请人为离婚身份，请提供1份离婚证复印件', 1, 1, 'V20043', '1610000002', '2012-10-11 14:27:36.900000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1522, 'V121011000966', 'V121011000954', '在职证明', '<p><span style=\"font-size:9pt;font-family:宋体;\">在职人员提供单位工作证明信一份：（信纸必须用单位正规抬头纸，上有公司地址、电话和传真）必须盖有单位公章章、註明签字领导的姓名、职务及联系电话。（同行人不能作为证明信的签字人）</span></p><span style=\"font-size:9pt;font-family:Arial;\">&nbsp; </span><span style=\"font-size:9pt;font-family:宋体;\">工作证明信中必须注明以下内容：</span><span style=\"font-size:9pt;font-family:宋体;\">本人在公司所担任的职务、本人的收入、休假时间许可，保证其遵守法律以及在行程后按时回国并继续就职，并标注营业执照号码。</span><br />', 0, 1, 'V20043', '1610000002', '2012-10-11 14:27:36.917000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1523, 'V121011000967', 'V121011000954', '营业执照', '<p><span style=\"font-size:9pt;font-family:宋体;\">申请人所在公司单位营业执照或组织机构代码证复印件盖红章。</span></p><br />', 0, 1, 'V20043', '1610000002', '2012-10-11 14:27:36.933000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1524, 'V121011000968', 'V121011000954', '资产证明', '<p><span style=\"font-size:9pt;font-family:宋体;\">申请人本人名下的房产证复印件</span></p><br />', 0, 1, 'V20043', '1610000002', '2012-10-11 14:27:36.950000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1525, 'V121011000969', 'V121011000954', '银行对账单', '<p><span style=\"font-size:9pt;font-family:宋体;\">申请人本人名下对账单</span><span style=\"font-size:9pt;font-family:Arial;\">:</span><span style=\"font-size:9pt;font-family:宋体;\">盖有银行公章的近</span><span style=\"font-size:9pt;font-family:Arial;\">6</span><span style=\"font-size:9pt;font-family:宋体;\">个月完整工资的对帐单（余额不要低于</span><span style=\"font-size:9pt;font-family:Arial;\">1</span><span style=\"font-size:9pt;font-family:宋体;\">万元）</span></p><br />', 0, 1, 'V20043', '1610000002', '2012-10-11 14:27:36.970000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1527, 'V121011000971', 'V121011000954', '身份证', '<p><span style=\"font-size:9pt;font-family:宋体;\">身份证必须在有效期内，须正反两面复印。</span></p>', 0, 1, 'V20043', '1610000002', '2012-10-11 14:27:37.007000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1530, 'V121011000975', 'V121011000974', '护照', 'A  1本原件有效期至少半年以上，护照后需有个人本人签名<br />B  有旧护照，则必须提供原件，老护照后也必须本人签名<br />C  若申请人旧护照遗失，则必须提供旧护照的遗失证明（即客人自己写一份遗失说明并签字或者公安机关开具的遗失证明）<br />D  若申请者在以往申请欧洲签证过程中，有被拒签的记录显示，请提供说明。（即客人自己写一份拒签理由并签字即可。）<br />E 有 2 张以上的空白可用页', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.117000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1531, 'V121011000978', 'V121011000974', '照片', '4张最近半年内白底彩色照片，照片大小为（3.5*4.5）厘米：<br />A  从头发最高处至下颚占全部相片高度的70%-80%<br />B  4张并在背后附签名<br />C  务必请配合清晰的露出五官', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.190000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1532, 'V121011000979', 'V121011000974', '个人资料表', '1份字迹清晰、内容真实无误、填写完整的个人资料表。特别注意申请人的手机联系方式一定要留准确。', 0, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.210000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1534, 'V121011000984', 'V121011000974', '户口薄', 'A  1份申请人全家的户口薄复印件（包括首页，备注页，不能有缺页）<br />B  若夫妻不在同一口薄上，请提供配偶的完整口薄复印件（包括首页，备注页，不能有缺页）<br />C  户口薄全本必须机打，不收手写', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.287000', NULL, NULL, 0, 1, 0, 0);
