INSERT INTO `visa_data` VALUES (1536, 'V121011000986', 'V121011000974', '资产证明', '各类房产证明复印件、汽车行使证复印件等一切可以证明申请人经济情况的材料此类文件非常重要，（如果有的话，请尽可能多的提供这方面材料，有利于提高出签率）', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.333000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1537, 'V121011000987', 'V121011000974', '银行对账单', 'A  1份能证明是本人所有的存折或一卡通账户近半年对帐单，资金的进出金额、进出频率以及余额要尽可能丰富，余额不低于1万。<br />B  信用卡对账单只能作为补充材料，不能替代银行对账单。<br />C  若申请人为公司法人代表，请提供该公司近3月缴纳的税单，可以是国税也可以是地税，网上缴款凭证也可。', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.363000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1538, 'V121011000988', 'V121011000974', '名片', '2张申请人本人的名片，内容真实无误', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.383000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1539, 'V121011000989', 'V121011000974', '身份证', '1份身份证必须在有效期内，新版身份证必须正反两面复印', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.400000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1540, 'V121011000990', 'V121011000974', '备注', '<div>&nbsp;A.领馆保留索要补充资料和要求申请者面试的权利，需本人按领馆要求前往领馆面试或递交补充材料。<br />B.签证由领馆签发，即使客人提供全部材料，也不能保证获得签证。<br />C.所有签证材料不得加注仅供签证使用字樣。<br /></div>', 0, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.417000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1542, 'V121011000992', 'V121011000974', '退休证', 'A  建议70周岁以上申请人员提供健康证明原件！<br />B  退休人员需要提供1份退休证复印件！', 1, 1, 'V20043', '1610000002', '2012-10-11 14:27:37.450000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1543, 'V121011000994', 'V121011000993', '护照', 'A  1本原件有效期至少半年以上，护照后需有个人本人签名<br />B  有旧护照，则必须提供原件，老护照后也必须本人签名<br />C  若申请人旧护照遗失，则必须提供旧护照的遗失证明（即客人自己写一份遗失说明并签字或者公安机关开具的遗失证明）<br />D  若申请者在以往申请欧洲签证过程中，有被拒签的记录显示，请提供说明。（即客人自己写一份拒签理由并签字即可。）<br />E 有 2 张以上的空白可用页', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.490000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1544, 'V121011000997', 'V121011000993', '照片', '4张最近半年内白底彩色照片，照片大小为（3.5*4.5）厘米：<br />A  从头发最高处至下颚占全部相片高度的70%-80%<br />B  4张并在背后附签名<br />C  务必请配合清晰的露出五官', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.533000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1545, 'V121011000998', 'V121011000993', '个人资料表', '1份字迹清晰、内容真实无误、填写完整的个人资料表。特别注意申请人的手机联系方式一定要留准确。', 0, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.550000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1547, 'V121011001003', 'V121011000993', '户口薄', 'A  1份申请人全家的户口薄复印件（包括首页，备注页，不能有缺页）<br />B  若夫妻不在同一口薄上，请提供配偶的完整口薄复印件（包括首页，备注页，不能有缺页）<br />C  户口薄全本必须机打，不收手写', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.623000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1548, 'V121011001004', 'V121011000993', '资产证明', '各类房产证明复印件、汽车行使证复印件等一切可以证明申请人经济情况的材料此类文件非常重要，（如果有的话，请尽可能多的提供这方面材料，有利于提高出签率）', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.640000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1549, 'V121011001005', 'V121011000993', '银行对账单', 'A  1份能证明是本人所有的存折或一卡通账户近半年对帐单，资金的进出金额、进出频率以及余额要尽可能丰富，余额不低于1万。<br />B  信用卡对账单只能作为补充材料，不能替代银行对账单。<br />C  若申请人为公司法人代表，请提供该公司近3月缴纳的税单，可以是国税也可以是地税，网上缴款凭证也可。', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.657000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1550, 'V121011001006', 'V121011000993', '身份证', '1份身份证必须在有效期内，新版身份证必须正反两面复印', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.673000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1551, 'V121011001007', 'V121011000993', '备注', '<div>&nbsp;A.领馆保留索要补充资料和要求申请者面试的权利，需本人按领馆要求前往领馆面试或递交补充材料。<br />B.签证由领馆签发，即使客人提供全部材料，也不能保证获得签证。<br />C.所有签证材料不得加注仅供签证使用字樣。<br /></div>', 0, 0, 'V20043', '1610000002', '2012-10-11 14:27:37.690000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1553, 'V121011001009', 'V121011000993', '学校准假证明', '1份申请人所在学校证明原件：<br />A  有学校抬头信笺、学校负责人签字、学校盖章；<br />B  内容包含：申请人的姓名、性别、班级，出行时间、目的，费用承担方，并保证其按时回国等；<br />C  必须为A4或学校信纸打印英文，手写无效。<br />D  如学生处于升学期间、须提供毕业证书复印件以及录取通知书复印件。', 0, 1, 'V20043', '1610000002', '2012-10-11 14:27:37.727000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1554, 'V121011001011', 'V121011000993', '公证认证', 'A  1份与父母双方一同出行的，提供省、市或区县级公证处出具的出生公证书<br />B  与父母一方出行的，在原有出生公证的基础上，另需提供一份不出行一方的委托公证书原件（内容主要是同意小孩随另一方出国旅游，18周岁以上可以不提供）<br />C  所有公证书必须是涉外公证书，即需附有英文翻译件的公证书<br />D  公证书需要经过外办认证<br />注：18周岁以下及18周岁以上在校生，仅假期内可以申请签证', 0, 1, 'V20043', '1610000002', '2012-10-11 14:27:37.757000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1564, 'V121011001030', 'V121011001029', '护照', 'A  1本原件有效期至少半年以上，护照后需有个人本人签名<br />B  有旧护照，则必须提供原件，老护照后也必须本人签名<br />C  若申请人旧护照遗失，则必须提供旧护照的遗失证明（即客人自己写一份遗失说明并签字或者公安机关开具的遗失证明）<br />D  若申请者在以往申请欧洲签证过程中，有被拒签的记录显示，请提供说明。（即客人自己写一份拒签理由并签字即可。）<br />E 有 2 张以上的空白可用页', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:38.073000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1565, 'V121011001033', 'V121011001029', '照片', '4张最近半年内白底彩色照片，照片大小为（3.5*4.5）厘米：<br />A  从头发最高处至下颚占全部相片高度的70%-80%<br />B  4张并在背后附签名<br />C  务必请配合清晰的露出五官', 1, 0, 'V20043', '1610000002', '2012-10-11 14:27:38.187000', NULL, NULL, 0, 1, 0, 0);
