INSERT INTO `visa_data` VALUES (1727, 'V121011001271', 'V121011001270', '在校学生', '在校学生签证须知<br />', 0, 0, 'V20046', '1610000002', '2012-10-11 14:28:11.480000', NULL, NULL, 0, 1, 0, 0);
