INSERT INTO `visa_data` VALUES (1767, 'V121015001335', 'V121015001334', '护照', '1.归国后还有6个月以上有效期，至少留有2页空白签证页（不是备注页）,末页必须有持证人中文亲笔签名<br />2.护照需彩色复印，包括照片页签字页及所有有内容和图章的页面。如有旧护照请一并提供。<br />3.不接收在澳大利亚非法滞留过的护照', 0, 1, 'V20047', '1610000002', '2012-10-15 10:19:36.310000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1768, 'V121015001336', 'V121015001334', '照片', '半年内拍摄的2寸(3.5cmx4.5cm)白底彩照3张(照片背面签字) （如是澳新连线是4张）', 1, 1, 'V20047', '1610000002', '2012-10-15 10:19:36.340000', NULL, NULL, 0, 1, 0, 0);
