INSERT INTO `visa_data` VALUES (1770, 'V121015001338', 'V121015001334', '身份证', '本人身份证正反面彩色复印件。', 0, 1, 'V20047', '1610000002', '2012-10-15 10:19:36.380000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1771, 'V121015001339', 'V121015001334', '户口簿', '户口整本彩色复印件，复印所有有内容的页面。<br />如是集体户口，需提供户主页和本人页彩色复印件', 0, 1, 'V20047', '1610000002', '2012-10-15 10:19:36.397000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1772, 'V121015001340', 'V121015001334', '个人资料表', '填写真实完整并本人亲笔签字，并请将本人的父母、兄弟姐妹、子女的详细资料认真如实填写。特别注意是否有亲戚在国外,是否有过拒签。', 1, 1, 'V20047', '1610000002', '2012-10-15 10:19:36.413000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1773, 'V121015001342', 'V121015001334', '结婚证/离婚证', '凡有婚姻状况，均需要提供结婚证或者离婚证复印件。', 1, 1, 'V20047', '1610000002', '2012-10-15 10:19:36.450000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1774, 'V121015001343', 'V121015001334', '在职证明/准假信', '1.提供英文在职证明不接受空白信纸，必须包含准假信息，公司抬头，加盖公司公章或人事章，有公司负责人亲笔签名。公司负责人可以是法人代表、总经理、部门主管或人事主管。<br />2.本人单位营业执照（或组织机构代码证）复印件并加盖公章。<br />（如是澳新连线，请提供两份在职证明、两份营业执照）', 0, 1, 'V20047', '1610000002', '2012-10-15 10:19:36.467000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1775, 'V121015001344', 'V121015001334', '资产证明（必须提供） ', '<p>1.本人的存折或借记卡的近半年流水单（上面需有清晰的户主姓名和卡号，以及银行的盖章），余额要可以覆盖此次旅行的。&nbsp;</p>2.银行开具的本人名下的已有3个月存入期的至少5万元的定期存款证明复印件（如交原件则原件不退）。', 0, 1, 'V20047', '1610000002', '2012-10-15 10:19:36.483000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1776, 'V121015001345', 'V121015001334', '资产证明（选择提供） ', '为了提高您的出签率，以下材料请尽可能多提供： （可以是配偶名下的资产证明，同时提供结婚证复印件）<br />A.房产证复印件<br />B.车产证复印件<br />C.行驶证复印件<br />D.股票交割单原件需加盖柜台章或其他资金证明', 0, 1, 'V20047', '1610000002', '2012-10-15 10:19:36.500000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1778, 'V121015001347', 'V121015001334', '特别提醒', '<p></p>1.如有拒签记录，请如实提供亲笔签名的拒签说明书。<br />2.如在澳大利亚亲戚的，请提供护照复印件和签证页复印件，如要探亲的 还要提供邀请函及其在当地的电话，地址。<br /><br /><p></p>', 0, 1, 'V20047', '1610000002', '2012-10-15 10:19:36.537000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1820, 'V121015001400', 'V121015001399', '护照', '①归国后还有6个月以上有效期<br />②末页必须有持证人中文亲笔签名<br />③至少留有2页空白签证页（不是备注页）<br />④如有旧护照请一并提供。<br />', 1, 1, 'V20048', '1610000002', '2012-10-15 10:19:48.970000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1821, 'V121015001401', 'V121015001399', '照片', '半年内拍摄的2寸(3.5cmx4.5cm)白底彩照3张(照片背面签字) （如是澳新连线是4张）', 1, 1, 'V20048', '1610000002', '2012-10-15 10:19:48.993000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1822, 'V121015001402', 'V121015001399', '名片 ', '2张（如有请提供）', 1, 1, 'V20048', '1610000002', '2012-10-15 10:19:49.010000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1823, 'V121015001403', 'V121015001399', '身份证', '本人身份证正反面复印件。', 1, 1, 'V20048', '1610000002', '2012-10-15 10:19:49.030000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1824, 'V121015001404', 'V121015001399', '户口簿', '户口本整本复印件（须复印到第一页空白页）<br />如果是集体户口，请提供户主页和本人页，或户籍证明原件', 1, 1, 'V20048', '1610000002', '2012-10-15 10:19:49.047000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1825, 'V121015001405', 'V121015001399', '个人资料表', '填写真实完整并本人亲笔签字，并请将本人的父母、兄弟姐妹、子女的详细资料认真如实填写。特别注意是否有亲戚在国外,是否有过拒签。', 1, 1, 'V20048', '1610000002', '2012-10-15 10:19:49.063000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1826, 'V121015001407', 'V121015001399', '结婚证/离婚证', '凡有婚姻状况，均需要提供结婚证或者离婚证复印件。', 1, 1, 'V20048', '1610000002', '2012-10-15 10:19:49.097000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1827, 'V121015001408', 'V121015001399', '在职证明', '①提供中英文在职证明一份，必须包含公司抬头，加盖公司公章或人事章，有公司负责人亲笔签名。公司负责人可以是法人代表、总经理、部门主管或人事主管。<br />②本人单位营业执照（或组织机构代码证）复印件并加盖公章。<br />（如是澳新连线，请提供两份在职证明、两份营业执照）', 1, 1, 'V20048', '1610000002', '2012-10-15 10:19:49.113000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1828, 'V121015001410', 'V121015001399', '资产证明（必须提供） ', '<p>①银行开具的本人名下的已有3个月存入期的至少5万元的定期存款证明原件（此原件不退）。</p><p>注：存款证明必须注明已冻结，冻结至旅行回来1个月后。</p><p>②能证明是本人所有的存折或一卡通账户的近半年对帐单（上面需有清晰的户主姓名和卡号，以及银行的盖章），资金的进出金额、进出频率以及余额要尽可能丰富。</p>', 1, 1, 'V20048', '1610000002', '2012-10-15 10:19:49.180000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1829, 'V121015001411', 'V121015001399', '资产证明（选择提供）', '为了提高您的出签率，以下材料请尽可能多提供：（可以是配偶名下的资产证明，同时提供结婚证复印件）<br />A.提供半年有效期存单5万元以上复印件（定期或活期都可）<br />B.房产证复印件<br />C.车产证复印件或行驶证复印件<br />D.股票交割单原件需加盖柜台章或其他资金证明，且余额在5万以上', 0, 1, 'V20048', '1610000002', '2012-10-15 10:19:49.260000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1831, 'V121015001413', 'V121015001399', '特别提醒', '①如有拒签记录，请如实提供亲笔签名的拒签说明书。有签证签出没去的，也要写一下情况说明。<br />②如在新西兰有亲戚，请提供护照复印件和签证页复印件。探亲的需提供邀请函以及其在当地的电话，地址。<br />③签证由领馆签发，即使客人提供全部材料，也不能保证获得签证。领馆保留索要补充资料和面试的权利。', 0, 1, 'V20048', '1610000002', '2012-10-15 10:19:49.430000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (1872, 'V121015001471', 'V121015001465', '中国大陆因私护照', '<span style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">（1）归国后还有6个月以上有效期</span><br style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\" /><span style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">（2）末页必须有持证人中文亲笔签名（不能用铅笔）</span><br style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\" /><span style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">（3）至少留有2页空白签证页（不是备注页）</span><br style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\" /><span style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">（4）护照首页复印件</span><br style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\" /><span style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">（5）如有旧护照请一并提供</span>', 1, 1, 'V10049', '1610000002', '2012-10-15 14:48:50.353000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (1873, 'V121015001473', 'V121015001465', '照片3张', '<span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">51mmx51mm 白底彩照3张，须一致（不接收过胸照）。</span>', 0, 1, 'V10049', '1610000002', '2012-10-15 14:49:16.320000', NULL, NULL, 1, 3, 0, 2);
INSERT INTO `visa_data` VALUES (1874, 'V121015001476', 'V121015001465', '身份证复印件', '<span style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">16周岁以上者请提供有效身份证正反面复印件一份。正反面复印在一张纸上</span><br style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\" /><span style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">如临时身份证，需在申请签证期间在有效期之内</span>', 1, 1, 'V10049', '1610000002', '2012-10-15 14:50:13.300000', NULL, NULL, 0, 1, 0, 3);
INSERT INTO `visa_data` VALUES (1875, 'V121015001478', 'V121015001465', '在职证明', '<span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">提供英文在职证明：在职证明中必须包含护照号码，出生年月，公司抬头，加盖公司公章或人事章，有公司负责人亲笔签名。公司负责人可以是法人代表、总经理、部门主管或人事主管。</span><br style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\" /><span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">注：出行人不能为自己签名，同行人不可以互相签名。</span>', 0, 1, 'V10049', '1610000002', '2012-10-15 14:50:45.787000', NULL, NULL, 1, 1, 0, 4);
INSERT INTO `visa_data` VALUES (1876, 'V121015001480', 'V121015001465', '存款证明', '<span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">至少1万元存款证明原件（需至少冻结到归国后三个月），开具存款证明的银行所在地必须与申请人的现居住地保持一致。</span>', 1, 1, 'V10049', '1610000002', '2012-10-15 14:51:11.427000', NULL, NULL, 1, 1, 1, 5);
INSERT INTO `visa_data` VALUES (1878, 'V121015001484', 'V121015001465', '表格', '<span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">1.签证申请表在线填写，我司填写完成后配送给您签名，本人需在签证申请表首页右上方的signature处与末页的Applicant signature处用黑色水笔中文签名，与护照末页上的签名一致。</span><br style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\" /><span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">2.填写完整、真实的个人信息表一份。</span>', 0, 1, 'V10049', '1610000002', '2012-10-15 14:51:53.997000', NULL, NULL, 1, 1, 0, 7);
INSERT INTO `visa_data` VALUES (1917, 'V121015001538', 'V121009000538', '中国大陆因私护照原件', '<p>（1）行程结束后还有半年以上有效期 <br />（2）如换发过护照同时请提供旧护照原件 <br />（3）护照末页请本人用中文签名（不可用铅笔） <br />（4）留有至少连续2张的正反面空白签证页（共4页，最后一页签证页除外） </p>', 1, 0, 'V10038', '1610000002', '2012-10-15 15:12:13.070000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (1918, 'V121015001540', 'V121009000538', '照片（2张）', '2寸（3.5cmx4.5cm）3个月内拍摄白底光面彩照2张，必须表情自然、双唇紧闭。（照片背面请不要注明姓名,正面必须无污渍）', 1, 0, 'V10038', '1610000002', '2012-10-15 15:13:23.743000', NULL, NULL, 1, 2, 0, 2);
INSERT INTO `visa_data` VALUES (1919, 'V121015001542', 'V121009000538', '个人信息表', '填写完整并签字。确保联系电话是准确有效的，并保持畅通便于领馆联系。', 1, 1, 'V10038', '1610000002', '2012-10-15 15:27:37.773000', NULL, NULL, 1, 1, 0, 3);
INSERT INTO `visa_data` VALUES (1920, 'V121015001545', 'V121009000538', '签证申请表', '本人只需在签名栏处用黑色水笔中文签名，与护照末页上的签名一致，无需填写表格。预订后会由我处提供。', 1, 1, 'V10038', '1610000002', '2012-10-15 15:29:17.860000', NULL, NULL, 1, 1, 0, 4);
INSERT INTO `visa_data` VALUES (1921, 'V121015001554', 'V121015001546', '中国大陆因私护照原件', '<span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">（1）护照在归国后还有半年以上有效期，护照末页必须有持证人中文签名（不可用铅笔）。请提供护照首页和签名页的复印件。护照至少有2页连续的空白签证页。</span><br style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\" /><span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">（2）若换发过护照同时请提供旧护照原件，若遗失，请提供遗失说明。</span><a style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; LETTER-SPACING: normal; COLOR: rgb(0,83,170); WORD-SPACING: 0px; TEXT-DECORATION: none; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\" href=\"http://pages.ctrip.com/tour/word/080905b.doc\" target=\"_blank\">遗失说明</a><span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\"><span>&nbsp;</span></span><br style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\" /><span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">（3）不接收半年内有欧洲国家拒签章的护照</span><br style=\"WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\" /><span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">（4）不接收在斯里兰卡非法滞留过的护照</span>', 1, 1, 'V10050', '1610000002', '2012-10-15 15:39:16.993000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (1922, 'V121015001556', 'V121015001546', '照片', '<span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">半年内拍摄的2寸(3.5cmx4.5cm)白底彩照2张（照片背面请不要注明姓名,正面必须无污渍）</span>', 1, 1, 'V10050', '1610000002', '2012-10-15 15:39:33.667000', NULL, NULL, 1, 2, 0, 2);
INSERT INTO `visa_data` VALUES (1923, 'V121015001558', 'V121015001546', '个人信息表', '<span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">填写完整并签字。确保联系电话是准确有效的，并保持畅通便于领馆联系。</span>', 1, 1, 'V10050', '1610000002', '2012-10-15 15:39:49.710000', NULL, NULL, 1, 1, 0, 3);
