INSERT INTO `visa_data` VALUES (2079, 'V130823000233', 'V130823000227', '★中国大陆因私护照首页信息彩色扫描件', '<p><span style=\"font-family:Tahoma, Simsun, sans-serif;color:#4d4d4d;PADDING-BOTTOM: 0px; LINE-HEIGHT: 18px; BACKGROUND-COLOR: rgb(254,254,254); MARGIN: 0px; PADDING-LEFT: 0px; PADDING-RIGHT: 0px; PADDING-TOP: 0px\"></span>1、行程结束后至少还有6个月有效期；<br />2、老版护照在第7-47页范围内（电子护照在第8-45页范围内），至少留有2页空白签证页。<br /></p>', 0, 1, 'V10062', '1610000002', '2013-08-23 19:35:49.087000', NULL, NULL, 0, 1, 0, 1);
INSERT INTO `visa_data` VALUES (2089, 'V130823000273', 'V130823000267', '★中国大陆因私护照', '<p>1、行程结束后至少还有6个月有效期。<br />2、老版护照在第7-47页范围内（电子护照在第8-45页范围内），至少留有1页空白签证页。<br />3、护照末页请本人用中文签名，学龄前儿童可由父母用中文代签名（不可用铅笔）（电子护照除外）。<br /></p>', 0, 1, 'V10064', '1610000002', '2013-08-23 20:39:19.093000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (2101, 'V130823000321', 'V130823000313', '★中国大陆因私护照', '1、行程结束后至少还有6个月有效期。<br />2、老版护照在第7-47页范围内（电子护照在第8-45页范围内），至少留有1页空白签证页。<br />3、护照末页请本人用中文签名，学龄前儿童可由父母用中文代签名（不可用铅笔）（电子护照除外）。<br />', 0, 1, 'V10066', '1610000002', '2013-08-23 21:10:59.540000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (2111, 'V130827000365', 'V130823000332', '★中国大陆因私护照', '1、行程结束后还有半年以上有效期。<br />2、末页必须有持证人中文亲笔签名（不能用铅笔）。<br />3、至少留有2页空白签证页（不是备注页）。<br />4、不接收半年内被韩国拒签过的护照。<br />5、不接收在韩国非法滞留过的护照。<br />', 1, 1, 'V10067', '1610000002', '2013-08-27 15:41:37.930000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (2112, 'V130827000367', 'V130823000332', '★照片（2张）', '<p>2寸(3.5cmx4.5cm)白底彩照2张（在照片背后用铅笔写名字）<br /></p>', 1, 1, 'V10067', '1610000002', '2013-08-27 15:43:16.743000', NULL, NULL, 1, 2, 1, 2);
INSERT INTO `visa_data` VALUES (2113, 'V130827000370', 'V130823000332', '★身份证复原件', '<p>1、16周岁以上，请提供身份证原件</p><p>备注：一定要身份证原件。</p><p></p>', 1, 1, 'V10067', '1610000002', '2013-08-27 15:46:22.927000', NULL, NULL, 1, 1, 1, 3);
INSERT INTO `visa_data` VALUES (2114, 'V130827000373', 'V130823000332', '★个人简历', '<p>1、用中文完整填写后，本人在签名栏处，用黑色水笔中文签名（与护照末页签名保持一致）。</p><p>备注：最终学历如果是大学或大学以上的一定要写学校名称和专业</p>', 1, 1, 'V10067', '1610000002', '2013-08-27 15:49:01.497000', NULL, NULL, 1, 1, 1, 4);
INSERT INTO `visa_data` VALUES (2115, 'V130827000377', 'V130823000332', '★签证申请表', '<p>1、用中文完整填写后，无需粘贴照片，本人在签名栏处，用黑色水笔中文签名（与护照签名一致）。<br /><br /></p>', 0, 1, 'V10067', '1610000002', '2013-08-27 16:10:08.460000', NULL, NULL, 1, 1, 1, 5);
INSERT INTO `visa_data` VALUES (2119, 'V130827000418', 'V130823000332', '资金证明', '<p>1.近六个月信用卡对帐单必须显示消费字样每个月三千元。<br />2.近六个月银行拉出的工资卡对账单原件，必须显示工资字样。<br />3.个人所得税缴税证明原件不能为0。</p><p>4.公司缴纳的近六个月社保原件并且盖有社保红章。<br />备注：上述4点选其二即可<br /></p>', 0, 1, 'V10067', '1610000002', '2013-08-27 16:56:09.443000', NULL, NULL, 1, 1, 1, 6);
INSERT INTO `visa_data` VALUES (2149, 'V130828000493', 'V130821000077', '★中国大陆因私护照', '（可接收电子护照）<br />1、行程结束后至少还有6个月有效期。<br />2、老版护照在第7-47页范围内，至少留有1页空白签证页；电子护照在第8-45页范围内，至少留有1页空白签证页。<br />3、护照末页请本人用中文签名，学龄前儿童可由父母用中文代签名（不可用铅笔）（电子护照除外）。<br />4、旧护照无需提供（如新旧护照订在一起，请自行拆卸）。<br />', 1, 1, 'V10057', '1610000002', '2013-08-28 11:01:42.430000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (2150, 'V130828000495', 'V130821000077', '★照片（1张）', '2寸(3.5cmx4.5cm)白底彩照1张（在照片背后请用铅笔写本人名字）。<br />', 0, 1, 'V10057', '1610000002', '2013-08-28 11:02:16.713000', NULL, NULL, 1, 1, 1, 2);
INSERT INTO `visa_data` VALUES (2167, 'V130828000522', 'V130823000312', '★中国大陆因私护照', '1、行程结束后至少还有6个月有效期。<br />2、老版护照在第7-47页范围内（电子护照在第8-45页范围内），至少留有1页空白签证页。<br />3、护照末页请本人用中文签名，学龄前儿童可由父母用中文代签名（不可用铅笔）（电子护照除外）。<br />', 1, 1, 'V10066', '1610000002', '2013-08-28 13:21:07.557000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (2168, 'V130828000524', 'V130823000312', '★照片（2张）', '2寸(3.5cmx4.5cm)白底彩照2张（在照片背后用铅笔写名字）。', 0, 1, 'V10066', '1610000002', '2013-08-28 13:23:55.883000', NULL, NULL, 1, 1, 1, 2);
INSERT INTO `visa_data` VALUES (2169, 'V130828000527', 'V130823000312', '★英文在职证明', '1、使用抬头信纸打印（抬头包括公司名称、地址、电话和传真），若无抬头信纸，可自行编辑打印。<br />2、英文在职证明请按模版提供，可以由法人代表或总经理或部门主管或人事主管本人签名，并加盖公司（公章）或（人力资源章）或（财务章）或（部门章）。<br />3、如申请人本人是法人代表，请人事负责人或其他公司高管签名；其他出行人不能为自己签名，同行人也不可以互相签名。<br />4、除签名外其他内容手写无效，请勿标注类似“仅供签证使用”字样。<br />', 0, 1, 'V10066', '1610000002', '2013-08-28 13:27:32.160000', NULL, NULL, 1, 1, 1, 3);
INSERT INTO `visa_data` VALUES (2171, 'V130828000531', 'V130823000312', '★签证申请表', '1、申请表请下载并用A4纸正反面打印1份。（请用英文填写，不接受中文）<br />2、本人在签名栏处用黑色水笔中文签名（与护照签名一致），18周岁以下者由同行的父/母签孩子本人名字，并在签名后注（父代/母代）。<br />', 0, 1, 'V10066', '1610000002', '2013-08-28 13:32:30.360000', NULL, NULL, 1, 1, 1, 5);
INSERT INTO `visa_data` VALUES (2172, 'V130828000543', 'V130823000313', '★照片（2张）', '2寸(3.5cmx4.5cm)白底彩照2张（在照片背后用铅笔写名字）。<br />', 1, 1, 'V10066', '1610000002', '2013-08-28 14:00:14.940000', NULL, NULL, 1, 1, 1, 2);
INSERT INTO `visa_data` VALUES (2174, 'V130828000549', 'V130823000313', '★签证申请表', '1、申请表请下载并用A4纸正反面打印1份。<br />2、本人在签名栏处用黑色水笔中文签名（与护照签名一致），18周岁以下者由同行的父/母签孩子本人名字，并在签名后注（父代/母代）。<br />', 0, 1, 'V10066', '1610000002', '2013-08-28 14:03:16.250000', NULL, NULL, 1, 1, 1, 4);
INSERT INTO `visa_data` VALUES (2183, 'V130828000581', 'V130823000315', '★学龄前儿童', '1、如与父母同同行，提供出生证明复印件；<br />2、如出生证明中的信息不全或者无法提供，请提供可以提现父母关系的户口本复印件或亲属关系公证书原件或派出所开具的亲属关系证明原件。<br />', 0, 1, 'V10066', '1610000002', '2013-08-28 14:48:56.910000', NULL, NULL, 1, 1, 1, 3);
