INSERT INTO `visa_data` VALUES (2252, 'V130828000725', 'V130822000157', '★中国大陆因私护照', '1、行程结束后至少还有6个月有效期.（可接收电子护照）<br />2、老版护照在第7-47页范围内（电子护照在第8-45页范围内），至少留有2页空白签证页.<br />3、护照末页请本人用中文签名，学龄前儿童可由父母用中文代签名（不可用铅笔）（电子护照除外）。<br />', 1, 1, 'V10060', '1610000002', '2013-08-28 16:06:20.517000', NULL, NULL, 1, 1, 1, 1);
