INSERT INTO `visa_data` VALUES (2262, 'V130828000745', 'V130822000125', '★中国大陆因私护照', '1、行程结束后至少还有6个月有效期。<br />2、老版护照在第7-47页范围内（电子护照在第8-45页范围内），至少留有2页空白签证页。<br />', 0, 1, 'V10059', '1610000002', '2013-08-28 16:14:32.397000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (2263, 'V130828000747', 'V130822000125', '★照片（2张）', '2寸(照片大小：35mmx45mm；头部大小:21-24mm；头部长度：28-33mm)白底彩照2张，须一致（在照片背后请用铅笔写本人名字）。<br />', 0, 1, 'V10059', '1610000002', '2013-08-28 16:15:26.533000', NULL, NULL, 1, 1, 1, 2);
INSERT INTO `visa_data` VALUES (2268, 'V130828000757', 'V130822000127', '★同行关系证明（18周岁以下者提供）', '<p>1、如只与父母或父母一方出行，需提供可体现与父母关系的（出生证明复印件）或（户口簿整本复印件）或（派出所开具的关系证明原件盖红章）；</p><p>2、如不与父母同行，需提供关系证明。（公证关系证明复印件）</p><p>备注：不得委托无血缘关系者携带未满18周岁学生出境，满18周岁以上学生无须提供关系证明。</p>', 0, 1, 'V10059', '1610000002', '2013-08-28 16:17:04.707000', NULL, NULL, 1, 1, 1, 3);
INSERT INTO `visa_data` VALUES (2280, 'V130828000790', 'V130828000789', '★中国大陆因私护照', '1、行程结束后至少还有6个月有效期。<br />2、老版护照在第7-47页范围内（电子护照在第8-45页范围内），至少留有1页空白签证页；<br />3、护照末页请本人用中文签名，学龄前儿童可由父母用中文代签名（不可用铅笔）（电子护照除外）。', 1, 0, 'V10061', '1610000002', '2013-08-28 17:04:09.077000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (2281, 'V130828000791', 'V130828000789', '★照片（2张）', '近6个月内（以实际出发时间开始计算）拍摄的2寸(3.5cmx4.5cm)白底彩照2张（在照片背后请用铅笔写本人名字）。<br />', 0, 1, 'V10061', '1610000002', '2013-08-28 17:04:09.107000', NULL, NULL, 1, 1, 1, 2);
INSERT INTO `visa_data` VALUES (2284, 'V130828000797', 'V130828000789', '★身份证复印件', '<span style=\"font-family:Tahoma, Simsun, sans-serif;color:#4d4d4d;LINE-HEIGHT: 18px\"></span>1、16周岁以上，请提供身份证原件以及正反面复印件，正反面复印在一张纸上。<br />2、行程结束后仍在有效期内的临时身份证原件以及复印件也可接收。', 1, 0, 'V10061', '1610000002', '2013-08-28 17:04:32.713000', NULL, NULL, 1, 1, 1, 3);
INSERT INTO `visa_data` VALUES (2287, 'V130828000803', 'V130828000789', '★退休证原件', '<p><span style=\"color:#ff0000;\"><span style=\"font-family: 宋体;\">退休证复印件及银行存款证明3-5万</span><span style=\"font-family: Arial;\">(</span><span style=\"font-family: 宋体;\">原件及复印件，原件不退还</span><span style=\"font-family: Arial;\">)</span><span style=\"font-family: 宋体;\">。银行存款证明的金额没有具体要求但银行签发日期必须是签证申请递交日期的</span><span style=\"font-family: Arial;\">1</span><span style=\"font-family: 宋体;\">个月内。</span><span style=\"font-family: 宋体;\">若退休证提供不出可只提供存款证明</span><span style=\"font-family: Arial;\">(</span><span style=\"font-family: 宋体;\">原件及复印件</span><span style=\"font-family: Arial;\">)</span><span style=\"font-family: 宋体;\">。</span><span style=\"font-family: 宋体;\">并注明收入来源，若有同行人，须提供同行人姓名、同行人护照号码、同行人与申请人的关系。</span></span></p><p></p>', 0, 1, 'V10061', '1610000002', '2013-08-28 17:08:16.957000', NULL, NULL, 1, 1, 1, 6);
INSERT INTO `visa_data` VALUES (2291, 'V130828000825', 'V130828000824', '★中国大陆因私护照', '1、行程结束后至少还有6个月有效期。<br />2、老版护照在第7-47页范围内（电子护照在第8-45页范围内），至少留有1页空白签证页；<br />3、护照末页请本人用中文签名，学龄前儿童可由父母用中文代签名（不可用铅笔）（电子护照除外）。', 1, 0, 'V10061', '1610000002', '2013-08-28 17:12:21.880000', NULL, NULL, 1, 1, 1, 1);
