INSERT INTO `visa_data` VALUES (2302, 'V130828000843', 'V130828000824', '★户口簿复印件', '<span style=\"font-family:Tahoma, Simsun, sans-serif;color:#4d4d4d;LINE-HEIGHT: 18px\"></span>1、户口本原件以及整本复印件（请连续复印至第一页空白页）。<br />2、如是集体户口请提供户籍证明原件（不退还）。', 0, 0, 'V10061', '1610000002', '2013-08-28 17:12:59.740000', NULL, NULL, 1, 1, 1, 4);
INSERT INTO `visa_data` VALUES (2303, 'V130828000845', 'V130828000824', '★中文在校证明', '1、使用抬头信纸打印（抬头包括学校名称、地址、电话和传真）。<br /><br />2、中文在校证明请按模版提供，可以由班主任或其他老师本人签名或盖本人私章，并加盖学校（公章）或（教务处章）<br />3、除签名外其他内容手写无效，请勿标注类似“仅供签证使用”字样。<br />4、如遇寒暑假，可用学生证或学籍卡复印件代替在校证明。<br />', 0, 1, 'V10061', '1610000002', '2013-08-28 17:14:06.670000', NULL, NULL, 1, 1, 1, 5);
