INSERT INTO `visa_data` VALUES (2346, 'V130829000938', 'V130822000106', '★同行关系证明（18周岁以下者提供）', '<p>1、如只与父母或父母一方出行，需提供可体现与父母关系的（出生证明复印件）或（户口簿整本复印件）或（派出所开具的关系证明原件盖红章）；</p><p>2、如不与父母同行，需提供关系证明。（公证关系证明复印件）</p><p>备注：不得委托无血缘关系者携带未满18周岁学生出境，满18周岁以上学生无须提供关系证明。</p>', 0, 1, 'V10058', '1610000002', '2013-08-29 09:24:44.667000', NULL, NULL, 1, 1, 1, 3);
