INSERT INTO `visa_data` VALUES (2396, 'V130829001052', 'V130828000789', '★户口簿复印件', '<span style=\"font-family:Tahoma, Simsun, sans-serif;color:#4d4d4d;LINE-HEIGHT: 18px\"></span>1、户口本原件以及整本复印件（请连续复印至第一页空白页）。<br />2、如是集体户口请提供户籍证明原件（不退还）。', 0, 0, 'V10061', '1610000002', '2013-08-29 13:13:35.393000', NULL, NULL, 1, 1, 1, 5);
INSERT INTO `visa_data` VALUES (2398, 'V130829001057', 'V130822000176', '★中国大陆因私护照', '1、行程结束后至少还有6个月有效期。<br />2、老版护照在第7-47页范围内（电子护照在第8-45页范围内），至少留有1页空白签证页；<br />3、护照末页请本人用中文签名，学龄前儿童可由父母用中文代签名（不可用铅笔）（电子护照除外）。', 1, 1, 'V10061', '1610000002', '2013-08-29 13:26:39.260000', NULL, NULL, 1, 1, 1, 8);
INSERT INTO `visa_data` VALUES (2399, 'V130829001059', 'V130822000176', '★照片（2张）', '近6个月内（以实际出发时间开始计算）拍摄的2寸(3.5cmx4.5cm)白底彩照2张（在照片背后请用铅笔写本人名字）。<br />', 1, 1, 'V10061', '1610000002', '2013-08-29 13:27:18.743000', NULL, NULL, 1, 1, 1, 8);
INSERT INTO `visa_data` VALUES (2400, 'V130829001061', 'V130822000176', '★身份证复印件', '1、16周岁以上，请提供身份证原件以及正反面复印件，正反面复印在一张纸上。<br />2、行程结束后仍在有效期内的临时身份证原件以及复印件也可接收。', 1, 1, 'V10061', '1610000002', '2013-08-29 13:28:01.203000', NULL, NULL, 1, 1, 1, 8);
INSERT INTO `visa_data` VALUES (2401, 'V130829001063', 'V130822000176', '★户口簿复印件', '<span style=\"font-family:Tahoma, Simsun, sans-serif;color:#4d4d4d;LINE-HEIGHT: 18px\"></span>1、户口本整本复印件（请连续复印至第一页空白页）。<br />2、如是集体户口请提供户籍证明原件（不退还）。', 0, 1, 'V10061', '1610000002', '2013-08-29 13:28:29.170000', NULL, NULL, 1, 1, 1, 8);
INSERT INTO `visa_data` VALUES (2402, 'V130829001065', 'V130822000176', '★中文在职证明原件', '<span style=\"font-family: Tahoma, Simsun, sans-serif; line-height: 18px;\"></span><span style=\"color:#ff0000;\"><span style=\"font-size: 10.5pt; font-family: 宋体;\">必须提供由就职公司出具的在职证明信原件一份。证明信中需有</span><span style=\"font-size: 10.5pt; font-family: 宋体;\">公司名称（英文）</span><span style=\"font-size: 10.5pt; font-family: 宋体;\">同意其休假，并详细注明申请者在该公司任职时间、</span><span style=\"font-size: 10.5pt; font-family: 宋体;\">职务及工资</span><span style=\"font-size: 10.5pt; font-family: 宋体;\">。在职证明信必须列有</span><span style=\"font-size: 10.5pt; font-family: 宋体;\">公司及有关联系人的地址、电话和传真号码。信函必须加盖公章</span><span style=\"font-size: 10.5pt; font-family: 宋体;\">。</span></span>', 0, 1, 'V10061', '1610000002', '2013-08-29 13:29:07.727000', NULL, NULL, 1, 1, 1, 8);
INSERT INTO `visa_data` VALUES (2405, 'V130829001093', 'V130823000267', '★照片（2张）', '2寸(3.5cmx4.5cm)白底彩照2张（在照片背后用铅笔写名字）。', 1, 1, 'V10064', '1610000002', '2013-08-29 14:07:52.520000', NULL, NULL, 1, 1, 1, 2);
INSERT INTO `visa_data` VALUES (2406, 'V130829001095', 'V130823000267', '★英文在职证明', '<p>1、使用抬头信纸打印（抬头包括公司名称、地址、电话和传真），若无抬头信纸，可自行编辑打印。<br />2、英文在职证明请按模版提供，可以由法人代表或总经理或部门主管或人事主管本人签名，并加盖公司（公章）或（人力资源章）或（财务章）或（部门章）。<br />3、如申请人本人是法人代表，请人事负责人或其他公司高管签名；其他出行人不能为自己签名，同行人也不可以互相签名。<br />4、除签名外其他内容手写无效，请勿标注类似“仅供签证使用”字样。<br /></p>', 0, 1, 'V10064', '1610000002', '2013-08-29 14:08:27.610000', NULL, NULL, 1, 1, 1, 3);
INSERT INTO `visa_data` VALUES (2407, 'V130829001097', 'V130823000267', '★签证申请表', '1、申请表请下载并用A4纸正反面打印在一张纸，提供1份。（请用英文填写，不接受中文）<br />2、本人在签名栏处用黑色水笔中文签名（与护照签名一致），18周岁以下者由同行的父/母签孩子本人名字，并在签名后注（父代/母代）。<br />', 0, 1, 'V10064', '1610000002', '2013-08-29 14:08:57.203000', NULL, NULL, 1, 1, 1, 4);
