INSERT INTO `visa_data` VALUES (2500, 'V131105000140', 'V131105000131', '在校证明', '<p>在校学生需提供：学校准假信，包含该学生名字、生日、班级、准假等等信息，中英文版本。</p><p>寒暑假期间出行，提供学生证复印件即可。</p>', 1, 1, 'V20048', '1610000002', '2013-11-05 17:03:26.270000', NULL, NULL, 0, 1, 0, 6);
INSERT INTO `visa_data` VALUES (2501, 'V131105000141', 'V131105000131', '父母资产', '<p style=\"padding: 0px; margin: 0px; font-family: Arial, simsun; line-height: 23px;\"></p><p style=\"padding: 0px; margin: 0px; font-family: Arial, simsun; line-height: 23px;\">A 父母的存折或借记卡的近半年流水单（上面需有清晰的户主姓名和卡号，以及银行的盖章），余额要可以覆盖此次旅行的。&nbsp;</p><p style=\"padding: 0px; margin: 0px; font-family: Arial, simsun; line-height: 23px;\">B 或银行开具的本人或父母名下的已有3个月存入期的至少5万元的存款证明复印件（如交原件则原件不退）。</p><p style=\"padding: 0px; margin: 0px; font-family: Arial, simsun; line-height: 23px;\">C 父母或本人的其他资产复印件，车证房证等等。</p><p><span style=\"font-family: Arial, simsun; line-height: 23px;\"></span></p><p></p>', 1, 1, 'V20048', '1610000002', '2013-11-05 17:03:26.287000', NULL, NULL, 0, 1, 0, 7);
INSERT INTO `visa_data` VALUES (2502, 'V131105000147', 'V131105000131', '未成年所需材料', '<p>18周岁以下儿童必须提供该儿童的，出生公证书复印件或出生证复印件。</p><p>此外，如有父母一方不同行，则不同行方的父母必须提供书面授权信（同意信），身份证复印件以及联系地址电话。</p><p>如父母双方都不同行，双方必须提供书面授权信（同意委托信），身份证复印件以及联系地址电话。</p>', 0, 1, 'V20048', '1610000002', '2013-11-05 17:06:31.667000', NULL, NULL, 0, 1, 0, 8);
INSERT INTO `visa_data` VALUES (2503, 'V131105000164', 'V131105000089', '特别提醒', '①如有拒签记录，请如实提供亲笔签名的拒签说明书。有签证签出没去的，也要写一下情况说明。<br />②如在新西兰有亲戚，请提供护照复印件和签证页复印件。探亲的需提供邀请函以及其在当地的电话，地址。<br />③签证由领馆签发，即使客人提供全部材料，也不能保证获得签证。领馆保留索要补充资料和面试的权利。', 0, 0, 'V20048', '1610000002', '2013-11-05 17:18:58.293000', NULL, NULL, 0, 1, 0, 10);
INSERT INTO `visa_data` VALUES (2504, 'V131105000168', 'V131105000106', '特别提醒', '①如有拒签记录，请如实提供亲笔签名的拒签说明书。有签证签出没去的，也要写一下情况说明。<br />②如在新西兰有亲戚，请提供护照复印件和签证页复印件。探亲的需提供邀请函以及其在当地的电话，地址。<br />③签证由领馆签发，即使客人提供全部材料，也不能保证获得签证。领馆保留索要补充资料和面试的权利。', 1, 0, 'V20048', '1610000002', '2013-11-05 17:19:33.787000', NULL, NULL, 0, 1, 0, 7);
INSERT INTO `visa_data` VALUES (2505, 'V131105000171', 'V131105000131', '特别提醒', '①如有拒签记录，请如实提供亲笔签名的拒签说明书。有签证签出没去的，也要写一下情况说明。<br />②如在新西兰有亲戚，请提供护照复印件和签证页复印件。探亲的需提供邀请函以及其在当地的电话，地址。<br />③签证由领馆签发，即使客人提供全部材料，也不能保证获得签证。领馆保留索要补充资料和面试的权利。', 1, 0, 'V20048', '1610000002', '2013-11-05 17:19:54.373000', NULL, NULL, 0, 1, 0, 9);
INSERT INTO `visa_data` VALUES (2512, 'V131106000214', 'V121011001050', '保险', '<p></p>旅游医疗保险证明原件和复印件（须是电脑出单，手写保单无效）<br />a、保险金额不低于30万元人民币。<br />b、旅行医疗保险须超于整个旅行日期的2-3天，以备延期之用。<p></p>', 1, 1, 'V20044', '1610000002', '2013-11-06 09:34:25.610000', NULL, NULL, 1, 1, 1, 11);
INSERT INTO `visa_data` VALUES (2513, 'V131106000216', 'V121011001050', '备注', '<p><span style=\"background-position: initial initial; background-repeat: initial initial;\"></span></p><div>&nbsp;A.办理此签证需要自行递交材料<br />B.领馆保留索要补充资料和要求申请者面试的权利，需本人按领馆要求前往领馆面试或递交补充材料。<br />C.签证由领馆签发，即使客人提供全部材料，也不能保证获得签证。<br />D.所有签证材料不得加注仅供签证使用字樣。<br /></div><p><span style=\"background-position: initial initial; background-repeat: initial initial;\"></span></p>', 0, 1, 'V20044', '1610000002', '2013-11-06 09:34:57.637000', NULL, NULL, 1, 1, 1, 12);
INSERT INTO `visa_data` VALUES (2514, 'V131106000225', 'V121011001070', '保险', '<p></p>保险：旅游医疗保险证明原件和复印件（须是电脑出单，手写保单无效）<br />a、保险金额不低于30万元人民币。<br />b、旅行医疗保险须超于整个旅行日期的2-3天，以备延期之用。<p></p>', 0, 1, 'V20044', '1610000002', '2013-11-06 09:39:34.393000', NULL, NULL, 1, 1, 1, 10);
