INSERT INTO `visa_data` VALUES (2527, 'V131106000308', 'V131106000307', '护照', '1.归国后还有6个月以上有效期，至少留有2页空白签证页（不是备注页）,末页必须有持证人中文亲笔签名<br />2.护照需整本彩色复印，如有旧护照请一并提供。<br />3.不接收在澳大利亚非法滞留过的护照', 0, 0, 'V20047', '1610000002', '2013-11-06 10:25:49.923000', NULL, NULL, 0, 1, 0, 1);
