INSERT INTO `visa_data` VALUES (2551, 'V131106000388', 'V121015001348', '身份证', '本人身份证正反面彩色复印件。', 0, 0, 'V20047', '1610000002', '2013-11-06 10:47:59.927000', NULL, NULL, 0, 1, 0, 3);
INSERT INTO `visa_data` VALUES (2552, 'V131106000389', 'V121015001348', '户口簿', '户口整本彩色复印件（须复印到第一页空白页）<br />如是集体户口，需提供户主页和本人页彩色复印件', 0, 0, 'V20047', '1610000002', '2013-11-06 10:47:59.960000', NULL, NULL, 0, 1, 0, 4);
INSERT INTO `visa_data` VALUES (2553, 'V131106000390', 'V121015001348', '个人资料表', '填写真实完整并本人亲笔签字，并请将本人的父母、兄弟姐妹、子女的详细资料认真如实填写。特别注意是否有亲戚在国外,是否有过拒签。', 1, 0, 'V20047', '1610000002', '2013-11-06 10:47:59.973000', NULL, NULL, 0, 1, 0, 5);
INSERT INTO `visa_data` VALUES (2554, 'V131106000392', 'V121015001348', '资产证明（必须提供） ', '<p>1.本人的存折或借记卡的近半年流水单（上面需有清晰的户主姓名和卡号，以及银行的盖章），余额要可以覆盖此次旅行的。&nbsp;</p>2.银行开具的本人名下的已有3个月存入期的至少5万元的定期存款证明复印件（如交原件则原件不退）。', 0, 0, 'V20047', '1610000002', '2013-11-06 10:48:00.020000', NULL, NULL, 0, 1, 0, 8);
INSERT INTO `visa_data` VALUES (2555, 'V131106000393', 'V121015001348', '资产证明（选择提供） ', '为了提高您的出签率，以下材料请尽可能多提供： （可以是配偶名下的资产证明，同时提供结婚证复印件）<br />A.房产证复印件<br />B.车产证复印件<br />C.行驶证复印件<br />D.股票交割单原件需加盖柜台章或其他资金证明', 1, 0, 'V20047', '1610000002', '2013-11-06 10:48:00.053000', NULL, NULL, 0, 1, 0, 9);
INSERT INTO `visa_data` VALUES (2556, 'V131106000394', 'V121015001348', '特别提醒', '<p></p>1.如有拒签记录，请如实提供亲笔签名的拒签说明书。<br />2.如在澳大利亚亲戚的，请提供护照复印件和签证页复印件，如要探亲的 还要提供邀请函及其在当地的电话，地址。<br /><br /><p></p>', 0, 0, 'V20047', '1610000002', '2013-11-06 10:48:00.070000', NULL, NULL, 0, 1, 0, 10);
INSERT INTO `visa_data` VALUES (2557, 'V131106000396', 'V121015001348', '退休证明', '退休证复印件', 1, 1, 'V20047', '1610000002', '2013-11-06 10:48:23.047000', NULL, NULL, 0, 1, 1, 7);
INSERT INTO `visa_data` VALUES (2558, 'V131106000398', 'V121015001348', '结婚证/离婚证', '凡有婚姻状况，均需要提供结婚证或者离婚证复印件。', 1, 0, 'V20047', '1610000002', '2013-11-06 10:49:02.397000', NULL, NULL, 0, 1, 0, 6);
INSERT INTO `visa_data` VALUES (2559, 'V131106000410', 'V121011000954', '旅行证明', '<p><span style=\"font-size:9pt;font-family:Arial;\">a.</span><span style=\"font-size:9pt;font-family:宋体;\">英文的覆盖全程的简单行程（城市与城市之间）</span></p><p><span style=\"font-size:9pt;font-family:Arial;\">b.</span><span style=\"font-size:9pt;font-family:宋体;\">有申请人名字的全程机票订单和全程酒店订单（必须与您的英文行程</span><span style=\"font-size:9pt;font-family:Arial;\">&nbsp;&nbsp; </span><span style=\"font-size:9pt;font-family:宋体;\">单保持一致）</span></p>', 1, 1, 'V20043', '1610000002', '2013-11-06 13:45:51.823000', NULL, NULL, 1, 1, 1, 11);
INSERT INTO `visa_data` VALUES (2560, 'V131106000412', 'V121011000954', '保险', '<p><span style=\"font-size:9pt;font-family:宋体;\">旅游医疗保险证明原件和复印件（须是电脑出单，手写保单无效）</span></p><p><span style=\"font-size:9pt;font-family:Arial;\">a</span><span style=\"font-size:9pt;font-family:宋体;\">、保险金额不低于</span><span style=\"font-size:9pt;font-family:Arial;\">30</span><span style=\"font-size:9pt;font-family:宋体;\">万元人民币。</span></p><p><span style=\"font-size:9pt;font-family:Arial;\">b</span><span style=\"font-size:9pt;font-family:宋体;\">、旅行医疗保险须超于整个旅行日期的</span><span style=\"font-size:9pt;font-family:Arial;\">2-3</span><span style=\"font-size:9pt;font-family:宋体;\">天，以备延期之用。</span></p>', 1, 1, 'V20043', '1610000002', '2013-11-06 13:46:14.110000', NULL, NULL, 1, 1, 1, 12);
INSERT INTO `visa_data` VALUES (2561, 'V131106000414', 'V121011000954', '备注', '<p><span style=\"font-size:9pt;font-family:Arial;\"></span></p><div>&nbsp;A.领馆保留索要补充资料和要求申请者面试的权利，需本人按领馆要求前往领馆面试或递交补充材料。<div>B.签证由领馆签发，即使客人提供全部材料，也不能保证获得签证。<br />C.所有签证材料不得加注仅供签证使用字樣。<br /></div><br /></div><p><span style=\"font-size:9pt;font-family:宋体;\"></span></p>', 0, 1, 'V20043', '1610000002', '2013-11-06 13:46:38.470000', NULL, NULL, 1, 1, 1, 13);
INSERT INTO `visa_data` VALUES (2562, 'V131106000428', 'V121011000676', '旅行证明', '<p>a.英文的覆盖全程的简单行程（城市与城市之间）<br />b.有申请人名字的全程机票订单和全程酒店订单（必须与您的英文行程&nbsp;&nbsp;&nbsp;单保持一致）</p>', 1, 1, 'V20040', '1610000002', '2013-11-06 13:51:55.400000', NULL, NULL, 1, 1, 1, 11);
INSERT INTO `visa_data` VALUES (2563, 'V131106000430', 'V121011000676', '保险', '<p></p>保险：旅游医疗保险证明原件和复印件（须是电脑出单，手写保单无效）<br />a、保险金额不低于30万元人民币。<br />b、旅行医疗保险须超于整个旅行日期的2-3天，以备延期之用。<p><span style=\"background-position: initial initial; background-repeat: initial initial;\"></span></p>', 1, 1, 'V20040', '1610000002', '2013-11-06 13:52:12.620000', NULL, NULL, 1, 1, 1, 12);
