INSERT INTO `visa_data` VALUES (2573, 'V131106000521', 'V121011000743', '保险', '<p><span style=\"font-family:宋体;color:black;font-size:9.0pt;background:#FEFEFE;\"></span></p>旅游医疗保险证明原件和复印件（须是电脑出单，手写保单无效）<br />a、保险金额不低于30万元人民币。<br />b、旅行医疗保险须超于整个旅行日期的2-3天，以备延期之用。<p><span style=\"font-family:宋体;color:black;font-size:9.0pt;background:#FEFEFE;\"></span></p>', 1, 1, 'V20040', '1610000002', '2013-11-06 15:25:18.467000', NULL, NULL, 1, 1, 1, 12);
INSERT INTO `visa_data` VALUES (2574, 'V131107000532', 'V131107000531', '护照', 'A. &nbsp;1本原件有效期至少半年以上，护照后需有个人本人签名<br />B. &nbsp;有旧护照，则必须提供原件，老护照后也必须本人签名<br />C. &nbsp;若申请人旧护照遗失，则必须提供旧护照的遗失证明（即客人自己写一份遗失说明并签字或者公安机关开具的遗失证明）<br />D. 有 2 张以上的空白可用页<br />', 1, 1, 'V10069', '1610000002', '2013-11-07 09:44:54.987000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2575, 'V131107000534', 'V131107000531', '照片', '最近半年内白底彩色照片，照片大小为（3.5*4.5）厘米：<br />A.从头发最高处至下颚占全部相片高度的70%-80%<br />B.4张并在背后附签名<br />C.务必请配合清晰的露出五官。<br />', 1, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.050000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2576, 'V131107000535', 'V131107000531', '户口薄', '<p><span style=\"font-size:12.0pt;font-family:宋体;\"></span></p><p>全家户口本整本原件及复印件：</p><p>a.户口本的服务处所/职务必须与所提供公司营业执照名称一致</p><p>b.爱人、小孩户口不在同一本户口本上，必须提供爱人和小孩所在户口本的整本户口本复印件</p><p>c.军人提供军官证复印件</p><p></p><br />', 1, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.050000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2577, 'V131107000536', 'V131107000531', '结婚证/离婚证', 'A.申请人为已婚身份，请提供1份结婚证复印件<br /><p>B.申请人为离婚身份，请提供1份离婚证复印件</p><p><br /></p>', 1, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.067000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2578, 'V131107000537', 'V131107000531', '在职证明', '<p>在职人员提供单位工作证明信一份：（信纸必须用单位正规抬头纸，上有公司地址、电话和传真）必须盖有单位公章章、註明签字领导的姓名、职务及联系电话。（同行人不能作为证明信的签字人）</p><p>&nbsp; 工作证明信中必须注明以下内容：本人在公司所担任的职务、本人的收入、休假时间许可，保证其遵守法律以及在行程后按时回国并继续就职，并标注营业执照号码。</p><br />', 1, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.080000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2579, 'V131107000539', 'V131107000531', '营业执照', 'A. 申请人为企业性质的公司：提供1份有经营范围的营业执照<br />B. 申请人为非企业性质的公司：提供组织机构代码证<br />注：营业执照和组织机构代码证均为清晰的复印件并加盖公司公章<br />', 1, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.097000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2580, 'V131107000540', 'V131107000531', '资产证明', '申请人本人名下的其他资产复印件。房产证，车证，股票等等<br />', 1, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.127000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2581, 'V131107000541', 'V131107000531', '身份证', '身份证必须在有效期内，须正反两面复印。', 1, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.143000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2582, 'V131107000542', 'V131107000531', '名片', '2张申请人本人的名片，内容真实无误。', 1, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.173000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2583, 'V131107000543', 'V131107000531', '工资单或银行对账单', '申请人本人名下对账单<span lang=\"EN-US\">:</span>盖有银行公章的近<span lang=\"EN-US\">6</span>个月完整工资的对帐单或借记卡都账单（不可以用信用卡且余额不要低于<span lang=\"EN-US\">1</span>万元）<br />', 1, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.173000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2584, 'V131107000544', 'V131107000531', '旅行证明', 'a.英文的覆盖全程的简单行程（城市与城市之间）<br />b.有申请人名字的全程机票订单和全程酒店订单（必须与您的英文行程 &nbsp; 单保持一致）<br />', 1, 0, 'V10069', '1610000002', '2013-11-07 09:44:55.190000', NULL, NULL, 1, 1, 0, 15);
INSERT INTO `visa_data` VALUES (2585, 'V131107000545', 'V131107000531', '医疗保险证明', '<p>保险：旅游医疗保险证明原件和复印件（须是电脑出单，手写保单无效）</p><p>a、保险金额不低于30万元人民币。</p><p>b、旅行医疗保险须超于整个旅行日期的2-3天，以备延期之用。</p>', 1, 0, 'V10069', '1610000002', '2013-11-07 09:44:55.207000', NULL, NULL, 1, 1, 0, 16);
INSERT INTO `visa_data` VALUES (2586, 'V131107000546', 'V131107000531', '个人申请表', '<p>表格必须用水笔填写，字迹清晰，须本人签字</p>', 1, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.220000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (2587, 'V131107000549', 'V131107000531', '备注', '<p></p>A.办理此签证需要自行递交材料<br />B.领馆保留索要补充资料和要求申请者面试的权利，需本人按领馆要求前往领馆面试或递交补充材料。<br />C.签证由领馆签发，即使客人提供全部材料，也不能保证获得签证。<br />D.所有签证材料不得加注仅供签证使用字樣。<p></p>', 0, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.253000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (2588, 'V131107000551', 'V131107000550', '护照', 'A. &nbsp;1本原件有效期至少半年以上，护照后需有个人本人签名<br />B. &nbsp;有旧护照，则必须提供原件，老护照后也必须本人签名<br />C. &nbsp;若申请人旧护照遗失，则必须提供旧护照的遗失证明（即客人自己写一份遗失说明并签字或者公安机关开具的遗失证明）<br />D. &nbsp;&nbsp;有 2 张以上的空白可用页<br />', 0, 0, 'V10069', '1610000002', '2013-11-07 09:44:55.283000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2589, 'V131107000553', 'V131107000550', '照片', '最近半年内白底彩色照片，照片大小为（3.5*4.5）厘米：<br />A.从头发最高处至下颚占全部相片高度的70%-80%<br />B.4张并在背后附签名<br />C.务必请配合清晰的露出五官。<br />', 1, 0, 'V10069', '1610000002', '2013-11-07 09:44:55.317000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2590, 'V131107000554', 'V131107000550', '户口薄', '<p>全家户口本整本原件及复印件：</p><p>a.户口本的服务处所/职务必须与所提供公司营业执照名称一致</p><p>b.爱人、小孩户口不在同一本户口本上，必须提供爱人和小孩所在户口本的整本户口本复印件</p><p>c.军人提供军官证复印件</p><br />', 1, 0, 'V10069', '1610000002', '2013-11-07 09:44:55.330000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2591, 'V131107000555', 'V131107000550', '结婚证/离婚证', 'A.申请人为已婚身份，请提供1份结婚证复印件<br />B.申请人为离婚身份，请提供1份离婚证复印件<br />', 1, 0, 'V10069', '1610000002', '2013-11-07 09:44:55.347000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2592, 'V131107000556', 'V131107000550', '资产证明', '申请人本人名下的房产证复印件<br />', 1, 0, 'V10069', '1610000002', '2013-11-07 09:44:55.360000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2593, 'V131107000557', 'V131107000550', '退休证', '<p>提供本人退休证复印件<br /><br /></p>', 1, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.377000', NULL, NULL, 0, 1, 0, 0);
