INSERT INTO `visa_data` VALUES (2595, 'V131107000559', 'V131107000550', '银行工资卡对账单', '<p>申请人本人名下对账单:盖有银行公章的近6个月完整养老金的对帐单（余额不要低于1万元）</p><br />', 1, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.410000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2596, 'V131107000560', 'V131107000550', '旅行证明', '<p>a.英文的覆盖全程的简单行程（城市与城市之间）</p><p>b.有申请人名字的全程机票订单和全程酒店订单（必须与您的英文行程&nbsp;&nbsp; 单保持一致）</p><br />', 1, 0, 'V10069', '1610000002', '2013-11-07 09:44:55.423000', NULL, NULL, 1, 1, 0, 13);
