INSERT INTO `visa_data` VALUES (2604, 'V131107000572', 'V131107000566', '学校准假证明', '1份申请人所在学校证明原件：<br />A  有学校抬头信笺、学校负责人签字、学校盖章；<br />B  内容包含：申请人的姓名、护照号、性别、班级，出行时间、目的，费用承担方，并保证其按时回国等；<br />C  必须为A4或学校信纸打印英文，手写无效。<br />D  如学生处于升学期间、须提供毕业证书复印件以及录取通知书复印件。<br />', 0, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.597000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2605, 'V131107000574', 'V131107000566', '公证认证', 'A  与父母双方一同出行的，提供省、市或区县级公证处出具的出生公证和认证书原件。（请注意：一律提供出生公证，不能是亲属公证）<br />B  与父母一方出行的，在原有出生公证认证的基础上，另需提供一份不出行一方的委托公证认证书原件（内容主要是同意小孩随另一方出国旅游，同时请提供不出行一方的在职证明原件及工资单，以上材料18周岁以上可以不提供）<br />C  所有公证书必须是中英文版本<br />注：18周岁以下及18周岁以上在校生，仅假期内可以申请签证；<br />', 0, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.627000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2606, 'V131107000575', 'V131107000566', '身份证', '必须在有效期内，新版身份证必须正反两面复印。（17周岁以上学生提供）', 0, 0, 'V10069', '1610000002', '2013-11-07 09:44:55.643000', NULL, NULL, 0, 1, 0, 0);
