INSERT INTO `visa_data` VALUES (2614, 'V131107000589', 'V131107000584', '结婚证/离婚证', '<p>.A.申请人为已婚身份，请提供1份结婚证复印件</p><p>B.申请人为离婚身份，请提供1份离婚证复印件</p><p>C.家庭妇女需结婚证公证认证(中英文版）</p><br />', 1, 0, 'V10069', '1610000002', '2013-11-07 09:44:55.800000', NULL, NULL, 0, 1, 0, 0);
