INSERT INTO `visa_data` VALUES (2616, 'V131107000591', 'V131107000584', '收入来源证明 ', '<p>请提供本人收人情况说明，资金来源。</p><p>A.无业未婚的;a.提供父母的在职证明，营业执照，6个月工资单</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; b.父母的出资说明 和资产证明</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;c.申请人本人名下的6个月对账单</p><p>B.无业离婚的，提供自己有效的经济来源及申请人本人名下的6个月对账单</p><p>C.无业已婚的：</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; a..配偶工作单位出具的英文在职证明原件，需使用单位抬头纸打印加盖公章、签字并明确日期及如下信息：单位地址、电话、传真号码，单位签字人员的姓名和职务，申请人配偶的姓名、职务、收入和工作年限。<br style=\"margin: 0px; padding: 0px;\" />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;b..配偶的6个月工资卡对账单盖银行章。<br style=\"margin: 0px; padding: 0px;\" />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;c.配偶出具的经济担保证明书（内容需包含：担保出行人在签证有效期内按时回国，且承担其出行的所有 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 费用）。</p><br />', 0, 1, 'V10069', '1610000002', '2013-11-07 09:44:55.823000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2617, 'V131107000592', 'V131107000584', '身份证', '身份证必须在有效期内，须正反两面复印。', 0, 0, 'V10069', '1610000002', '2013-11-07 09:44:55.840000', NULL, NULL, 0, 1, 0, 0);
