INSERT INTO `visa_data` VALUES (2627, 'V131107000634', 'V131107000630', '户口薄', '<p><span style=\"font-size:12.0pt;font-family:宋体;\"></span></p><p>全家户口本整本原件及复印件：</p><p>a.户口本的服务处所/职务必须与所提供公司营业执照名称一致</p><p>b.爱人、小孩户口不在同一本户口本上，必须提供爱人和小孩所在户口本的整本户口本复印件</p><p>c.军人提供军官证复印件</p><p></p><br />', 1, 1, 'V10070', '1610000002', '2013-11-07 10:00:57.730000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2628, 'V131107000635', 'V131107000630', '结婚证/离婚证', 'A.申请人为已婚身份，请提供1份结婚证复印件<br /><p>B.申请人为离婚身份，请提供1份离婚证复印件</p><p><br /></p>', 1, 1, 'V10070', '1610000002', '2013-11-07 10:00:57.760000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2629, 'V131107000636', 'V131107000630', '在职证明', '<p>在职人员提供单位工作证明信一份：（信纸必须用单位正规抬头纸，上有公司地址、电话和传真）必须盖有单位公章章、註明签字领导的姓名、职务及联系电话。（同行人不能作为证明信的签字人）</p><p>&nbsp; 工作证明信中必须注明以下内容：本人在公司所担任的职务、本人的收入、休假时间许可，保证其遵守法律以及在行程后按时回国并继续就职，并标注营业执照号码。</p><br />', 1, 1, 'V10070', '1610000002', '2013-11-07 10:00:57.777000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2630, 'V131107000638', 'V131107000630', '营业执照', 'A. 申请人为企业性质的公司：提供1份有经营范围的营业执照<br />B. 申请人为非企业性质的公司：提供组织机构代码证<br />注：营业执照和组织机构代码证均为清晰的复印件并加盖公司公章<br />', 1, 1, 'V10070', '1610000002', '2013-11-07 10:00:57.933000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2631, 'V131107000639', 'V131107000630', '资产证明', '申请人本人名下的其他资产复印件。房产证，车证，股票等等。<br />', 1, 1, 'V10070', '1610000002', '2013-11-07 10:00:57.947000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2632, 'V131107000640', 'V131107000630', '身份证', '身份证必须在有效期内，须正反两面复印。', 1, 1, 'V10070', '1610000002', '2013-11-07 10:00:57.963000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2633, 'V131107000641', 'V131107000630', '名片', '2张申请人本人的名片，内容真实无误。', 1, 1, 'V10070', '1610000002', '2013-11-07 10:00:57.980000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2634, 'V131107000642', 'V131107000630', '工资单或银行对账单', '申请人本人名下对账单<span lang=\"EN-US\">:</span>盖有银行公章的近<span lang=\"EN-US\">6</span>个月完整工资的对帐单或借记卡都账单（不可以用信用卡且余额不要低于<span lang=\"EN-US\">1</span>万元）<br />', 1, 1, 'V10070', '1610000002', '2013-11-07 10:00:57.993000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2635, 'V131107000643', 'V131107000630', '旅行证明', 'a.英文的覆盖全程的简单行程（城市与城市之间）<br />b.有申请人名字的全程机票订单和全程酒店订单（必须与您的英文行程 &nbsp; 单保持一致）<br />', 1, 1, 'V10070', '1610000002', '2013-11-07 10:00:58.010000', NULL, NULL, 1, 1, 0, 15);
INSERT INTO `visa_data` VALUES (2636, 'V131107000644', 'V131107000630', '医疗保险证明', '<p>保险：旅游医疗保险证明原件和复印件（须是电脑出单，手写保单无效）</p><p>a、保险金额不低于30万元人民币。</p><p>b、旅行医疗保险须超于整个旅行日期的2-3天，以备延期之用。</p><br />', 1, 1, 'V10070', '1610000002', '2013-11-07 10:00:58.027000', NULL, NULL, 1, 1, 0, 16);
INSERT INTO `visa_data` VALUES (2637, 'V131107000645', 'V131107000630', '个人申请表', '<p>表格必须用水笔填写，字迹清晰，须本人签字</p>', 1, 1, 'V10070', '1610000002', '2013-11-07 10:00:58.057000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (2638, 'V131107000647', 'V131107000630', '备注', '<p></p><p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \"></p>A.领馆保留索要补充资料和要求申请者面试的权利，需本人按领馆要求前往领馆面试或递交补充材料。<br />B.签证由领馆签发，即使客人提供全部材料，也不能保证获得签证。<br />C.所有签证材料不得加注仅供签证使用字樣<p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \"></p><p></p>', 0, 1, 'V10070', '1610000002', '2013-11-07 10:00:58.120000', NULL, NULL, 1, 1, 1, 1);
