INSERT INTO `visa_data` VALUES (2664, 'V131107000682', 'V131107000678', '户口薄', '<p>全家户口本整本原件及复印件：</p><p>a.户口本的服务处所/职务必须与所提供公司营业执照名称一致。</p><p>b.爱人、小孩户口不在同一本户口本上，必须提供爱人和小孩所在户口本的整本户口本复印件。</p><p>c.军人提供军官证复印件。</p>', 1, 0, 'V10070', '1610000002', '2013-11-07 10:00:58.730000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2665, 'V131107000683', 'V131107000678', '结婚证/离婚证', '<p>.A.申请人为已婚身份，请提供1份结婚证复印件</p><p>B.申请人为离婚身份，请提供1份离婚证复印件</p><p>C.家庭妇女需结婚证公证认证(中英文版）</p>', 1, 0, 'V10070', '1610000002', '2013-11-07 10:00:58.743000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2666, 'V131107000684', 'V131107000678', '资产证明', '<p>申请人本人名下的房产证复印件</p>', 1, 0, 'V10070', '1610000002', '2013-11-07 10:00:58.760000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2667, 'V131107000685', 'V131107000678', '收入来源证明 ', '<p>请提供本人收人情况说明，资金来源。</p><p>A.无业未婚的;a.提供父母的在职证明，营业执照，6个月工资单</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; b.父母的出资说明 和资产证明</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;c.申请人本人名下的6个月对账单</p><p>B.无业离婚的，提供自己有效的经济来源及申请人本人名下的6个月对账单</p><p>C.无业已婚的：</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; a..配偶工作单位出具的英文在职证明原件，需使用单位抬头纸打印加盖公章、签字并明确日期及如下信息：单位地址、电话、传真号码，单位签字人员的姓名和职务，申请人配偶的姓名、职务、收入和工作年限。<br style=\"margin: 0px; padding: 0px;\" />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;b..配偶的6个月工资卡对账单盖银行章。<br style=\"margin: 0px; padding: 0px;\" />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;c.配偶出具的经济担保证明书（内容需包含：担保出行人在签证有效期内按时回国，且承担其出行的所有 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 费用）。</p><br />', 1, 1, 'V10070', '1610000002', '2013-11-07 10:00:58.790000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2668, 'V131107000686', 'V131107000678', '身份证', '身份证必须在有效期内，须正反两面复印。', 0, 0, 'V10070', '1610000002', '2013-11-07 10:00:58.807000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2671, 'V131107000689', 'V131107000678', '个人申请表', '<p>表格必须用水笔填写，字迹清晰，须本人签字</p>', 0, 0, 'V10070', '1610000002', '2013-11-07 10:00:58.870000', NULL, NULL, 1, 1, 1, 5);
INSERT INTO `visa_data` VALUES (2676, 'V131107000701', 'V131107000648', '备注', '<p></p><p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \"></p>A.领馆保留索要补充资料和要求申请者面试的权利，需本人按领馆要求前往领馆面试或递交补充材料。<br />B.签证由领馆签发，即使客人提供全部材料，也不能保证获得签证。<br />C.所有签证材料不得加注仅供签证使用字樣<p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \"></p><p></p>', 0, 0, 'V10070', '1610000002', '2013-11-07 10:18:37.373000', NULL, NULL, 1, 1, 1, 12);
INSERT INTO `visa_data` VALUES (2680, 'V131111000746', 'V131107000678', '旅行证明', 'a.英文的覆盖全程的简单行程（城市与城市之间）<br />b.有申请人名字的全程机票订单和全程酒店订单（必须与您的英文行程 &nbsp; 单保持一致）<br />', 1, 0, 'V10070', '1610000002', '2013-11-11 13:06:35.877000', NULL, NULL, 1, 1, 0, 10);
INSERT INTO `visa_data` VALUES (2681, 'V131111000747', 'V131107000678', '医疗保险证明', '<p>保险：旅游医疗保险证明原件和复印件（须是电脑出单，手写保单无效）</p><p>a、保险金额不低于30万元人民币。</p><p>b、旅行医疗保险须超于整个旅行日期的2-3天，以备延期之用。</p><br />', 1, 0, 'V10070', '1610000002', '2013-11-11 13:06:36.000000', NULL, NULL, 1, 1, 0, 11);
INSERT INTO `visa_data` VALUES (2682, 'V131111000748', 'V131107000678', '备注', '<p></p><p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \"></p>A.领馆保留索要补充资料和要求申请者面试的权利，需本人按领馆要求前往领馆面试或递交补充材料。<br />B.签证由领馆签发，即使客人提供全部材料，也不能保证获得签证。<br />C.所有签证材料不得加注仅供签证使用字樣<p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \"></p><p></p>', 0, 0, 'V10070', '1610000002', '2013-11-11 13:06:36.033000', NULL, NULL, 1, 1, 1, 12);
