INSERT INTO `visa_data` VALUES (2770, 'V140115000101', 'V140115000092', '银行工资卡对账单', '<p>申请人本人名下对账单:盖有银行公章的近6个月完整养老金的对帐单（余额不要低于1万元）</p><br />', 1, 1, 'V10072', '1610000002', '2014-01-15 09:53:00.450000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2771, 'V140115000102', 'V140115000092', '旅行证明', '<p>a.英文的覆盖全程的简单行程（城市与城市之间）</p><p>b.有申请人名字的全程机票订单和全程酒店订单（必须与您的英文行程&nbsp;&nbsp; 单保持一致）</p><br />', 1, 0, 'V10072', '1610000002', '2014-01-15 09:53:00.463000', NULL, NULL, 1, 1, 0, 13);
INSERT INTO `visa_data` VALUES (2772, 'V140115000103', 'V140115000092', '医疗保险证明', '<p>保险：旅游医疗保险证明原件和复印件（须是电脑出单，手写保单无效）</p><p>a、保险金额不低于30万元人民币。</p><p>b、旅行医疗保险须超于整个旅行日期的2-3天，以备延期之用。</p><br />', 1, 0, 'V10072', '1610000002', '2014-01-15 09:53:00.480000', NULL, NULL, 1, 1, 0, 14);
INSERT INTO `visa_data` VALUES (2773, 'V140115000104', 'V140115000092', '个人申请表', '<p>表格必须用水笔填写，字迹清晰，须本人签字</p>', 0, 0, 'V10072', '1610000002', '2014-01-15 09:53:00.497000', NULL, NULL, 1, 1, 1, 12);
INSERT INTO `visa_data` VALUES (2774, 'V140115000107', 'V140115000092', '备注', '<p></p><p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \">A.办理此签证需要自行递交材料</p><p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \">B.领馆保留索要补充资料和要求申请者面试的权利，需本人按领馆要求前往领馆面试或递交补充材料。</p><p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \">C.签证由领馆签发，即使客人提供全部材料，也不能保证获得签证。</p><p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \">D.所有签证材料不得加注仅供签证使用字樣。</p><p></p>', 0, 1, 'V10072', '1610000002', '2014-01-15 09:53:00.510000', NULL, NULL, 0, 1, 0, 12);
INSERT INTO `visa_data` VALUES (2775, 'V140115000109', 'V140115000108', '护照', 'A. &nbsp;1本原件有效期至少半年以上，护照后需有个人本人签名<br />B. &nbsp;有旧护照，则必须提供原件，老护照后也必须本人签名<br />C. &nbsp;若申请人旧护照遗失，则必须提供旧护照的遗失证明（即客人自己写一份遗失说明并签字或者公安机关开具的遗失证明）<br />D. &nbsp;有 2 张以上的空白可用页<br />', 0, 0, 'V10072', '1610000002', '2014-01-15 09:53:00.560000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2776, 'V140115000111', 'V140115000108', '照片', '最近半年内白底彩色照片，照片大小为（3.5*4.5）厘米：<br />A.从头发最高处至下颚占全部相片高度的70%-80%<br />B.4张并在背后附签名<br />C.务必请配合清晰的露出五官。<br />', 1, 0, 'V10072', '1610000002', '2014-01-15 09:53:00.573000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2777, 'V140115000112', 'V140115000108', '户口薄', '<p>全家户口本整本原件及复印件：</p><p>a.户口本的服务处所/职务必须与所提供公司营业执照名称一致</p><p>b.爱人、小孩户口不在同一本户口本上，必须提供爱人和小孩所在户口本的整本户口本复印件</p><p>c.军人提供军官证复印件</p><br />', 1, 0, 'V10072', '1610000002', '2014-01-15 09:53:00.590000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2778, 'V140115000113', 'V140115000108', '资产证明', '申请人本人名下或父母名下的房产证复印件<br />', 1, 0, 'V10072', '1610000002', '2014-01-15 09:53:00.590000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2779, 'V140115000114', 'V140115000108', '学校准假证明', '1份申请人所在学校证明原件：<br />A  有学校抬头信笺、学校负责人签字、学校盖章；<br />B  内容包含：申请人的姓名、护照号、性别、班级，出行时间、目的，费用承担方，并保证其按时回国等；<br />C  必须为A4或学校信纸打印英文，手写无效。<br />D  如学生处于升学期间、须提供毕业证书复印件以及录取通知书复印件。<br />', 0, 1, 'V10072', '1610000002', '2014-01-15 09:53:00.607000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2780, 'V140115000116', 'V140115000108', '公证认证', 'A  与父母双方一同出行的，提供省、市或区县级公证处出具的出生公证和认证书原件。（请注意：一律提供出生公证，不能是亲属公证）<br />B  与父母一方出行的，在原有出生公证认证的基础上，另需提供一份不出行一方的委托公证认证书原件（内容主要是同意小孩随另一方出国旅游，同时请提供不出行一方的在职证明原件及工资单，以上材料18周岁以上可以不提供）<br />C  所有公证书必须是中英文版本<br />注：18周岁以下及18周岁以上在校生，仅假期内可以申请签证；<br />', 0, 1, 'V10072', '1610000002', '2014-01-15 09:53:00.637000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2781, 'V140115000117', 'V140115000108', '身份证', '必须在有效期内，新版身份证必须正反两面复印。（17周岁以上学生提供）', 0, 0, 'V10072', '1610000002', '2014-01-15 09:53:00.653000', NULL, NULL, 0, 1, 0, 0);
