INSERT INTO `visa_data` VALUES (2789, 'V140115000129', 'V140115000124', '结婚证/离婚证', '<p>.A.申请人为已婚身份，请提供1份结婚证复印件</p><p>B.申请人为离婚身份，请提供1份离婚证复印件</p><p>C.家庭妇女需结婚证公证认证(中英文版）</p><br />', 1, 0, 'V10072', '1610000002', '2014-01-15 09:53:00.813000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2790, 'V140115000130', 'V140115000124', '资产证明', '<p>申请人本人名下的房产证复印件</p><br />', 1, 0, 'V10072', '1610000002', '2014-01-15 09:53:00.830000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2791, 'V140115000131', 'V140115000124', '收入来源证明 ', '<p>请提供本人收人情况说明，资金来源。</p><p>A.无业未婚的;a.提供父母的在职证明，营业执照，6个月工资单</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; b.父母的出资说明 和资产证明</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;c.申请人本人名下的6个月对账单</p><p>B.无业离婚的，提供自己有效的经济来源及申请人本人名下的6个月对账单</p><p>C.无业已婚的：</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; a..配偶工作单位出具的英文在职证明原件，需使用单位抬头纸打印加盖公章、签字并明确日期及如下信息：单位地址、电话、传真号码，单位签字人员的姓名和职务，申请人配偶的姓名、职务、收入和工作年限。<br style=\"margin: 0px; padding: 0px;\" />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;b..配偶的6个月工资卡对账单盖银行章。<br style=\"margin: 0px; padding: 0px;\" />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;c.配偶出具的经济担保证明书（内容需包含：担保出行人在签证有效期内按时回国，且承担其出行的所有 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 费用）。</p><br />', 1, 1, 'V10072', '1610000002', '2014-01-15 09:53:00.847000', NULL, NULL, 0, 1, 0, 0);
INSERT INTO `visa_data` VALUES (2792, 'V140115000132', 'V140115000124', '身份证', '身份证必须在有效期内，须正反两面复印。', 0, 0, 'V10072', '1610000002', '2014-01-15 09:53:00.860000', NULL, NULL, 0, 1, 0, 0);
