INSERT INTO `visa_data` VALUES (2796, 'V140115000138', 'V140115000124', '备注', '<p></p><p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \">A.办理此签证需要自行递交材料</p><p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \">B.领馆保留索要补充资料和要求申请者面试的权利，需本人按领馆要求前往领馆面试或递交补充材料。</p><p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \">C.<span style=\"font-family: Arial, simsun; background-color: rgb(254, 254, 254); \">即使客人提供全部材料，也不能保证获得签证。</span></p><p style=\"margin: 0px; padding: 0px; font-family: Arial, simsun; background-color: rgb(254, 254, 254); \">D.所有签证材料不得加注仅供签证使用字樣。</p><p></p>', 0, 1, 'V10072', '1610000002', '2014-01-15 09:53:00.923000', NULL, NULL, 1, 1, 1, 12);
INSERT INTO `visa_data` VALUES (2797, 'V140516000039', 'V140515000001', '中国大陆因私护照', '<p>1、行程结束以后还有6个月以上有效期</p><p>2、至少留有2页空白页</p><p>3、不接受5年内被拒签过的护照</p>', 1, 1, 'V10073', '1610000002', '2014-05-16 17:07:57.207000', NULL, NULL, 1, 1, 1, 1);
INSERT INTO `visa_data` VALUES (2798, 'V140516000041', 'V140515000001', '照片', '2张2寸（4.5mm*4.5mm）白底彩照要近6个月的（背后用铅笔写上名字）', 1, 1, 'V10073', '1610000002', '2014-05-16 17:09:23.687000', NULL, NULL, 1, 2, 1, 2);
INSERT INTO `visa_data` VALUES (2799, 'V140516000043', 'V140515000001', '身份证和户口薄', '<p>1、身份证正反面复印件</p><p>2、户口薄整本复印件</p><p>备注：如果夫妻或子女不在一本上也要提供整本</p>', 0, 1, 'V10073', '1610000002', '2014-05-16 17:10:23.307000', NULL, NULL, 1, 2, 1, 6);
INSERT INTO `visa_data` VALUES (2800, 'V140516000046', 'V140515000001', '在职证明', '<p>1、提供所在公司的抬头纸中文在职证明，并注明年薪要达到10万或10万以上，或月薪*12达到10万或10以上，并加盖公司公章红色</p><p>2、提供所在公司的营业执照复印件或组织机构代码证复印件并加盖公司公张红色</p>', 0, 1, 'V10073', '1610000002', '2014-05-16 17:16:31.433000', NULL, NULL, 1, 1, 1, 7);
INSERT INTO `visa_data` VALUES (2801, 'V140516000050', 'V140515000001', '资产证明', '<p>1、银行拉出的对账单近6个月明细，证明月收入符合在职证明上的年薪或月薪</p><p>2、存款证明5万或5万以上并冻结3个月</p><p>3、房产证复印件</p><p>4、车产证复印件</p>', 1, 1, 'V10073', '1610000002', '2014-05-16 17:21:08.530000', NULL, NULL, 1, 4, 1, 8);
INSERT INTO `visa_data` VALUES (2802, 'V140516000052', 'V140515000001', '申请表格', '用黑色水笔客人亲自填写的申请表格，必须填写完整并在表格背后亲自签名，写上日期', 1, 1, 'V10073', '1610000002', '2014-05-16 17:23:08.177000', NULL, NULL, 1, 1, 1, 3);
INSERT INTO `visa_data` VALUES (2803, 'V140516000055', 'V140515000001', '个人信息同意书', '客人用黑色水笔亲自签名并写上日期', 1, 1, 'V10073', '1610000002', '2014-05-16 17:24:16.637000', NULL, NULL, 1, 1, 1, 4);
INSERT INTO `visa_data` VALUES (2805, 'V140516000062', 'V140515000002', '中国大陆因私护照', '<p>1、行程结束以后还有6个月以上有效期</p><p>2、至少留有2页空白页</p><p>3、不接受5年内被拒签过的护照</p>', 1, 0, 'V10073', '1610000002', '2014-05-16 17:28:02.497000', NULL, NULL, 1, 1, 1, 1);
