INSERT INTO `visa_data` VALUES (2976, 'V140516000597', 'V140516000572', '身份证和户口薄', '<p>1、身份证正反面复印件</p><p>2、户口薄整本复印件</p><p>备注：如果夫妻或子女不在一本上也要提供整本</p>', 1, 1, 'V10079', '1610000002', '2014-05-16 20:50:46.020000', NULL, NULL, 1, 2, 1, 5);
INSERT INTO `visa_data` VALUES (2977, 'V140516000601', 'V140516000572', '在职证明', '<p>1、提供所在公司的抬头纸中文在职证明，并注明年薪要达到30万或30万以上，或月薪*12达到30万或30以上，并加盖公司公章红色和财务章红色</p><p>2、提供所在公司的营业执照复印件或组织机构代码证复印件并加盖公司公章红色</p>', 1, 1, 'V10079', '1610000002', '2014-05-16 20:53:14.960000', NULL, NULL, 1, 1, 1, 6);
INSERT INTO `visa_data` VALUES (2978, 'V140516000611', 'V140516000605', '中国大陆因私护照', '<span style=\"color: rgb(33, 37, 41);\">1、行程结束后至少还有6个月有效期。</span><br style=\"color: rgb(33, 37, 41);\"><span style=\"color: rgb(33, 37, 41);\">2、老版护照在第7-47页范围内（电子护照在第8-45页范围内），至少留有1页空白签证页。</span><br style=\"color: rgb(33, 37, 41);\"><span style=\"color: rgb(33, 37, 41);\">3、护照末页请本人用中文签名，学龄前儿童可由父母用中文代签名（不可用铅笔）（电子护照除外）。</span>', 0, 0, 'V10080', '1610000002', '2014-05-16 20:56:49.177000', NULL, NULL, 1, 1, 0, 1);
INSERT INTO `visa_data` VALUES (2980, 'V140516000615', 'V140516000572', '资产证明', '<p>1、符合年薪30万或30万以上相对应的个人所得税单，并加盖税务局红章（如提供不了需提供100万元的存款证明以及为何不能提供税单的说明）</p><p>2、银行拉出的对账单近6个月明细，证明月收入符合在职证明上的年薪或月薪</p><p>3、存款证明10万或10万以上并冻结3个月</p><p>4、房产证复印件</p><p>5、车产证复印件</p>', 0, 1, 'V10079', '1610000002', '2014-05-16 20:59:02.053000', NULL, NULL, 1, 1, 1, 7);
