INSERT INTO `visa_data` VALUES (2996, 'V140516000641', 'V140516000573', '资产证明', '<p><span style=\"font-family: Arial, simsun; background-color: rgb(254, 254, 254); \">提供退休人员直系亲属的在职证明，如：夫妻、子女</span><br /></p><p>1、符合年薪30万或30万以上相对应的个人所得税单，并加盖税务局红章（如提供不了需提供100万元的存款证明以及为何不能提供税单的说明）</p><p>2、<span style=\"font-family: Arial, simsun; background-color: rgb(254, 254, 254); \">银行拉出的对账单近6个月明细，证明月收入符合在职证明上的年薪或月薪</span></p><p></p><p>3、存款证明10万或10万以上并冻结3个月</p><p>4、房产证复印件</p><p>5、车产证复印件</p>', 0, 0, 'V10079', '1610000002', '2014-05-16 20:59:53.677000', NULL, NULL, 1, 1, 1, 8);
INSERT INTO `visa_data` VALUES (2997, 'V140516000642', 'V140516000573', '机票酒店', '客人自己预定的机票酒店订单 （第一晚必须住冲绳）', 0, 0, 'V10079', '1610000002', '2014-05-16 20:59:53.707000', NULL, NULL, 1, 1, 1, 9);
