INSERT INTO `visa_datafiles` VALUES (1106, 'V2004000017', 'V120929002278', 'http://yuanfile.sh-cct.cn/Files/visa/V20030/20200429_151821_2248.jpg', '护照模板', '1610000002', '2020-04-29 15:18:21.640000', 'V20030');
INSERT INTO `visa_information` VALUES (2, 'V10001', '1812000014', 1, '菲律宾个签', 1, 2, 3, 1, 1, '日本', '/8/', '2', 555.0000, 0.0000, '5个工作日', '中国大陆因私护照', '3个月，以领馆实际签出的结果为准', '14天', '单次', 0, '<p>1、3张2寸白底照片。</p><p>2、护照（有效期6个月以上的中国护照，护照最后一页签名）。</p><p>3、在职证明。</p><p>4、个人申请表。</p>', '<div class=\"align_l\">1、价格含签证工本费及服务费，不含保险费。</div><div class=\"align_l\">2、上海市户口的申请人在市区级公证处均可以办理公证书。部分公证处联系方式以供参考：静安区公证处（电话：62671801、32170441）、杨浦区公证处（电话：65899528）、浦东新区公证处（电话：58396060、58395050）。请在去公证处前先准备齐全资料，可以缩短公证书的办理时间。</div><div class=\"align_l\">◆办理亲属关系公证书所需材料：父母和未成年子女的身份证及户口本原件；结婚证书原件；未成年子女出生证或独生子女证原件。</div>', 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-09-04 14:19:03.000000', '1610000002', '管理员', '2012-09-04 17:42:49.000000', NULL, '程臻', '2012-09-04 17:44:07.000000', NULL, 1, '/1/50/', 48, 5, 0, 370.0000, '1611000001');
INSERT INTO `visa_information` VALUES (3, 'V10002', '1812000014', 1, '泰国个人签证', 1, 2, 3, 1, 1, '日本', '/8/', '2', 390.0000, 0.0000, '5个工作日', '中国大陆因私护照（包含电子普通护照）\r\n如是北京、广东、福建、广西、天津、河北、海南、云南、重庆、四川、陕西、香港、澳门签发的护照，另须提供从签发期起至今已有半年以上有效期的江、浙、沪的暂住证或居住证原件及复印件；或提供江、浙、沪身份证原件及复印件。', '3个月', '3个月', '单次', 0, '<p>1、半年内拍摄的2寸(3.5cmx4.5cm)白底彩照2张(照片背面签字)。</p><p>2、护照（有效期6个月以上的中国护照，护照最后一页签名）。</p><p>3、护照在归国后至少还有半年以上有效期，护照末页需本人中文签名（不要用铅笔签名）；护照至少留有连续2页的空白签证页，不含备注页。</p>', '<span style=\"color:#000000;TEXT-ALIGN: left; WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/20px Arial, Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">如果最近一次办理过泰国签证且没有使用，需等该签证失效后才可以再次办理。</span>', 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-09-05 11:37:48.000000', '1610000002', '管理员', '2012-09-05 11:43:48.000000', NULL, '梁珺', '2012-09-05 11:44:23.000000', NULL, 1, '/1/50/', 24, 1, -1, 260.0000, '1611000001');
INSERT INTO `visa_information` VALUES (4, 'V10003', '1812000014', 1, '马来西亚个人签证', 1, 2, 3, 1, 1, '日本', '/8/', '2', 270.0000, 0.0000, '4个工作日', '全国（除了新疆地区以外）', '3个月', '30天', '单次', 0, '<p>1. 护照在归国后至少还有半年以上有效期，护照末页需本人中文签名（不要用铅笔签名）；马签必须保持4面以上空白签证页，否则拒签，我社一概不负责，不含备注页。</p><p>2. 半年内拍摄的2寸(3.5cmx4.5cm)白底彩照2张(照片背面签字)。</p>', NULL, 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-09-05 13:43:49.000000', '1610000002', '管理员', '2012-09-05 13:44:11.000000', NULL, '梁珺', '2012-09-05 13:45:29.000000', NULL, 1, '/1/50/', 24, 1, -1, 180.0000, '1611000001');
INSERT INTO `visa_information` VALUES (5, 'V10004', '1812000014', 1, '印度尼西亚旅游签证', 1, 2, 5, 1, 1, '印度尼西亚', '/10/', '2', 1000.0000, 0.0000, '8个工作日 ', '全国', '3个月 ', '30天', '单次', 0, '1.必须提供英文在职证明2.单身女性必须提供良好在职保证', NULL, 'Files/pic/10/5/636517128296959560.gif', NULL, '1610000002', '管理员', '2012-09-05 14:52:27.000000', '1610000002', '管理员', '2012-09-05 15:12:12.000000', '1610000002', '陈璐', '2014-05-16 20:45:35.000000', NULL, 1, '/1/50/', 48, 1, 1, 650.0000, '1611000001');
INSERT INTO `visa_information` VALUES (6, 'V10005', '1812000014', 1, '新加坡个人旅游签证（20个城市）', 1, 2, 3, 1, 1, '日本', '/8/', '2', 322.5000, 0.0000, '上海收齐材料后所需5-7个工作日', '申请人的护照首页下面第二排数字最后四位连续的城市代码，都符合以下城市名称和城市代码的因私护照：\r\n北京(1100、1101、1102)、上海(3100、3101、3102)、广州(4401)\r\n天津(1200)、沈阳(2101)、哈尔滨(2301)、大连(2102)\r\n南京(3201)、无锡(3202)、苏州(3205)、杭州(3301)\r\n厦门(3502)、深圳(4403)\r\n西安(6101)、济南(3701)、青岛(3702)\r\n成都(5101)、昆明(5301)、重庆(5000)\r\n福州(必须是3501,且必须提供以35010开头的身份证复印件)\r\n护照签发地为中国驻外使领馆的、电子普通护照，请按20城市外提交订单。 ', '35天或1年，以领馆实际签出的结果为准', '以入境时边防所盖章为准', '多次', 0, '<dt class=\"red\">1、新加坡领馆从2009-7-1起实行电子签证，我司会在出签后将电子签证打印给您。电子签证可以复印使用。 </dt><dt class=\"red\">2、如之前申请过新加坡签证，请确保签证页已过期，否则领馆将给予拒签。</dt><dt class=\"red\">3、您的护照在换发后，如新加坡签证仍在有效期内，请携带新旧护照、签证页原件和本人2寸白底彩照一张亲自递交至新加坡领馆并当场填写申请表格办理转签手续。上海新加坡领馆地址：万山路89号。</dt><dt class=\"red\">4、由于新加坡签证是另纸电子签证，为一A4纸订在护照上。请不要将此签证纸撕下或丢失。</dt>', '<dt class=\"red\">&nbsp;</dt>', 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-09-05 15:06:12.000000', '1610000002', '管理员', '2012-09-05 16:36:06.000000', NULL, '侯竞燕', '2012-09-05 16:36:27.000000', NULL, 1, '/1/50/', 48, 3, NULL, 215.0000, '1611000001');
INSERT INTO `visa_information` VALUES (7, 'V10006', '1812000014', 1, '韩国个人旅游签证', 1, 2, 3, 1, 1, '韩国', '/36/', '2', 480.0000, 0.0000, '上海收齐材料后所需工作日7个，异地收齐材料后所需工作日9个', '常住地和工作地是上海、浙江、江苏、安徽，且护照（包含电子普通护照）签发地为以上四地的中国公民。如护照是上海、浙江、江苏、安徽以外签发或国外换发，需在以上四地工作、生活或学习并提供已有三个月记录的有效暂住证或居住证复印件或以上四地户口簿复印件。', '3个月', '30天（以领馆签发为准）', '单次', 1, '<span style=\"color:#4d4d4d;WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); TEXT-INDENT: 0px; DISPLAY: inline !important; FONT: 12px/22px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; FLOAT: none; LETTER-SPACING: normal; WORD-SPACING: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\">如果您的政审不通过，我司可能会视具体材料情况要求您增补材料或者担保金。</span>', NULL, 'Files/pic/36/23/636517268190865266.jpg', NULL, '1610000002', '管理员', '2012-09-05 15:40:45.000000', '1610000002', '管理员', '2012-09-05 17:13:49.000000', NULL, '夏江', '2012-09-07 17:38:14.000000', '/1/50/', 1, '/1/50/', 48, 1, NULL, 320.0000, '1611000001');
INSERT INTO `visa_information` VALUES (8, 'V10007', '1812000014', 1, '新加坡个人旅游签证（20个城市外）', 1, 2, 3, 1, 1, '新加坡', '/34/', '2', 322.0000, 0.0000, '上海收齐材料后所需工作日5个，杭州、南京收齐材料后所需工作日7个，其他地区收齐材料后所需工作日9个', '申请人的护照首页下面第二排数字最后四位连续的城市代码，都不符合以下城市名称或城市代码的因私护照：\r\n北京(1100、1101、1102)、上海(3100、3101、3102)、广州(4401)\r\n天津(1200)、沈阳(2101)、哈尔滨(2301)、大连(2102)\r\n南京(3201)、无锡(3202)、苏州(3205)、杭州(3301)\r\n福州(必须是3501)、厦门(3502)、深圳(4403)\r\n西安(6101)、济南(3701)、青岛(3702)\r\n成都(5101)、昆明(5301)、重庆(5000)\r\n福建除福州3501以外签发的护照不予受理；接收电子普通护照。 ', '35天，以领馆实际签出的结果为准。', '以入境时边防所盖章为准。', '多次', 0, '<dt class=\"red\">1、新加坡领馆从2009-7-1起实行电子签证，我司会在出签后将电子签证打印给您。电子签证可以复印使用。 </dt><dt class=\"red\">2、如之前申请过新加坡签证，请确保签证页已过期，否则领馆将给予拒签。</dt><dt class=\"red\">3、您的护照在换发后，如新加坡签证仍在有效期内，请携带新旧护照、签证页原件和本人2寸白底彩照一张亲自递交至新加坡领馆并当场填写申请表格办理转签手续。上海新加坡领馆地址：万山路89号。</dt><dt class=\"red\">4、由于新加坡签证是另纸电子签证，为一A4纸订在护照上。请不要将此签证纸撕下或丢失。</dt><dt class=\"red\">&nbsp;</dt>', '<dt class=\"red\">&nbsp;我社需要根据材料所定是否送签。</dt>', 'Files/pic/34/20/636517266077155031.jpg', NULL, '1610000002', '管理员', '2012-09-05 16:37:35.000000', '1610000002', '管理员', '2012-09-05 17:27:00.000000', '1610000002', '侯竞燕', '2012-09-05 17:27:14.000000', NULL, 1, '/1/50/', 48, 3, NULL, 215.0000, '1611000001');
INSERT INTO `visa_information` VALUES (9, 'V20008', '1812000014', 2, 'it测试产品，请勿操作', 1, 2, 1, 1, 1, '日本', '/33/', '2', 0.0000, 0.0000, '以领馆为准', '测试', '以领馆为准', '以领馆为准', '单次', 1, ' ', NULL, 'Files/pic/33/3/636516976483802146.jpg', NULL, '1610000002', '管理员', '2012-09-05 17:20:41.000000', '1610000002', '管理员', NULL, NULL, NULL, NULL, '', 1, '/1/50/', 0, NULL, 1, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (10, 'V10009', '1812000014', 1, '柬埔寨个人旅游签证（电子签证）', 1, 2, 3, 1, 1, '柬埔寨', '/35/', '2', 360.0000, 0.0000, '上海收齐材料后所需工作日3个', '中国大陆因私护照（包含电子普通护照）(不接收18周岁以下申请人单独申请签证)', '3个月，以领馆实际签出的结果为准。', '30天', '单次', 0, '<dt class=\"red\">该签证仅适用于链接中的入境与出境口岸：</dt><dt class=\"red\"><table border=\"0\" cellspacing=\"0\" cellpadding=\"0\"><tbody><tr><td style=\"WIDTH: 106.5pt\"><p><strong><span style=\"font-family:宋体;\">口岸名称</span></strong></p></td><td style=\"WIDTH: 106.5pt\"><p><strong><span style=\"font-family:宋体;\">边境</span></strong></p></td><td style=\"WIDTH: 106.55pt\"><p><strong><span style=\"font-family:宋体;\">入境</span></strong></p></td><td style=\"WIDTH: 106.55pt\"><p><strong><span style=\"font-family:宋体;\">出境</span></strong></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:宋体;\">金边国际机场</span></p></td><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:Arial;\">-</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:宋体;\">暹粒国际机场</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:Arial;\">-</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:Arial;\">Cham Yeam (Koh Kong)</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">泰国</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:Arial;\">Chorm (Oddar Meanchey)</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">泰国</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">否</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:Arial;\">Daung (Kamrieng Battambang)</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">泰国</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">否</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:Arial;\">Poi Pet (Banteay Meanchey)</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">泰国</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:Arial;\">Prom (Pailin)</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">泰国</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">否</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:Arial;\">O Smach (Oddar Meanchey)</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">泰国</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">否</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:Arial;\">Bavet (Svay Rieng)</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">越南</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:Arial;\">Kaoam Samnor (Kandal Mekong)</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">越南</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">否</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:Arial;\">Phnom Den (Takeo)</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">越南</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">否</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:Arial;\">Trapaing Sre (Kratie)</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">越南</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">否</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:Arial;\">Dong Kralo (Stung Treng)</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">老挝</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">否</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:Arial;\">Preah Sihanouk International Airport</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:Arial;\">-</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">否</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 106.5pt\"><p><span style=\"font-family:宋体;\">西哈努克镇</span></p></td><td style=\"WIDTH: 106.5pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:Arial;\">-</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">否</span></p></td><td style=\"WIDTH: 106.55pt\"><p style=\"TEXT-ALIGN: center\"><span style=\"font-family:宋体;\">是</span></p></td></tr><tr><td style=\"WIDTH: 426.1pt\" colspan=\"4\"><p><strong><em><span style=\"font-family:宋体;color:red;\">是（支援电子签证）；否（不支援电子签证）</span></em></strong></p></td></tr></tbody></table><p>&nbsp;<table border=\"0\" cellspacing=\"3\" cellpadding=\"0\" width=\"98%\"><tbody><tr><td class=\"yellow14\" width=\"95%\"><div align=\"center\"><strong><span class=\"blue14\"><span style=\"font-size:12px;\">旅游者持非大陆籍居民因私护照前往柬埔寨的说明</span></span></strong></div></td></tr><tr><td valign=\"top\" colspan=\"2\"><img alt=\"\" src=\"http://pages.ctrip.com/images/domestic_tour/space1.gif\" width=\"5\" height=\"5\" /></td></tr></tbody></table><span style=\"font-family:宋体;color:black;FONT-SIZE: 10pt\">旅游者持中国香港特别行政区、中国澳门特别行政区、中国台湾三地颁发的护照赴柬埔寨旅游时，必须办理签证，停留期为30天。<br /></span></p></dt>', '<dt class=\"red\">&nbsp;</dt>', 'Pictures/pic/35/21/636517266658485111.jpg', NULL, '1610000002', '管理员', '2012-09-05 17:29:47.000000', '1610000002', '管理员', '2012-09-05 17:59:44.000000', NULL, '侯竞燕', '2012-09-05 18:00:25.000000', NULL, 1, '/1/50/', 48, 3, NULL, 240.0000, '1611000001');
INSERT INTO `visa_information` VALUES (11, 'V10010', '1801000004', 1, '美国个人旅游签证', 1, 1, 5, 1, 4, '美国', '/17/', '2', 1500.0000, 0.0000, '提前15天交材料，面试后3-5个工作日', '不限制领区', '十年', '以边防敲章为准', '多次', 0, '1、美国旅游签证有效期通常为十年，有效期内可多次进出美国。持有此类签证，您可以自由制定您的旅行计划，单独或者跟随任意团队前往。<br />2、80周岁以上（含80周岁）老人或14周岁（含14周岁）以下儿童，如从未被拒签过，本人无需前往领馆面试，可以通过中信银行的签证“代传递”程序申请签证。或者，如有直系亲属需申请同一类型的签证并需要前往领馆面谈，老人或儿童的材料可由直系亲属带去领馆。<br />3、如申请人上一次赴美签证到期日距此次申请日期不超过12个月、此次申请的签证类型与上次相同，有过期的美国签证页所在的旧护照，您必须在之前的签证面试时提供过十指指纹，未被美领馆行政审核过，且未被拒签过，申请人最近一次美国签证的签发地是中国大陆，以前获发的任何签证在注释栏内未印有“clearance received”，符合以上条件，您则无需前往领馆面试，可以通过中信银行的签证“代传递”程序申请签证。<br />4、领馆给予的递交材料时间我司无法干涉，建议您尽早申请签证以免影响您出行。', NULL, 'Files/pic/17/7/636517216410356720.jpg', NULL, '1610000002', '管理员', '2012-09-06 11:29:03.000000', '1610000002', '管理员', '2012-09-06 13:14:31.000000', NULL, '王婷', '2013-08-29 20:19:48.000000', '/1/50/', 1, '/1/50/', 48, 15, 0, 1200.0000, '1611000001');
INSERT INTO `visa_information` VALUES (12, 'V20011', '1801000004', 2, '奥地利团队签证', 1, 2, 3, 1, 2, '奥地利', '/683/', '2', 0.0000, 0.0000, '送进领馆后约10个工作日', '上海市、江苏省、浙江省、安徽省 （如在此领区工作或学习者，还需提供暂住证复印件，暂住证上必须显示已经有超过六个月或以上的居住历史。）', '按实际行程日期', '按行程实际天数', '1', 1, ' ', NULL, 'Files/pic/24/13/636517255085878831.jpg', NULL, '1610000002', '管理员', '2012-09-06 17:47:21.000000', '1610000002', '管理员', '2012-09-20 11:23:36.000000', '1610000002', '华文义', '2012-09-20 11:23:46.000000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (13, 'V10012', '1812000014', 1, '日本个人旅游签证', 1, 2, 3, 1, 1, '日本', '/8/', '2', 975.0000, 0.0000, '上海收齐材料后所需工作日10个', '上海、浙江、江苏、安徽、江西签发的护照（包含电子普通护照）并在以上五地工作生活或学习。其他地区签发或国外换发的护照申请人如在以上五地工作生活或学习，需提供已有六个月记录的有效暂住证或居住证复印件。', '15天或30天（以领馆签发为准）', '30天（以领馆签发为准）', '单次', 1, '1.如果您的政审不通过，我司可能会视具体材料情况要求您增补材料或者担保金<br />2.请您在回国后2个工作日内将在日本航空公司柜台盖章后的归国报告书邮寄我司办理销签,否则将影响到您今后其他签证正常办理。<br />3.关于全程酒店预订记录和全程往返交通（机票、船票、火车票等）预订记录，领馆要求申请签证时必须提供在代理旅行社（携程）预订的相关记录且保证信息的真实和准确，如发现您提供虚假信息，您申请的签证将会被领馆拒签或终止。如是申请冲绳多次往返签证，您在行程中访问冲绳、北海道等城市请务必提供相关交通信息。<br />4.如您在出行之前出行时间、行程、机票、酒店信息有变更，请及时联系我司重新提供相关变更信息，以免影响您正常出行。', NULL, 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-09-07 20:22:04.400000', '1610000002', '管理员', '2012-09-07 21:02:11.113000', '1610000002', '夏江', '2012-09-07 21:02:20.147000', '/22/,/14/,/28/,/2/,/15/', 1, '/1/50/', 48, 2, NULL, 650.0000, '1611000001');
INSERT INTO `visa_information` VALUES (14, 'V10013', '1812000014', 1, '越南个人签证', 1, 2, 3, 1, 1, '日本', '/8/', '2', 720.0000, 0.0000, '上海收齐材料后所需工作日5个，异地收齐材料后所需工作日9个。', '中国大陆因私护照（包含电子普通护照）。', '最大30天（根据行程，以领馆签发为准）', '最大30天（根据行程，以领馆签发为准）', '单次', 0, '<dt>预订限制</dt><dt>1、越南签证的生效日期即是旅客所填写的计划入境日期，如提前离开中国边境，边防警察将不会放行。</dt><dt>2、申请人必须在签证有效期内往返。若申请人延期逗留，越南边防有可能在申请人的护照上登记不良出入境记录。 </dt>', NULL, 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-09-10 09:46:47.000000', '1610000002', '管理员', '2012-09-10 09:51:13.000000', NULL, '侯竞燕', '2012-09-10 09:51:28.000000', NULL, 1, '/1/50/', 48, 3, -1, 480.0000, '1611000001');
INSERT INTO `visa_information` VALUES (15, 'V10014', '1812000014', 1, '老挝个人签证', 1, 2, 5, 1, 1, '老挝', '/19/', '2', 495.0000, 0.0000, '7个工作日', '中国大陆各地居民因私护照。', '60天', '30天（具体可停留天数以当地移民局签发为准）。', '单次', 0, '<dt>重要条款</dt><dt>1、申请同一国家签证在半年内有拒签记录的客人不予办理。</dt><dt>2、请按照实际出发日期下订单，如由于提供错误的出发时间导致行程受阻责任须自负。</dt>', '如遇领馆休息，工作日顺延', 'Files/pic/19/8/636517219396460471.jpg', NULL, '1610000002', '管理员', '2012-09-10 10:21:28.000000', '1610000002', '管理员', '2012-09-10 10:24:04.000000', '1610000002', '陈晓珏', '2014-05-16 19:22:27.000000', '/1/50/', 1, '/1/50/', 48, 3, 0, 350.0000, '1611000001');
INSERT INTO `visa_information` VALUES (16, 'V10015', '1801000004', 1, '加拿大个人旅游签证', 1, 2, 5, 1, 4, '加拿大', '/18/', '2', 1400.0000, 0.0000, '送签后15-20个工作日', '目前无领区限制', '以领馆签发为准', '以领馆签发为准', '单次或多次', 0, '办理时长指领馆正常受理工作日（领馆节假日随各国情况有所差异）。\r\n不接受18周岁以下（包括18周岁）未成年人单独出行的预订；18周岁以下未成年人必须至少与父/母一方同行。', NULL, 'Files/pic/18/6/636517195368854538.jpg', NULL, '1610000002', '管理员', '2012-09-12 17:21:03.000000', '1610000002', '管理员', '2012-09-13 17:51:15.000000', NULL, '王婷', '2013-08-29 19:53:55.000000', '/1/50/', 1, '/1/50/', 48, 30, 0, 1100.0000, '1611000001');
INSERT INTO `visa_information` VALUES (17, 'V20016', '1801000004', 2, '法国团队签证', 1, 3, 5, 1, 2, '法国', '/26/', '2', 0.0000, 0.0000, '送签后10个工作日', '上海市、江苏省、浙江省、安徽省\r\n注：有职称证书、职业资格证的请提供证书复印件，例如：教师证、医师证、记者证、会计证、律师证等。', '按实际行程时间', '按实际行程时间', '1', 1, ' ', NULL, 'Files/pic/26/14/636517257721331386.jpg', NULL, '1610000002', '管理员', '2012-09-20 11:34:11.000000', '1610000002', '管理员', '2012-10-09 11:41:29.000000', '1610000002', '程钰', '2014-07-15 13:29:31.000000', NULL, 1, '/1/50/', 0, NULL, -1, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (18, 'V20017', '1801000004', 2, '英国团队签证', 1, 1, 5, 1, 2, '英国', '/25/', '2', 0.0000, 0.0000, '送签后15个工作日', '上海市、江苏省、浙江省、安徽省 （如在此领区工作或学习者，还需提供暂住证复印件）', '按实际行程时间', '按实际行程时间', '1', 1, ' ', NULL, 'Files/pic/25/4/636516980079741244.jpg', NULL, '1610000002', '管理员', '2012-09-27 15:49:16.000000', '1610000002', '管理员', '2012-09-28 14:33:16.000000', '1610000002', '管理员', '2018-01-17 10:45:59.000000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (19, 'V20018', '1801000004', 2, '意大利团队签证', 1, 2, 5, 1, 2, '意大利', '/24/', '2', 0.0000, 0.0000, '送签后10-15个工作日 ', '上海市、江苏省、浙江省、安徽省 （如在此领区工作或学习者，还需提供暂住证复印件，暂住证上必须显示已经有超过六个月或以上的居住历史！） \r\n温馨提示：意大利使馆现在严查ADS签证申请表的客人签字。因此， 在此特别提醒大家，在收取资料时， 请客人提供亲笔签名的申请表，未成年人需有其父母一方签名。\r\n注： 签字页必须为原件，需要签名的地方一共有两处： 签证表的第37项以及最后一页处。尤其要注意，当未成年人与父母其中一方同去时，签证表上未成年人父母一方的签名一定要与委托书的签名一致。', '按实际行程时间', '按实际行程时间', '1', 1, ' ', NULL, 'Files/pic/24/13/636517255085878831.jpg', NULL, '1610000002', '管理员', '2012-09-28 14:09:52.000000', '1610000002', '管理员', '2012-09-28 15:52:49.000000', '1610000002', '管理员', '2018-01-17 10:49:33.000000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (20, 'V10019', '1801000004', 2, '美国团队签证', 1, 1, 5, 1, 4, '美国', '/17/', '2', 0.0000, 0.0000, '面试后需2-4个工作日', '上海、浙江、江苏、安徽签发的护照并在以上四地工作生活或学习6个月以上。其他地区签发的护照申请人如在以上四地工作生活或学习6个月以上，请在面谈时携带以上四地已有六个月记录的有效暂住证或居住证原件。', '十年（具体以领馆签发为准）', '以边防敲章为准', '多次', 0, ' ', NULL, 'Files/pic/17/7/636517216410356720.jpg', NULL, '1610000002', '管理员', '2012-09-28 14:36:01.000000', '1610000002', '管理员', '2012-09-28 14:55:45.000000', '1610000002', '管理员', '2018-01-17 10:56:45.000000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (21, 'V10020', '1801000004', 2, ' 加拿大团队签证', 1, 2, 3, 1, 4, '加拿大', '/18/', '2', 0.0000, 0.0000, '30个工作日', '护照签发地为上海、浙江、江苏、安徽。如护照签发地不在以上四地内，其他地区申请者需在以上四地工作、生活或学习并提供已有六个月记录的有效暂住证或居住证原件。', '以领馆签发为准', '以领馆签发为准', '以领馆签发为准，一般为单次', 0, ' ', NULL, 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-09-28 14:40:15.000000', '1610000002', '管理员', '2012-09-28 14:55:43.000000', '1610000002', '袁嘉婧', '2012-09-28 14:56:29.000000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (22, 'V20021', '1801000004', 2, '南非团队旅游签证', 1, 2, 3, 1, 3, '南非', '/20/', '2', 0.0000, 0.0000, '10', '山东省、浙江省、江苏省、安徽省、福建省、广东省及上海市.', '3', '15', '1', 0, ' ', NULL, 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-09-28 16:00:40.000000', '1610000002', '管理员', '2012-09-28 16:36:31.000000', '1610000002', '王妹', '2012-09-28 16:37:02.000000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (23, 'V20022', '1801000004', 2, '瑞士团队签证', 1, 2, 5, 1, 2, '瑞士', '/23/', '2', 0.0000, 0.0000, '送签后10个工作日', '上海市、江苏省、浙江省、安徽省 （如在此领区工作或学习者，还需提供暂住证复印件）', '按实际行程时间', '按实际行程时间', '1', 1, ' ', NULL, 'Files/pic/23/12/636517252606697866.gif', NULL, '1610000002', '管理员', '2012-09-28 16:16:21.000000', '1610000002', '管理员', '2012-09-28 16:35:46.000000', '1610000002', '管理员', '2018-01-17 10:49:08.000000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (24, 'V20023', '1801000004', 2, '希腊团队签证', 1, 2, 5, 1, 2, '希腊', '/38/', '2', 0.0000, 0.0000, '送签后15个工作日', '上海市、江苏省、浙江省、安徽省、江西省、山东省 （如在此领区工作或学习者，还需提供暂住证复印件，暂住证上必须显示已经有超过三个月或以上的居住历史！） ', '按实际行程时间', '按实际行程时间', '1', 1, ' ', NULL, 'Files/pic/38/25/636517269993470449.jpg', NULL, '1610000002', '管理员', '2012-09-28 16:44:13.000000', '1610000002', '管理员', '2012-09-28 17:04:52.000000', '1610000002', '程钰', '2014-07-15 13:28:33.000000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (25, 'V20024', '1801000004', 2, '西班牙团队签证', 1, 2, 5, 1, 2, '西班牙', '/37/', '2', 0.0000, 0.0000, '送签后15个工作日', '申请人户口必须属于上海市、江苏省、浙江省、安徽省，江西 \r\n请注意：西班牙领事馆对白板护照及无大国出入境记录的申请者审核较严格，尤其是浙江籍的人士，另外加上个人税单和个人的四金证明。', '按实际行程时间', '按实际行程时间', '1', 1, ' ', NULL, 'Files/pic/37/24/636517268915852862.jpg', NULL, '1610000002', '管理员', '2012-09-28 17:17:20.000000', '1610000002', '管理员', '2012-09-28 17:35:41.000000', '1610000002', '程钰', '2014-07-15 13:28:22.000000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (26, 'V20025', '1801000004', 2, '埃及团队旅游签证', 1, 2, 3, 1, 3, '埃及', '/685/', '2', 0.0000, 0.0000, '9个工作日', '江苏省、浙江省、安徽省及上海市', '90天', '30天', '1', 0, ' ', NULL, 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-09-28 17:23:02.000000', '1610000002', '管理员', '2012-10-09 10:52:00.000000', '1610000002', '王妹', '2012-10-09 10:52:07.000000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (27, 'V10026', '1801000004', 1, '南非个人旅游签证', 1, 3, 5, 1, 3, '南非', '/20/', '2', 1300.0000, 0.0000, '送签后10-15个工作日', '护照签发地为上海、浙江、江苏、安徽、福建、广东，山东。如护照签发地不在以上七地内，其他地区申请者需在以上七地工作、生活或学习并提供已有六个月记录的有效暂住证或居住证原件。\r\n', '3个月', '根据行程由领馆决定', '单次', 0, '<p>1、请务必确保您的护照在归国后仍有半年以上有效期，并且至少留有两页空白签证页。<br />2、以上签证价格、所需材料，若领馆临时变更，以领馆变更为准。<br />3、办理时长指领馆正常受理工作日（领馆节假日随各国情况有所差异）。往返快递时间另计。<br /></p>', '<p>请按照实际出发日期下订单，如由于提供错误的出发时间导致行程受阻责任须自负。<br /></p>', 'Files/pic/20/9/636517222612597276.jpg', NULL, '1610000002', '管理员', '2012-09-28 17:25:02.000000', '1610000002', '管理员', '2012-10-08 16:14:56.000000', NULL, '江坚强', '2014-12-11 16:24:50.000000', '/1/50/', 1, '/1/50/', 48, 15, -1, 1000.0000, '1611000001');
INSERT INTO `visa_information` VALUES (28, 'V20027', '1801000004', 2, '德国团队签证', 1, 2, 5, 1, 2, '德国', '/22/', '2', 0.0000, 0.0000, '送签后30个工作日', '上海市、江苏省、浙江省、安徽省 （如在此领区工作或学习者，还需提供暂住证复印件，暂住证上必须显示已经有超过六个月或以上的居住历史！）', '按实际行程时间', '按实际行程时间', '1', 1, ' ', NULL, 'Files/pic/22/11/636517251539391933.jpg', NULL, '1610000002', '管理员', '2012-09-29 09:12:09.000000', '1610000002', '管理员', '2012-09-29 11:03:40.000000', '1610000002', '管理员', '2018-01-17 10:31:29.000000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
