INSERT INTO `visa_information` VALUES (30, 'V20029', '1801000004', 2, '新西兰团队签证', 1, 2, 5, 1, 5, '新西兰', '/28/', '2', 0.0000, 0.0000, '送签后5个工作日', '护照签发地在上海、浙江、江苏、安徽、江西、福建。如护照签发地不在以上六地内，需提供六地内已有六个月记录的的有效暂住证或居住证原件。我司不接收超过80周岁以上老人办理。', '按实际行程时间', '按实际行程时间', '1', 1, ' ', NULL, 'Files/pic/28/16/636517258997510675.jpg', NULL, '1610000002', '管理员', '2012-09-29 11:34:00.000000', '1610000002', '管理员', '2012-09-29 14:36:59.000000', '1610000002', '管理员', '2018-01-17 10:52:16.457000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
