INSERT INTO `visa_information` VALUES (35, 'V20034', '1812000014', 2, '以色列团队旅游签证', 1, 2, 3, 1, 3, '以色列', '/688/', '1', 0.0000, 0.0000, '15个工作日', '全国各地', '60', '14', '1次', 0, ' ', NULL, 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-10-08 16:18:18.000000', '1610000002', '管理员', '2012-10-10 16:37:20.000000', '1610000002', '王妹', '2012-10-10 16:37:23.000000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (36, 'V10035', '1812000014', 1, '阿联酋/迪拜旅游电子签证', 1, 2, 5, 1, 1, '阿联酋', '/21/', '2', 1200.0000, 0.0000, '7个工作日', '全国各地', '60天', '30天', '1次', 1, '<p>1、请务必确保您的护照在归国后仍有半年以上有效期，并且至少留有两页空白签证页。<br />2、以上签证价格、所需材料，若领馆临时变更，以领馆变更为准。<br />3、办理时长指领馆正常受理工作日（领馆节假日随各国情况有所差异）。</p>', '<p>请按照实际出发日期下订单，如由于提供错误的出发时间导致行程受阻责任须自负。<br /></p>', 'Files/pic/21/10/636517226128426898.gif', NULL, '1610000002', '管理员', '2012-10-08 16:39:26.000000', '1610000002', '管理员', '2012-10-08 16:58:18.000000', NULL, '赵淑芸', '2014-05-16 20:51:22.000000', '/1/50/', 1, '/1/50/', 48, 3, 1, 999.0000, '1611000001');
INSERT INTO `visa_information` VALUES (37, 'V10036', '1812000014', 1, '肯尼亚旅游签证', 1, 2, 3, 1, 3, '肯尼亚', '/21/', '1', 1664.0000, 0.0000, '6-10个工作日', '全国各地', '90天', '30天', '1次', 0, '<p>1、请务必确保您的护照在归国后仍有半年以上有效期，并且至少留有两页空白签证页。<br />2、以上签证价格、所需材料，若领馆临时变更，以领馆变更为准。<br />3、办理时长指领馆正常受理工作日（领馆节假日随各国情况有所差异）。</p>', '<p>请按照实际出发日期下订单，如由于提供错误的出发时间导致行程受阻责任须自负。<br /></p>', 'Files/pic/21/10/636517226128426898.gif', NULL, '1610000002', '管理员', '2012-10-08 17:22:34.000000', '1610000002', '管理员', '2012-10-09 09:59:09.000000', NULL, '王妹', '2012-10-09 09:59:17.000000', NULL, 1, '/1/50/', 48, 15, NULL, 1109.0000, '1611000001');
INSERT INTO `visa_information` VALUES (38, 'V20037', '1801000004', 2, '复件（1） 意大利团队签证', 1, 3, 1, 0, 2, '日本', '/8/', '2', 0.0000, 0.0000, '送签后10-15个工作日 ', '上海市、江苏省、浙江省、安徽省 （如在此领区工作或学习者，还需提供暂住证复印件，暂住证上必须显示已经有超过六个月或以上的居住历史！） \r\n温馨提示：意大利使馆现在严查ADS签证申请表的客人签字。因此， 在此特别提醒大家，在收取资料时， 请客人提供亲笔签名的申请表，未成年人需有其父母一方签名。\r\n注： 签字页必须为原件，需要签名的地方一共有两处： 签证表的第37项以及最后一页处。尤其要注意，当未成年人与父母其中一方同去时，签证表上未成年人父母一方的签名一定要与委托书的签名一致。', '按实际行程时间', '按实际行程时间', '1', 1, ' ', NULL, 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-10-09 10:57:17.830000', '1610000002', '管理员', NULL, NULL, NULL, NULL, NULL, 1, '/1/50/', 0, NULL, NULL, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (39, 'V10038', '1812000014', 1, '文莱个人旅游签证', 1, 2, 3, 1, 1, '文莱', '/689/', '1', 1650.0000, 0.0000, '24', '全国签发的护照。', '以领馆签发为准', '以领馆签发为准', '以领馆签发为准', 0, '<dt>预订限制：领馆可能会临时通知您增补材料，请您积极配合。</dt><p class=\"red\">出行警示及说明：请按照实际出发日期下订单，如由于提供错误的出发时间导致行程受阻责任须自负。</p>', NULL, 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-10-09 15:05:27.000000', '1610000002', '管理员', '2012-10-15 16:04:06.000000', NULL, '黄丽芸', '2012-10-15 16:07:33.000000', NULL, 1, '/1/50/', 48, 1, NULL, 1100.0000, '1611000001');
INSERT INTO `visa_information` VALUES (40, 'V20039', '1812000014', 2, '摩洛哥旅游签证', 1, 2, 3, 1, 3, '日本', '/8/', '-1', 0.0000, 0.0000, '10个工作日', '全国各地', '60', '15', '1次', 0, ' ', NULL, 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-10-11 09:48:50.657000', '1610000002', '管理员', '2012-10-11 09:59:51.717000', '1610000002', '王妹', '2012-10-11 09:59:57.383000', NULL, 1, '/1/50/', 0, NULL, 0, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (41, 'V20040', '1801000004', 1, '德国个人旅游签证', 1, 2, 5, 1, 2, '德国', '/22/', '2', 1300.0000, 0.0000, '送签后15个工作日', '上海市、江苏省、浙江省、安徽省 （如非本领区人士需提供6个月以上的暂住证复印件）', '按实际行程时间', '按实际行程时间', '单次', 0, '<ul style=\"margin: 0px; padding: 0px; font-family: Arial, Simsun, sans-serif; line-height: 24px; \"><li style=\"margin: 0px; padding: 0px; list-style: none; \">1、价格不含签证费及保险费用；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">2、请务必确保您的护照在归国后仍有半年以上有效期，并且至少留有两页空白签证页；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">3、签证所需材料，若领馆临时变更，以领馆变更为准；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">4、办理时长指领馆正常受理工作日（领馆节假日随各国情况有所差异），往返快递时间另计；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">5、受理范围：护照签发地为上海、浙江、江苏、安徽。如护照签发地不在上述地区内，其他地区申请者需在上述地区内工作、生活或学习并提供已有六个月记录的有效暂住证或居住证原件。</li></ul> ', NULL, 'Files/pic/22/11/636517251539391933.jpg', NULL, '1610000002', '管理员', '2012-10-11 14:27:09.000000', '1610000002', '管理员', '2012-10-30 17:21:26.000000', NULL, '邵梦琛', '2013-11-06 15:25:31.000000', '/1/50/', 1, '/1/50/', 48, 30, -1, 950.0000, '1611000001');
INSERT INTO `visa_information` VALUES (42, 'V20041', '1801000004', 2, '复件（1） 西班牙团队签证', 1, 3, 1, 0, 2, '日本', '/8/', '2', 0.0000, 0.0000, '送签后15个工作日', '申请人户口必须属于上海市、江苏省、浙江省、安徽省，江西 \r\n请注意：西班牙领事馆对白板护照及无大国出入境记录的申请者审核较严格，尤其是浙江籍的人士，另外加上个人税单和个人的四金证明。', '按实际行程时间', '按实际行程时间', '1', 1, ' ', NULL, 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-10-11 14:27:20.473000', '1610000002', '管理员', NULL, NULL, NULL, NULL, NULL, 1, '/1/50/', 0, NULL, NULL, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (43, 'V20042', '1801000004', 2, '复件（1） 希腊团队签证', 1, 3, 1, 0, 2, '日本', '/8/', '2', 0.0000, 0.0000, '送签后15个工作日', '上海市、江苏省、浙江省、安徽省、江西省、山东省 （如在此领区工作或学习者，还需提供暂住证复印件，暂住证上必须显示已经有超过三个月或以上的居住历史！） ', '按实际行程时间', '按实际行程时间', '1', 1, ' ', NULL, 'Files/pic/88/20037/634708727578452500.jpg', NULL, '1610000002', '管理员', '2012-10-11 14:27:28.690000', '1610000002', '管理员', NULL, NULL, NULL, NULL, NULL, 1, '/1/50/', 0, NULL, NULL, 0.0000, '1611000001');
INSERT INTO `visa_information` VALUES (44, 'V20043', '1801000004', 1, '瑞士个人旅游签证', 1, 2, 5, 1, 2, '瑞士', '/23/', '2', 1300.0000, 0.0000, '送签后15个工作日', '上海市、江苏省、浙江省、安徽省 （如非本领区人士需提供6个月以上的暂住证复印件） ', '按实际行程时间', '按实际行程时间', '单次', 0, '<ul style=\"margin: 0px; padding: 0px; font-family: Arial, Simsun, sans-serif; line-height: 24px; \"><li style=\"margin: 0px; padding: 0px; list-style: none; \">1、价格不含签证费及保险费用；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">2、请务必确保您的护照在归国后仍有半年以上有效期，并且至少留有两页空白签证页；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">3、签证所需材料，若领馆临时变更，以领馆变更为准；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">4、办理时长指领馆正常受理工作日（领馆节假日随各国情况有所差异），往返快递时间另计；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">5、受理范围：护照签发地为上海、浙江、江苏、安徽。如护照签发地不在上述地区内，其他地区申请者需在上述地区内工作、生活或学习并提供已有六个月记录的有效暂住证或居住证原件。</li></ul> ', NULL, 'Files/pic/23/12/636517252606697866.gif', NULL, '1610000002', '管理员', '2012-10-11 14:27:36.000000', '1610000002', '管理员', '2012-10-30 17:18:39.000000', NULL, '程钰', '2013-11-06 13:46:47.000000', '/1/50/', 1, '/1/50/', 48, 30, 0, 950.0000, '1611000001');
INSERT INTO `visa_information` VALUES (45, 'V20044', '1801000004', 1, '意大利个人旅游签证', 1, 1, 5, 1, 2, '意大利', '/24/', '2', 1300.0000, 0.0000, '送签后10-15个工作日 ', '上海市、江苏省、浙江省、安徽省 （如非本领区人士需提供6个月以上的暂住证复印件） \r\n', '按实际行程时间', '按实际行程时间', '单次', 0, '<ul style=\"margin: 0px; padding: 0px; font-family: Arial, Simsun, sans-serif; line-height: 24px; \"><li style=\"margin: 0px; padding: 0px; list-style: none; \">1、价格不含保险费用；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">2、请务必确保您的护照在归国后仍有半年以上有效期，并且至少留有两页空白签证页；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">3、签证所需材料，若领馆临时变更，以领馆变更为准；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">4、办理时长指领馆正常受理工作日（领馆节假日随各国情况有所差异），往返快递时间另计；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">5、受理范围：护照签发地为上海、浙江、江苏、安徽。如护照签发地不在上述地区内，其他地区申请者需在上述地区内工作、生活或学习并提供已有六个月记录的有效暂住证或居住证原件。</li></ul> ', '进入6-9月请提前2-3个月申请', 'Files/pic/24/13/636517255085878831.jpg', NULL, '1610000002', '管理员', '2012-10-11 14:27:53.000000', '1610000002', '管理员', '2012-10-30 17:16:12.000000', NULL, '王婷', '2013-08-29 20:48:26.000000', '/1/50/', 1, '/1/50/', 48, 30, 0, 950.0000, '1611000001');
INSERT INTO `visa_information` VALUES (46, 'V20045', '1801000004', 1, '英国个人旅游签证', 1, 1, 5, 1, 2, '英国', '/25/', '2', 1400.0000, 0.0000, '送签后15个工作日', '上海市、江苏省、浙江省、安徽省 （如在此领区工作或学习者，还需提供暂住证复印件）', '按实际行程时间', '按实际行程时间', '单次', 0, '<ul style=\"margin: 0px; padding: 0px; font-family: Arial, Simsun, sans-serif; line-height: 24px; \"><li style=\"margin: 0px; padding: 0px; list-style: none; \">1、价格不含签证费及保险费用；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">2、请务必确保您的护照在归国后仍有半年以上有效期，并且至少留有两页空白签证页；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">3、签证所需材料，若领馆临时变更，以领馆变更为准；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">4、办理时长指领馆正常受理工作日（领馆节假日随各国情况有所差异），往返快递时间另计；</li><li style=\"margin: 0px; padding: 0px; list-style: none; \">5、受理范围：护照签发地为上海、浙江、江苏、安徽。如护照签发地不在上述地区内，其他地区申请者需在上述地区内工作、生活或学习并提供已有六个月记录的有效暂住证或居住证原件。</li></ul> ', NULL, 'Files/pic/25/4/636516980079741244.jpg', NULL, '1610000002', '管理员', '2012-10-11 14:28:01.000000', '1610000002', '管理员', '2012-10-30 17:12:07.000000', NULL, '王婷', '2013-09-05 22:00:46.000000', '/1/50/', 1, '/1/50/', 48, 45, 0, 1150.0000, '1611000001');
INSERT INTO `visa_information` VALUES (47, 'V20046', '1801000004', 1, '法国个人旅游签证', 1, 2, 5, 1, 2, '法国', '/26/', '2', 1299.0000, 0.0000, '送签后3-5个工作日', '无领区限制', '按实际行程时间', '按实际行程时间给予签证', '单次或多次', 0, '<ul style=\"margin: 0px; padding: 0px; font-family: Arial, Simsun, sans-serif; line-height: 24px; \"><li style=\"margin: 0px; padding: 0px; list-style: none; \">1、价格不含保险费用；<br />2、请务必确保您的护照在归国后仍有半年以上有效期，并且至少留有两页空白签证页；<br />3、签证所需材料，若领馆临时变更，以领馆变更为准；<br />4、办理时长指领馆正常受理工作日（领馆节假日随各国情况有所差异），往返快递时间另计；<br />5、受理范围：无领区限制', NULL, 'Files/pic/26/14/636517257721331386.jpg', NULL, '1610000002', '管理员', '2012-10-11 14:28:10.000000', '1610000002', '管理员', '2012-10-19 13:39:20.000000', '1610000002', '管理员', '2018-02-06 12:12:06.000000', '/22/,/28/', 1, '/1/50/', 48, 15, 0, 899.0000, '1611000001');
INSERT INTO `visa_information` VALUES (48, 'V20047', '1801000004', 1, '澳大利亚个人旅游签证', 1, 2, 5, 1, 5, '澳大利亚', '/27/', '2', 1300.0000, 0.0000, '送签后10-15个工作日起', '护照签发地在北京、黑龙江、吉林、辽宁、天津、山东、河北、内蒙古、山西，河南\r\n上海、江苏、浙江，安徽。\r\n如护照签发地不在以上地区的，提供有效的暂住证或居住证复印件，并提供在以上地区公司开具在职证明方可办理。', '一年', '三个月', '1', 0, '1、签证价格含单次入境签证工本费，不含保险费用；&nbsp;<br />2、签证价格、所需材料，若领馆临时变更，以领馆变更为准；&nbsp;<br />3、请务必确保您的护照在归国后仍有半年以上有效期，并且至少留有两页空白签证页；&nbsp;<br />4、办理时长指领馆正常受理工作日（领馆节假日随各国情况有所差异），往返快递时间另计；&nbsp;<br />5、 领馆会根据客人的具体材料，提出补充材料和面试的要求；6、超过75周岁的客人需要体检和购买保险，体检由领馆另行通知。预计在澳停留时间超过3个月的，也要体检，由领馆另行通知。', '如要申请澳洲和新西兰两个签证的，需要预留两个签证的受理时间。', 'Files/pic/27/15/636517258386768302.jpg', NULL, '1610000002', '管理员', '2012-10-15 10:19:36.000000', '1610000002', '管理员', '2012-10-17 14:46:48.000000', NULL, '王婷', '2013-09-05 21:47:59.000000', NULL, 1, '/1/50/', 24, 9, 0, 1100.0000, '1611000001');
INSERT INTO `visa_information` VALUES (49, 'V20048', '1801000004', 1, '新西兰个人旅游签证', 1, 2, 5, 1, 5, '新西兰', '/28/', '2', 1300.0000, 0.0000, '送签后25个自然日左右', '护照签发地在上海、浙江、江苏、安徽、江西、福建、湖南和湖北的客人可以在我司办理。如签发地不在以上地区的，需提供在以上地区的暂住证复印件或居住证复印件，并提供以上地区公司出具的在职证明方可办理。\r\n', '签发日起3个月', '不超过6个月', '1', 0, '1、签证价格含单次入境签证工本费，不含保险费用；&nbsp;<br />2、签证价格、所需材料，若领馆临时变更，以领馆变更为准；&nbsp;<br />3、请务必确保您的护照在归国后仍有半年以上有效期，并且至少留有两页空白签证页；&nbsp;<br />4、办理时长指领馆正常受理工作日（领馆节假日随各国情况有所差异），往返快递时间另计；&nbsp;<br />5、领馆会根据客人的具体材料，提出补充材料和面试的要求；6，超过80周岁以上老人，会由领馆另行通知体检。如被抽到体检，签证受理周期将视体检情况而定。', '如要申请澳洲和新西兰两个签证的，需要预留两个签证的受理时间。', 'Files/pic/28/16/636517258997510675.jpg', NULL, '1610000002', '管理员', '2012-10-15 10:19:48.000000', '1610000002', '管理员', '2012-10-17 14:44:08.000000', NULL, '邵梦琛', '2013-11-05 16:10:38.000000', '/1/50/', 1, '/1/50/', 24, 5, 0, 1250.0000, '1611000001');
INSERT INTO `visa_information` VALUES (50, 'V10049', '1812000014', 1, '印度个人签证', 1, 2, 5, 1, 1, '印度', '/29/', '2', 900.0000, 0.0000, '7个工作日', '全国', '三个月（有效期具体的起至日期以领馆签发为准）', '30（不能超过有效期回来）', '单次', 1, '护照、51*51的白底彩照、申请表、英文在职证明、一万元冻结四个月的存款证明原件', NULL, 'Files/pic/29/17/636517262026152786.png', NULL, '1610000002', '管理员', '2012-10-15 14:43:54.000000', '1610000002', '管理员', '2012-10-15 14:59:03.000000', NULL, '唐翔', '2014-05-16 20:46:17.000000', NULL, 1, '/1/50/', 48, 1, -1, 750.0000, '1611000001');
INSERT INTO `visa_information` VALUES (51, 'V10050', '1812000014', 1, '斯里兰卡个人签证', 1, 2, 3, 1, 1, '斯里兰卡', '/41/', '2', 450.0000, 0.0000, '上海收齐材料后所需工作日5个，异地收齐材料后所需工作日9个', '上海、江苏、浙江、安徽、福建签发的护照，以上五地以外签发护照的申请人需提交以上五地的暂住证复印件/居住证复印件/公司在职证明。', '以领馆签发为准', '以领馆签发为准', '以领馆签发为准', 1, '<ul style=\"PADDING-BOTTOM: 0px; WIDOWS: 2; TEXT-TRANSFORM: none; BACKGROUND-COLOR: rgb(255,255,255); LIST-STYLE-TYPE: none; TEXT-INDENT: 0px; MARGIN: 0px; PADDING-LEFT: 22px; PADDING-RIGHT: 0px; FONT: 12px/18px Simsun, sans-serif; WHITE-SPACE: normal; ORPHANS: 2; LETTER-SPACING: normal; COLOR: rgb(77,77,77); WORD-SPACING: 0px; PADDING-TOP: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px\" class=\"visa_detail_tent\"><li style=\"PADDING-BOTTOM: 0px; LINE-HEIGHT: 22px; LIST-STYLE-TYPE: decimal; MARGIN: 0px; PADDING-LEFT: 0px; PADDING-RIGHT: 0px; PADDING-TOP: 0px\">领馆可能会临时通知您增补材料，请您积极配合。</li><li style=\"PADDING-BOTTOM: 0px; LINE-HEIGHT: 22px; LIST-STYLE-TYPE: decimal; MARGIN: 0px; PADDING-LEFT: 0px; PADDING-RIGHT: 0px; PADDING-TOP: 0px\">签证材料制作完成即产生500元服务费，如取消此费用无法退还</li></ul>', NULL, 'Files/pic/41/28/636517271928551177.jpg', NULL, '1610000002', '管理员', '2012-10-15 15:29:17.000000', '1610000002', '管理员', '2012-10-15 15:40:35.000000', '1610000002', '梁珺', '2012-10-15 15:40:40.000000', NULL, 1, '/1/50/', 48, 1, NULL, 300.0000, '1611000001');
INSERT INTO `visa_information` VALUES (52, 'V10051', '1812000014', 1, '尼泊尔个人签证', 1, 2, 5, 1, 1, '尼泊尔', '/30/', '2', 700.0000, 0.0000, '7天', '全国收客，中国大陆因私护照（包含电子普通护照）', '6个月（具体的起止日期以领馆签发为准）', '30天', '多次', 0, '具体见所需材料', '如遇领馆休息，工作日顺延', 'Files/pic/30/19/636517264892470462.jpg', NULL, '1610000002', '管理员', '2012-10-15 15:52:11.000000', '1610000002', '管理员', '2012-10-15 15:59:15.000000', '1610000002', '赵淑芸', '2014-05-16 21:09:14.000000', NULL, 1, '/1/50/', 48, 1, 1, 600.0000, '1611000001');
INSERT INTO `visa_information` VALUES (53, 'V10052', '1812000014', 1, '菲律宾个签加急', 1, 2, 3, 1, 1, '菲律宾', '/5/', '2', 1020.0000, 0.0000, '4个工作日', '中国大陆因私护照', '3个月，以领馆实际签出的结果为准', '14天', '单次', 0, '<p>1、3张2寸白底照片。</p><p>2、护照（有效期6个月以上的中国护照，护照最后一页签名）。</p><p>3、在职证明。</p><p>4、个人申请表。</p>', '<div class=\"align_l\">1、价格含签证工本费及服务费，不含保险费。</div><div class=\"align_l\">2、上海市户口的申请人在市区级公证处均可以办理公证书。部分公证处联系方式以供参考：静安区公证处（电话：62671801、32170441）、杨浦区公证处（电话：65899528）、浦东新区公证处（电话：58396060、58395050）。请在去公证处前先准备齐全资料，可以缩短公证书的办理时间。</div><div class=\"align_l\">◆办理亲属关系公证书所需材料：父母和未成年子女的身份证及户口本原件；结婚证书原件；未成年子女出生证或独生子女证原件。</div>', 'Files/pic/5/22/636517267272244462.jpg', NULL, '1610000002', '管理员', '2013-01-14 10:12:37.000000', '1610000002', '管理员', '2013-01-14 10:45:00.000000', NULL, '程臻', '2013-01-14 10:45:15.000000', NULL, 1, '/1/50/', 48, 4, 0, 680.0000, '1611000001');
