INSERT INTO `visa_information` VALUES (58, 'V10057', '1812000014', 1, '泰国签证', 1, 2, 5, 1, 1, '泰国', '/31/', '2', 420.0000, 0.0000, '7个工作日', '上海领区范围：上海、江苏、浙江、安徽\r\n（上述领区以外护照提供暂住证原件，如遇领馆休假，工作日顺延不含快递时间）', '3个月', '30天', '1', 0, '半年以上有效护照原件+近6个月彩色白底2寸照片2张\r\n', NULL, 'Files/pic/31/2/636516975073521831.jpg', NULL, '1610000002', '管理员', '2013-08-21 19:28:57.000000', '1610000002', '管理员', '2013-08-21 19:52:48.000000', NULL, '王婷', '2013-08-21 19:53:22.000000', NULL, 1, '/1/50/', 48, 1, 0, 280.0000, '1611000001');
INSERT INTO `visa_information` VALUES (59, 'V10058', '1812000014', 1, '马来西亚签证', 1, 2, 5, 1, 1, '马来西亚', '/32/', '2', 375.0000, 0.0000, '3个工作日', '全国受理，无领区限制，如遇领馆休假，工作日顺延，不含来回快递时间。', '3个月', '30天', '1', 0, '半年以上有效护照原件+2张近6个月白底2寸照片（18岁以下儿童必须父母陪同办理签证，提供出生证明复印件上面3个人的名字都要有或者户口本整本复印件，全国受理，无领区限制）\r\n', '半年以上有效护照原件+2张近6个月白底2寸照片（18岁以下儿童必须父母陪同办理签证，提供出生证明复印件或者户口本整本复印件，全国受理，无领区限制，如遇领馆休假，工作日顺延，不含来回快递时间）\r\n', 'Files/pic/32/18/636517263509774689.jpg', NULL, '1610000002', '管理员', '2013-08-22 18:35:36.000000', '1610000002', '管理员', '2013-08-22 19:02:32.000000', NULL, '王婷', '2013-08-22 19:02:58.000000', NULL, 1, '/1/50/', 48, 1, 1, 300.0000, '1611000001');
INSERT INTO `visa_information` VALUES (60, 'V10059', '1812000014', 1, '马来西亚签证（加急2天）', 1, 2, 6, 1, 1, '马来西亚', '/32/', '2', 600.0000, 0.0000, '2个工作日', '全国受理，无领区限制，如遇领馆休假，工作日顺延，不含来回快递时间。', '3个月', '30天', '1', 0, '半年以上有效护照原件+2张近6个月白底2寸照片（18岁以下儿童必须父母陪同办理签证，提供出生证明复印件或者户口本整本复印件，全国受理，无领区限制，如遇领馆休假，工作日顺延，不含来回快递时间）备注：马来西亚领馆对照片要求严格 ', '半年以上有效护照原件+2张近6个月白底2寸照片（18岁以下儿童必须父母陪同办理签证，提供出生证明复印件或者户口本整本复印件，全国受理，无领区限制，如遇领馆休假，工作日顺延，不含来回快递时间）备注：马来西亚领馆对照片要求严格 （每周五，每月底不做加急）', 'Files/pic/32/18/636517263509774689.jpg', NULL, '1610000002', '管理员', '2013-08-22 19:08:28.000000', '1610000002', '管理员', '2013-08-22 19:09:31.000000', NULL, '王婷', '2013-08-22 19:09:44.000000', NULL, 1, '/1/50/', 48, 1, 1, 400.0000, '1611000001');
INSERT INTO `visa_information` VALUES (61, 'V10060', '1812000014', 1, '越南签证', 1, 2, 5, 1, 1, '越南', '/33/', '2', 825.0000, 0.0000, '7个工作日', '全国受理，如遇领馆休假，工作日顺延，不含来回快递时间。', '30天', '30天', '1', 0, '半年以上有效护照原件+近6个月彩色白底2寸照片2张+准确的入境时间（全国受理）', '全国受理', 'Files/pic/33/3/636516976483802146.jpg', NULL, '1610000002', '管理员', '2013-08-22 19:21:32.000000', '1610000002', '管理员', '2013-08-22 19:22:23.000000', NULL, '王婷', '2013-08-22 19:22:31.000000', NULL, 1, '/1/50/', 48, 1, 0, 550.0000, '1611000001');
INSERT INTO `visa_information` VALUES (62, 'V10061', '1812000014', 1, '新加坡签证', 1, 2, 5, 1, 1, '新加坡', '/34/', '2', 400.0000, 0.0000, '5个工作日', '新加坡签证分快捷和非快捷城市，有效期最少35天，最长2年，旺季新签受理时间延长1-2个工作日', '最少35天', '30天', '多次', 0, '半年以上有效护照原件+近6个月彩色白底2寸照片2张+身份证复印件+户口本复印件+在职证明原件+英文表格（学生提供学生证复印件，儿童提供出生证明复印件，老人提供退休证复印件，无业人员提供存款证明复印件）\r\n备注：新加坡签证分快捷和非快捷城市，有效期最少35天，最长2年，旺季新签受理时间延长1-2个工作日', '半年以上有效护照原件+近6个月彩色白底2寸照片2张+身份证复印件+户口本复印件+在职证明原件+英文表格（学生提供学生证复印件，儿童提供出生证明复印件，老人提供退休证复印件，无业人员提供存款证明复印件）\r\n备注：新加坡签证分快捷和非快捷城市，有效期最少35天，最长2年，旺季新签受理时间延长1-2个工作日', 'Files/pic/34/20/636517266077155031.jpg', NULL, '1610000002', '管理员', '2013-08-22 19:29:47.000000', '1610000002', '管理员', '2013-08-22 19:35:43.000000', NULL, '王婷', '2013-08-22 19:35:53.000000', '/1/50/', 1, '/1/50/', 48, 1, 0, 300.0000, '1611000001');
INSERT INTO `visa_information` VALUES (63, 'V10062', '1812000014', 1, '柬埔寨电子签证', 1, 2, 5, 1, 1, '柬埔寨', '/35/', '2', 450.0000, 0.0000, '4个工作日', '全国受理，此签证为电子签证，如遇领馆休假，工作日顺延，不含来回快递时间', '3个月', '30天', '1', 0, '半年以上有效护照彩色扫描件+彩色白底2寸照片扫描件即可\r\n（全国受理，此签证为电子签证）', '半年以上有效护照彩色扫描件+彩色白底2寸照片扫描件即可\r\n（全国受理，此签证为电子签证）', 'Files/pic/35/21/636517266658485111.jpg', NULL, '1610000002', '管理员', '2013-08-23 19:35:21.000000', '1610000002', '管理员', '2013-08-23 19:38:59.000000', NULL, '王婷', '2013-08-23 19:39:13.000000', NULL, 1, '/1/50/', 48, 1, 0, 350.0000, '1611000001');
