INSERT INTO `visa_information` VALUES (65, 'V10064', '1812000014', 1, '菲律宾签证', 1, 2, 5, 1, 1, '菲律宾', '/5/', '2', 650.0000, 0.0000, '7个工作日', '上海领区：江、浙、沪、皖、鄂以上领区以外护照提供暂住证也不予办理，如遇领馆休假，工作日顺延，不含来回快递时间', '3个月', '14天', '1', 0, '半年以上有效护照原件+近6个月彩色白底2寸照片2张+英文表格+在职证明原件（18岁以下未成年人必须父母陪同办理签证，提供出生证明复印件，退休人员、无业人员提供不出在职证明必须提供资产证明1.房产证复印件2.信用卡正反面复印件3.存款证明原件 5万以上，如遇领馆休假，工作日顺延，不含来回快递时间）如之前申请过菲律宾个签须提供之前的签证原件', '半年以上有效护照原件+近6个月彩色白底2寸照片2张+英文表格+在职证明原件（18岁以下未成年人必须父母陪同办理签证，提供出生证明复印件，退休人员、无业人员提供不出在职证明必须提供资产证明1.房产证复印件2.信用卡正反面复印件3.存款证明原件 5万以上，如遇领馆休假，工作日顺延，不含来回快递时间）如之前申请过菲律宾个签须提供之前的签证原件', 'Files/pic/5/22/636517267272244462.jpg', NULL, '1610000002', '管理员', '2013-08-23 20:38:41.000000', '1610000002', '管理员', '2013-08-23 20:44:10.000000', NULL, '王婷', '2013-08-23 20:44:26.000000', NULL, 1, '/1/50/', 48, 1, 1, 350.0000, '1611000001');
